import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-b1-001","clusterId":"B","werkstueckRef":"B.1","stufe":1,"question":"Eine Kollegin ist überzeugt, ihr neuer Kollege sei unzuverlässig. Seit Wochen sammelt sie jede seiner Verspätungen und erzählt davon. Dass er gestern ein Projekt pünktlich und sauber abgeliefert hat, nennt sie „reinen Zufall“. Was ist an ihrem Vorgehen am ehesten fehlerhaft?","options":["Sie übernimmt ihr Urteil, weil die meisten im Team es teilen, und folgt damit der Mehrheit statt eigenen Gründen.","Sie beruft sich auf das Urteil einer Vorgesetzten, ohne zu prüfen, ob diese den Kollegen überhaupt gut genug kennt.","Sie sucht, deutet und behält Informationen so, dass sie ihr bestehendes Urteil stützen, und wertet Gegenteiliges ab.","Sie sieht in seinen Verspätungen die Ursache von Problemen im Team, obwohl beides nur zeitlich zusammen auftritt."],"correctIndex":2,"explanation":"Die Kollegin prüft ihr Urteil nicht, sie dekoriert es. Sie sammelt gezielt, was passt (einseitige Suche), und erklärt den Gegenbeleg zum „Zufall“ (einseitige Deutung). Auch die Erinnerung läuft bei diesem Muster typischerweise einseitig: Gründe für die eigene Seite werden eher gefunden und behalten. Das ist der Bestätigungsfehler: keine bloße Sturheit, sondern ein Verarbeitungsmuster auf diesen drei Ebenen. Es fehlt vor allem eines: der ernsthafte Versuch, das eigene Urteil zu widerlegen. Sich der Mehrheit anzuschließen, sich auf eine Autorität zu berufen oder Zeitliches mit Ursächlichem zu verwechseln, sind echte Denkfehler. Im Fall der Kollegin kommt aber weder eine Gruppenmeinung noch eine Autorität noch ein Problem im Team vor; sie wertet ihr Urteil selbst durch einseitige Auswahl auf.","coreRule":"⚡ Suche zuerst nach dem stärksten Beleg gegen deine Position, nicht nach dem nächsten dafür.","quote":"Er hat nicht ermittelt. Er hat nur seine anfängliche Vermutung dekoriert.","quoteLabel":"Merksatz:","beleg":"Werkstück B.1 (Der Detektiv und der Gärtner; Kernidee; Kontext & Tiefe, drei Ebenen)","status":"entwurf","scenario":"","kurz":"Sie sucht und deutet nur so, dass ihr Urteil bestehen bleibt: Verspätungen werden gesammelt, der pünktliche Erfolg wird zum „Zufall“ erklärt. So kann nichts mehr widerlegen, was sie schon glaubt.","prueffrage":"Was müsste der Kollege tun, damit sie ihr Urteil über ihn ändern würde?","rueckmeldung":[{"option":0,"text":"Sich der Mehrheit anzuschließen wäre ein echter Denkfehler. In der Schilderung findet sich aber keine Gruppenmeinung, nach der sie sich richtet: Sie sammelt und deutet selbst."},{"option":1,"text":"Sich blind auf eine Autorität zu stützen wäre problematisch. Hier kommt aber keine Vorgesetzte vor; der Fehler liegt darin, wie sie selbst Belege auswählt und deutet."},{"option":3,"text":"Ursache und bloßes Zusammentreffen zu verwechseln ist ein typischer Fehler, trifft hier aber nicht zu: Von Problemen im Team ist keine Rede. Es geht um die einseitige Auswahl und Deutung von Belegen."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175, 178","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson (1998), Verlagsfassung APA","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7ed6d86ba4a96918"}},{"id":"qx-b1-002","clusterId":"B","werkstueckRef":"B.1","stufe":2,"question":"Was ist an diesem Vorgehen das Hauptproblem?","scenario":"Du willst einen Staubsaugerroboter kaufen und hast dich schon in ein Modell verliebt. Abends gibst du in die Suchmaschine „Modell X Vorteile“ und „Modell X begeisterte Erfahrungsberichte“ ein.","options":["Du formulierst die Suche so, dass sie nur nach Zustimmung fragt, sodass das Ergebnis schon vorgegeben ist, bevor etwas gelesen wird.","Du vergleichst zu viele Modelle, sodass das Überangebot eine Entscheidung am Ende eher erschwert als erleichtert.","Du schließt vom hohen Preis des Modells auf seine Qualität, sodass der Preis dein Urteil schon vorab bestimmt.","Du lässt dich von einem Testsiegel überzeugen, ohne zu prüfen, wer es vergeben hat, sodass das Urteil auf Vertrauen beruht."],"correctIndex":0,"explanation":"Wer „Modell X Vorteile“ und „Modell X begeisterte Erfahrungsberichte“ eingibt, fragt nicht nach Belegen gegen das Modell, sondern nach Argumenten dafür. Das ist die tendenziöse Suche: Wir googeln nicht „Beweise gegen meine Position“, sondern „Argumente für meine Position“. Das Problem liegt hier auf der Ebene der Suche, noch bevor Deutung oder Erinnerung ins Spiel kommen. Eine Suche, die die Entscheidung wirklich prüft, würde gezielt auch nach „Kritik“, „Probleme mit“ oder „Gegenargumenten“ fragen. Ein Überangebot an Modellen, der Schluss vom Preis auf die Qualität und blindes Vertrauen in Siegel sind echte Stolpersteine beim Kauf. Hier gibt es aber nur ein einziges Wunschmodell, keinen genannten Preis und kein Siegel; die Schieflage steckt in den Suchbegriffen.","coreRule":"⚡ Schon die Wahl der Suchbegriffe kann das Ergebnis vorwegnehmen: Wer nur nach Bestätigung fragt, findet nur Bestätigung.","beleg":"Werkstück B.1 (Kontext & Tiefe, Ebene „Suche“; Werkbank-Frage)","status":"entwurf","kurz":"Mit „Vorteile“ und „begeisterte Erfahrungsberichte“ fragst du nur nach Zustimmung, also kann die Suche fast nur Bestätigendes liefern. Eine echte Prüfung würde auch nach „Kritik“ und „Probleme mit“ suchen.","prueffrage":"Welche Wörter stehen in den beiden Suchanfragen, und nach welchen Wörtern wird dort gar nicht gesucht?","rueckmeldung":[{"option":1,"text":"Zu viele Modelle können eine Entscheidung tatsächlich erschweren. Hier gibt es aber nur ein einziges Wunschmodell, und es wird gar nichts verglichen. Die Schieflage entsteht allein durch die Suchbegriffe."},{"option":2,"text":"Vom Preis auf die Qualität zu schließen, ist ein bekannter Denkfehler. Im Szenario kommt aber kein Preis vor. Was das Urteil verzerrt, sind die Suchbegriffe, die schon vor dem Lesen nur Zustimmung abfragen."},{"option":3,"text":"Ein ungeprüftes Testsiegel wäre ein echter Stolperstein beim Kauf. Hier taucht aber kein Siegel auf. Das Problem liegt eine Stufe früher: Die Suche ist so formuliert, dass sie nur Zustimmendes finden kann."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1e7d7064dcb37b69"}},{"id":"qx-b1-003","clusterId":"B","werkstueckRef":"B.1","stufe":3,"question":"Ein Freund investiert seit Jahren in ein Finanzsystem, das hohe Renditen garantiert. Mehrere Bekannte haben ihr Geld verloren, eine Verbraucherzentrale warnt, und die Auszahlungen stocken. Er sagt trotzdem: „Das sind alles Neider, mein System funktioniert.“ Warum ist sein Festhalten hier ein ernstes Problem und nicht nur eine harmlose Eigenart?","options":["Weil ihm schlicht die Informationen über das System fehlen und wer zu wenig weiß, mit seinen Entscheidungen leicht Schaden anrichtet.","Weil er sich nur unter Gleichgesinnten bewegt, die ihn bestärken, und der Gruppendruck dieses Umfelds ihn vom Umdenken abhält.","Weil es hier um ein wichtiges Thema geht und er trotz deutlicher Gegenbeweise nicht umdenkt, weil ihm sein Weltbild wichtiger ist.","Weil er seine Überzeugung auf ein einzelnes Erlebnis stützt und aus diesem Einzelfall auf die Wirksamkeit des ganzen Systems schließt."],"correctIndex":2,"explanation":"Einseitige Informationsverarbeitung ist an sich oft harmlos: Wer glaubt, die eigene Fußballmannschaft sei die beste, richtet damit kaum Schaden an. Gefährlich wird es, wenn zwei Dinge zusammenkommen: Es geht um ein wichtiges Thema, und überwältigende Gegenbeweise ändern nichts mehr an der Meinung. Dann wird der Schutz des eigenen Weltbildes wichtiger als die Anerkennung der Realität, und Menschen bleiben in betrügerischen Finanzsystemen, folgen gefährlichen Kulten oder lehnen medizinisch notwendige Behandlungen ab. Entscheidend sind das wichtige Thema und die Unbeweglichkeit gegenüber überwältigenden Gegenbeweisen. Fehlende Information ist hier nicht das Problem, denn die Warnungen und die stockenden Auszahlungen kennt er und schlägt sie trotzdem in den Wind. Von einem bestärkenden Umfeld oder von Gruppendruck ist im Fall keine Rede. Von einem einzelnen Erlebnis als Grundlage ebenso wenig; gegen sein System sprechen vielmehr mehrere unabhängige Hinweise.","coreRule":"⚡ Kritisch wird es bei wichtigen Themen, wenn Gegenbeweise nichts mehr bewegen.","beleg":"Werkstück B.1 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Entscheidend ist nicht die einseitige Sicht an sich, sondern die Kombination: ein folgenreiches Thema und mehrere unabhängige Gegenhinweise, die ihn nicht bewegen. Dann schützt er sein Weltbild statt sein Geld.","prueffrage":"Welche Warnzeichen liegen ihm schon vor, und wie erklärt er sie sich?","rueckmeldung":[{"option":0,"text":"Fehlendes Wissen kann tatsächlich zu schlechten Entscheidungen führen. Hier kennt er aber die Verluste der Bekannten, die Warnung und die stockenden Auszahlungen und wertet sie ab. Es mangelt nicht an Information, sondern am Umgang mit ihr."},{"option":1,"text":"Ein bestärkendes Umfeld kann Festhalten verstärken. Davon steht im Fall aber nichts: Von Gleichgesinnten oder Gruppendruck ist keine Rede. Entscheidend ist, dass er sich trotz deutlicher Gegenbeweise bei einem wichtigen Thema nicht bewegt."},{"option":3,"text":"Aus einem Einzelfall auf das Ganze zu schließen, wäre ein eigener Denkfehler. Hier fehlt aber ein solches Einzelerlebnis: Gegen das System sprechen mehrere unabhängige Hinweise, die er alle beiseiteschiebt."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9055720c0d05817e"}},{"id":"qx-b1-004","clusterId":"B","werkstueckRef":"B.1","stufe":4,"question":"Welche Einschätzung dieser Reaktion trifft zu?","scenario":"Du erzählst einem Bekannten, dass eine Behörde seine Behauptung über eine geheime Absprache geprüft und widerlegt hat. Er antwortet: „Genau das würden sie ja sagen – das beweist es erst recht!“","options":["Er greift einen Strohmann an, indem er statt der tatsächlichen Aussage der Behörde eine verzerrte Version widerlegt.","Er deutet auch die Widerlegung als weiteren Beleg um, sodass nichts mehr gegen seine Überzeugung sprechen kann.","Er beruft sich auf eine Autorität, indem er seine Behauptung damit stützt, dass eine anerkannte Stelle sie bestätigt habe.","Er folgt dem Mitläufereffekt, indem er an seiner Überzeugung festhält, weil viele andere in seinem Umfeld sie ebenfalls teilen."],"correctIndex":1,"explanation":"Wenn auch die Widerlegung als Beweis gilt, wird der Glaube zur „sich selbst versiegelnden Schleife“: Jedes Ereignis, egal wie unzusammenhängend, wird als weiterer Beweis gedeutet. Das ist der Bestätigungsfehler, die Neigung, Informationen so zu deuten, dass sie die eigene Überzeugung stützen. Eine hilfreiche Gegenfrage lautet: Welches Ergebnis würde er überhaupt als Widerlegung gelten lassen? Die Aussage der Behörde gibt er nicht verzerrt wieder, er deutet sie um, ein Strohmann liegt also nicht vor. Er beruft sich auch nicht auf eine Autorität, sondern lehnt gerade diese ab. Und von anderen, deren Meinung er übernähme, ist im Gespräch keine Rede.","coreRule":"⚡ Wenn selbst die Widerlegung als Bestätigung zählt, kann nichts mehr gegen die Überzeugung sprechen.","beleg":"Werkstück B.1 (Anwendung & Relevanz: Bei Verschwörungsmythen)","status":"entwurf","kurz":"Wenn auch die Widerlegung als Beweis zählt, kann nichts mehr gegen die Überzeugung sprechen: Jedes Ereignis wird passend gedeutet. Der naheliegende Fehler ist, das für besonders starke Gewissheit zu halten, obwohl sich die Überzeugung damit gegen jede Prüfung abschirmt.","prueffrage":"Welche neue Information über die Absprache bringt der Bekannte vor, nachdem er von der Prüfung gehört hat?","rueckmeldung":[{"option":0,"text":"Ein Strohmann setzt voraus, dass die Aussage der Behörde verzerrt wiedergegeben wird. Hier wird sie aber unverändert hingenommen und nur umgedeutet, nämlich als Beweis für die eigene Sicht."},{"option":2,"text":"Eine Autorität wird hier gerade nicht als Stütze herangezogen: Die Behörde widerspricht der Behauptung, und er lehnt ihr Ergebnis ab. Von einer Bestätigung durch eine anerkannte Stelle kann keine Rede sein."},{"option":3,"text":"Beim Mitläufereffekt hält jemand an einer Meinung fest, weil viele andere sie teilen. Im Gespräch kommt aber niemand sonst vor; sein Festhalten begründet er allein damit, dass die Widerlegung die Behauptung angeblich bestätigt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"178","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5e3a1dab4d0c84cb"}},{"id":"qx-b1-005","clusterId":"B","werkstueckRef":"B.2","stufe":1,"question":"Eine Kollegin stellt nach drei Wochen Einarbeitung fest: „Ich habe die Fehler in meinem Bericht gar nicht bemerkt. Ich hielt ihn für einwandfrei, dabei war er voller Mängel.“ Welche Erklärung für diese Lage ist am sparsamsten?","options":["Sie hat schwach gearbeitet und besitzt zugleich noch nicht die Fähigkeiten, die nötig sind, um die eigenen Fehler zu bemerken.","Sie hat schwach gearbeitet und stand unter hohem Zeitdruck, sodass sie beim Gegenlesen Fehler übersah, die sie sonst bemerkt hätte.","Sie hat schwach gearbeitet und redet sich die Qualität bewusst schön, um ihr Selbstbild zu schützen, obwohl sie die Mängel ahnt.","Sie hat schwach gearbeitet und beim Prüfen nur nach Hinweisen gesucht, die ihre gute Meinung stützen, sodass ein Bestätigungsfehler wirkte."],"correctIndex":0,"explanation":"Hier greifen zwei Probleme ineinander: Die Leistung ist schlecht, und zugleich fehlt der Maßstab, um das zu merken. Die Fähigkeiten, die man für einen guten Bericht braucht, sind dieselben, die man braucht, um die Qualität eines Berichts zu beurteilen. Wer sie noch nicht hat, kann seine Fehler also nicht erkennen, und die Selbstsicherheit bleibt hoch. So beschreiben es Dunning und Kruger; wie viel davon echte metakognitive Blindheit und wie viel ein statistischer Effekt ist, ist in der Fachliteratur umstritten. In der Studie von Kruger und Dunning (1999) lag das schwächste Viertel beim 12. Perzentil und hielt sich für das 68., während das beste Viertel beim 86. lag und sich für das 74. hielt; das Problem trifft also die Schwächsten am härtesten. Zeitdruck wäre eine zusätzliche Annahme, die der Fall nicht hergibt, und bei Hast würde sie die Mängel eher ahnen. Auch Schönreden zum Schutz des Selbstbilds passt nicht, denn sie gibt die Mängel offen zu und hatte sie wirklich nicht bemerkt. Eine einseitige Suche nach Bestätigung müsste erst vorausgesetzt werden, während die fehlende Beurteilungsfähigkeit allein schon alles erklärt.","coreRule":"⚡ Wem das Können fehlt, dem fehlt oft auch der Maßstab, um das zu bemerken.","beleg":"Werkstück B.2 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Wer noch nicht kann, was einen guten Bericht ausmacht, kann auch nicht erkennen, dass seiner schlecht ist; das erklärt alles mit einer einzigen Annahme. Zusätzliche Ursachen wie Hast oder Selbsttäuschung wären unnötige Annahmen.","prueffrage":"Welche Annahmen musst du über die Kollegin treffen, die der Fall selbst gar nicht erwähnt?","rueckmeldung":[{"option":1,"text":"Hast kann Fehler durchaus begünstigen. Von Zeitdruck steht im Fall aber nichts, und wer in Eile ist, ahnt die Mängel eher. Die hohe Selbstsicherheit erklärt das nicht, und die Annahme ist überflüssig."},{"option":2,"text":"Selbstbildschutz gibt es tatsächlich. Hier setzt er aber voraus, dass sie die Mängel ahnt. Sie räumt jedoch offen ein, sie nicht bemerkt zu haben; ein bewusstes Schönreden müsste man also erst unterstellen."},{"option":3,"text":"Ein Bestätigungsfehler ist ein echter Mechanismus, im Fall aber nirgends angelegt. Man müsste erst annehmen, dass sie einseitig nach Bestätigung gesucht hat, während die fehlende Beurteilungsfähigkeit schon allein alles erklärt."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121"},{"typ":"doi","kurz":"Magnus, J. R.; Peresetsky, A. A. (2022): A Statistical Explanation of the Dunning–Kruger Effect. Frontiers in Psychology 13","oeffentlich":true,"doi":"10.3389/fpsyg.2022.840180","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nuhfer, E. u. a. (2016): Random Number Simulations Reveal How Random Noise Affects the Measurements and Graphical Portrayals of Self-Assessed Competency. Numeracy 9(1), Art. 4","oeffentlich":true,"doi":"10.5038/1936-4660.9.1.4","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"756a72f178581aae"}},{"id":"qx-b1-007","clusterId":"B","werkstueckRef":"B.2","stufe":2,"question":"Was verrät diese Szene über die Verlässlichkeit der Einschätzung deines Nachbarn?","scenario":"Dein Nachbar hat sich zwei Wochen lang Videos zur Gebäudestatik angesehen. Beim Hausbau erklärt er dem Bauingenieur, dessen Berechnungen seien „unnötig kompliziert“, und Experten seien ohnehin „alle gekauft“. Auf die Nachfrage, wie die Lasten im Dachstuhl verteilt werden, weicht er aus und wiederholt nur, er sehe das „ganz klar“.","options":["Seine große Gewissheit nach kurzer Beschäftigung und die pauschale Abwertung der Fachleute sprechen eher für Selbstüberschätzung als für echte Sachkenntnis.","Dass Fachleute sich gelegentlich irren, macht seine Skepsis gegenüber den Berechnungen berechtigt, denn auch ein Bauingenieur sollte nicht ungeprüft recht bekommen.","Dass er die Berechnungen als unnötig kompliziert empfindet, spricht dafür, dass sie tatsächlich überladen sind, denn gute technische Lösungen sind meist einfach.","Weil es um sein eigenes Haus geht, hat er starkes Eigeninteresse an einem guten Ergebnis, und das spricht dafür, dass er seine Aussagen sorgfältig geprüft hat."],"correctIndex":0,"explanation":"Wer nur kurz in ein komplexes Feld hineingeschaut hat, dem fehlen oft genau die Fähigkeiten, um die Lücken im eigenen Wissen zu erkennen; dann fühlt sich das wenige Gelernte wie ein vollständiges Bild an. Typische Anzeichen sind große Gewissheit nach kurzer Beschäftigung und das pauschale Abwerten von Fachleuten („alle gekauft“). Dazu passt, dass er der konkreten Sachfrage ausweicht: Echte Prüfung würde die Gegenargumente verstehen wollen, statt die Berechnungen als „unnötig kompliziert“ abzutun. Sicherheit allein sagt wenig darüber aus, ob jemand recht hat, und hier spricht die Konstellation eher für Selbstüberschätzung. Ob er im Einzelfall trotzdem etwas Richtiges sagt, bleibt offen und ließe sich nur an der Sache selbst prüfen. Dass Fachleute sich irren können, rechtfertigt Skepsis nur, wenn man einen konkreten Fehler benennen kann, und genau dem weicht er aus. Ob eine Berechnung unnötig kompliziert ist, kann nur beurteilen, wer sie versteht; dass gute Lösungen oft einfach sind, ersetzt dieses Verständnis nicht. Ein Eigeninteresse am guten Ergebnis sichert keine Sorgfalt, wenn er auf die Sachfrage keine Antwort hat.","coreRule":"⚡ Große Sicherheit nach kurzer Beschäftigung ist ein Warnzeichen, kein Qualitätsmerkmal.","beleg":"Werkstück B.2 (Red Flags; Anwendung & Relevanz: Das Betriebssystem der „Selber-Denker“)","status":"entwurf","kurz":"Große Gewissheit nach nur zwei Wochen Videos, die pauschale Abwertung der Fachleute und das Ausweichen vor der Sachfrage sprechen eher für Selbstüberschätzung. Sicherheit allein sagt wenig darüber aus, ob jemand recht hat.","prueffrage":"Was antwortet dein Nachbar, wenn man ihn bittet, seine Einschätzung an einem konkreten Bauteil zu erklären?","rueckmeldung":[{"option":1,"text":"Dass Fachleute sich irren können, stimmt, und Nachprüfen ist legitim. Skepsis trägt aber erst, wenn man einen konkreten Fehler benennen kann, und genau dem weicht er aus."},{"option":2,"text":"Gute technische Lösungen sind oft tatsächlich einfach. Ob eine Berechnung unnötig kompliziert ist, kann aber nur beurteilen, wer sie versteht, und dazu fehlt ihm sichtbar das Verständnis der Lastverteilung."},{"option":3,"text":"Beim eigenen Haus steht für ihn viel auf dem Spiel. Das sagt aber nichts über Sorgfalt: Wer bei der Frage nach der Lastverteilung nur ausweicht, zeigt nicht, dass er etwas geprüft hat."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Light, N. u. a. (2022): Knowledge overconfidence is associated with anti-consensus views on controversial scientific issues. Science Advances 8(29), eabo0038 (frei über PMC9299547)","oeffentlich":true,"doi":"10.1126/sciadv.abo0038","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e8cd9c2681bbd205"}},{"id":"qx-b1-008","clusterId":"B","werkstueckRef":"B.2","stufe":4,"question":"Wie weit trägt der Befund tatsächlich, und was ist an der Folgerung der Kommentatorin zu beanstanden?","scenario":"In einer Pressemitteilung heißt es: „Neue US-Befragung belegt: Wer dem wissenschaftlichen Konsens zu Impfungen, Gentechnik und Evolution am stärksten widerspricht, schätzt sein eigenes Wissen am höchsten ein, weiß im Mittel aber am wenigsten.“ Eine Kommentatorin schreibt dazu: „Damit ist bewiesen, dass Selbstüberschätzung die Ablehnung des Konsenses verursacht.“","options":["Der Befund zeigt nur, dass Merkmale gemeinsam auftreten, und sagt nichts darüber, was Ursache und was Wirkung ist.","Der Befund zeigt, dass Selbstüberschätzung die Ablehnung des Konsenses verursacht, und gilt für alle Themen gleich stark.","Der Befund gilt nur für Menschen ohne Studium und verschwindet bei Befragten mit höherem Abschluss vollständig.","Der Befund zeigt, dass Wissen und Zustimmung zum Konsens nichts miteinander zu tun haben, weil beide unabhängig sind."],"correctIndex":0,"explanation":"Die Kommentatorin springt von einem Zusammenhang auf eine Ursache. Eine Befragung misst, welche Merkmale gemeinsam auftreten, nicht was woraus folgt: Denkbar ist, dass Selbstüberschätzung zur Ablehnung führt, dass die Ablehnung das Gefühl von Besserwissen verstärkt oder dass ein dritter Faktor beides erzeugt. Dazu kommt die Reichweite: Der beschriebene Befund stammt aus fünf Studien in den USA (Light u. a. 2022, Science Advances) zu sieben Themen mit wissenschaftlichem Konsens, und bei stark politisierten Themen, vor allem beim Klimawandel, war der Zusammenhang schwächer. Ein „bewiesen“ und ein „gilt überall gleich“ gehen also weiter, als die Daten tragen. Ebenso wenig folgt ein Bildungsgefälle oder gar Unabhängigkeit: Der Befund beschreibt gerade einen Zusammenhang zwischen Selbsteinschätzung, tatsächlichem Wissen und Haltung zum Konsens. Als Waffe gegen Andersdenkende taugt er nicht.","coreRule":"⚡ Ein Zusammenhang aus Befragungen zeigt, was zusammen auftritt, nicht was woraus folgt.","beleg":"Werkstück B.2 (Anwendung & Relevanz); Fn. gl-b-light (Light u. a. 2022, Science Advances 8(29), eabo0038)","status":"entwurf","kurz":"Eine Befragung zeigt, was gemeinsam auftritt, nicht was woraus folgt. Selbstüberschätzung könnte die Ablehnung fördern, die Ablehnung das Besserwisser-Gefühl, oder ein dritter Faktor beides. „Bewiesen“ ist deshalb zu viel.","prueffrage":"Wurde bei den Befragten etwas gezielt verändert und die Folge beobachtet, oder wurde erfragt, was sie wissen und meinen?","rueckmeldung":[{"option":1,"text":"Die Befragung beschreibt, welche Merkmale zusammen auftreten, nicht, was welches verursacht. Der Zusammenhang war zudem nicht überall gleich stark: Bei stark politisierten Themen wie dem Klimawandel fiel er schwächer aus."},{"option":2,"text":"Von einer Beschränkung auf Menschen ohne Studium ist nirgends die Rede, und ein vollständiges Verschwinden bei höherem Abschluss ist nicht belegt. Ein Bildungsgefälle lässt sich aus dem Befund nicht ablesen."},{"option":3,"text":"Dass ein Zusammenhang keine Ursache beweist, heißt nicht, dass es keinen gibt. Der Befund beschreibt gerade einen Zusammenhang zwischen Selbsteinschätzung, Wissen und Haltung zum Konsens; Wissen und Zustimmung sind also nicht unabhängig."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Light, N.; Fernbach, P. M.; Rabb, N.; Geana, M. V.; Sloman, S. A. (2022): Knowledge overconfidence is associated with anti-consensus views on controversial scientific issues. Science Advances 8(29), eabo0038 (frei über PMC9299547)","oeffentlich":true,"doi":"10.1126/sciadv.abo0038","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"bc121ae099221fbb"}},{"id":"qx-b1-009","clusterId":"B","werkstueckRef":"B.3","stufe":1,"question":"Welche Einschätzung ist hier am ehesten ein Fehlschluss und warum?","options":["Sie schätzt das Hai-Risiko nach der Lebhaftigkeit der Bilder ein, die ihr leicht in den Sinn kommen, nicht nach der tatsächlichen Häufigkeit der Ereignisse.","Sie schätzt das Hai-Risiko nach der ersten Zahl ein, die ihr in den Nachrichten begegnet ist, und bleibt an dieser Zahl hängen, statt sie zu überprüfen.","Sie schätzt das Hai-Risiko nach der Meinung ihres Umfelds ein, in dem alle ebenfalls vor dem Baden zurückschrecken, und übernimmt diese Haltung ungeprüft.","Sie schätzt das Hai-Risiko danach ein, wie vorhersehbar der Angriff im Rückblick wirkt, und hält die Gefahr deshalb für leicht erkennbar."],"correctIndex":0,"explanation":"Mara beurteilt die Wahrscheinlichkeit danach, wie leicht ihr Beispiele einfallen. Ein dramatischer, frisch gesehener Fall mit starken Bildern ist mental sehr präsent, die Gefahr der Autofahrt dagegen nur eine blasse, abstrakte Statistik. Das Risiko, auf der Fahrt tödlich zu verunglücken, ist statistisch um ein Vielfaches höher als das, von einem Hai getötet zu werden. Leichtigkeit des Abrufs hängt von Emotionalität, Lebhaftigkeit, zeitlicher Nähe und medialer Wiederholung ab, nicht nur von der tatsächlichen Häufigkeit (Tversky und Kahneman, 1974). Hier liegt die Verfügbarkeitsheuristik vor. Ein Ankereffekt setzt eine genannte Zahl voraus, und im Szenario kommt keine vor. Dass ihr Umfeld ihre Haltung prägt, steht nirgends; sie begründet ihre Angst mit den Nachrichten der letzten Woche. Ein Rückblick auf einen Angriff, den man hätte vorhersehen können, ist ebenfalls nicht ihr Thema, denn sie beurteilt die Gegenwart.","coreRule":"⚡ Was mir leicht einfällt, erscheint mir wahrscheinlicher und wichtiger, auch wenn die Statistik etwas anderes sagt.","beleg":"Werkstück B.3 (Kernidee; Kontext & Tiefe); Fn. gl-b-verfuegbarkeit (Tversky/Kahneman 1974, Science 185(4157), S. 1127); Fn. gl-b-hai-auto (International Shark Attack File; NHTSA 2024, Overview of Motor Vehicle Traffic Crashes in 2022)","status":"entwurf","scenario":"Nach einer Woche voller Nachrichten über einen Hai-Angriff an einem Küstenort sagt Mara: „Ich gehe dort nicht mehr ins Wasser, das ist mir zu gefährlich.“ Am selben Tag fährt sie ohne zu zögern mit dem Auto zum Supermarkt. Ein Freund hält ihr vor, ihre Risikoeinschätzung sei verzerrt.","kurz":"Mara misst die Gefahr daran, wie leicht ihr dramatische Fälle einfallen, nicht daran, wie oft sie vorkommen. Der Hai-Angriff ist bildstark und frisch, die Autofahrt bleibt eine blasse Statistik, obwohl sie viel häufiger tödlich endet.","prueffrage":"Was genau hat Mara in dieser Woche erfahren: eine Zahl, die Meinung von Bekannten oder Berichte über einen Fall?","rueckmeldung":[{"option":1,"text":"Die Nachrichten prägen Maras Urteil durchaus. Ein Ankereffekt bräuchte aber eine genannte Zahl, an der sie hängen bleibt, und im Szenario kommt keine vor: Sie reagiert auf den Fall und seine Bilder."},{"option":2,"text":"Dass andere Menschen unser Urteil beeinflussen, ist ein häufiger Grund für Fehleinschätzungen. Im Szenario steht aber nichts über ihr Umfeld. Mara beruft sich allein auf die Nachrichten der letzten Woche."},{"option":3,"text":"Beim Rückschaufehler wirkt ein Ereignis im Nachhinein vorhersehbar. Mara blickt aber nicht auf den Angriff zurück, sondern beurteilt ihr Risiko für die Zukunft, wenn sie dort badet."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Florida Museum of Natural History, International Shark Attack File: Beach Injuries & Fatalities (Daten USLA, Stand Februar 2001)","oeffentlich":true,"url":"https://www.floridamuseum.ufl.edu/shark-attacks/odds/compare-risk/beach-injuries-fatalities/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHTSA (2024): Overview of Motor Vehicle Traffic Crashes in 2022. DOT HS 813 560","oeffentlich":true,"url":"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813560","seite":"1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"bf1fafe162d5f8d2"}},{"id":"qx-b1-010","clusterId":"B","werkstueckRef":"B.3","stufe":2,"question":"Was ist an der Schlussfolgerung deiner Kollegin fehlerhaft, und wie schätzt du dein Risiko stattdessen sinnvoll ein?","scenario":"Seit drei Tagen berichtet die Lokalpresse täglich über Wohnungseinbrüche in deiner Stadt, mit Fotos aufgebrochener Türen. Du merkst, dass du dich abends plötzlich unsicher fühlst. Eine Kollegin sagt: „Wenn ständig darüber berichtet wird, muss es ja wirklich häufiger geworden sein.“","options":["Sie schließt aus der Menge der Berichte auf die Häufigkeit der Fälle, obwohl Berichte nur zeigen, was die Redaktion aufgreift; du prüfst deshalb die langfristigen Zahlen für deinen Wohnort.","Sie überträgt die Lage deiner Stadt unzulässig auf das ganze Land, obwohl sich Regionen stark unterscheiden; du prüfst deshalb die Zahlen anderer Städte und Bundesländer.","Sie sucht gezielt nach Berichten, die ihre Sorge bestätigen, und blendet Beruhigendes aus; du liest deshalb auch Meldungen, die zur Gelassenheit beitragen.","Sie vertraut einer einzelnen Quelle zu stark, obwohl auch Lokalzeitungen sich irren können; du vergleichst deshalb mit der Berichterstattung einer überregionalen Zeitung."],"correctIndex":0,"explanation":"Wie viel über ein Thema berichtet wird, sagt zunächst etwas über die Berichterstattung, nicht über die Häufigkeit des Ereignisses selbst. Wiederholung und eindrückliche Bilder machen Fälle im Kopf leicht abrufbar, und was uns leicht einfällt, halten wir gern für häufig oder wahrscheinlich: die Verfügbarkeitsheuristik. Diese Faustregel ist im Alltag oft brauchbar, führt bei statistischen Risiken aber leicht in die Irre; ständige Berichte über Kriminalität können das Gefühl einer gefährlichen Welt erzeugen, selbst wenn die Kriminalitätsstatistiken sinken. Die passende Gegenfrage lautet: Was sagen die langfristigen, nüchternen Zahlen zur tatsächlichen Häufigkeit? Das Unsicherheitsgefühl ist dabei real, ersetzt aber keine Messung. Eine Übertragung auf das ganze Land findet im Gespräch nicht statt, es geht nur um deine Stadt. Die Kollegin sucht auch nicht gezielt nach Bestätigung, sie deutet, was ihr täglich begegnet. Und eine weitere Zeitung würde vermutlich dieselben Fälle zeigen und damit nichts über die Häufigkeit sagen.","coreRule":"⚡ Wenn die Nachrichten laut sind, frag die langweilige Statistik.","quote":"Was sagen die langfristigen, langweiligen Statistiken über die tatsächliche Häufigkeit dieses Ereignisses?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.3 (Kontext & Tiefe: Mediale Wiederholung; Das Adaptive Talent; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wie viel berichtet wird, sagt etwas über die Berichterstattung, nicht über die Häufigkeit der Einbrüche. Eindrückliche Fälle fallen uns leicht ein, und wir halten sie dann für häufig. Verlässlicher sind die langfristigen Zahlen für deinen Wohnort.","prueffrage":"Über wie viele Einbrüche wurde in den drei Tagen berichtet, und woran erkennst du, ob das mehr sind als sonst?","rueckmeldung":[{"option":1,"text":"Dass sich Regionen stark unterscheiden, stimmt. Hier aber geht es nur um deine Stadt, auf das ganze Land wird nichts übertragen. Zahlen anderer Städte sagen nichts darüber, wie häufig Einbrüche bei dir wirklich sind."},{"option":2,"text":"Bestätigungssuche ist ein bekannter Fehler und Gelassenheit hilft. Die Kollegin sucht aber nichts gezielt aus, ihr begegnen die Berichte täglich und sie deutet sie. Ihr Schluss trägt nicht, weil Berichte keine Häufigkeit messen."},{"option":3,"text":"Auch Lokalzeitungen können sich irren, und Quellen zu vergleichen ist grundsätzlich sinnvoll. Hier liegt das Problem aber nicht in falschen Berichten: Eine überregionale Zeitung würde vermutlich dieselben Fälle zeigen und nichts über die Häufigkeit verraten."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Pew Research Center (2016): Voters' perceptions of crime continue to conflict with reality","oeffentlich":true,"url":"https://www.pewresearch.org/short-reads/2016/11/16/voters-perceptions-of-crime-continue-to-conflict-with-reality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Availability Heuristic“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"76f8fbb829dc80c3"}},{"id":"qx-b1-011","clusterId":"B","werkstueckRef":"B.3","stufe":3,"question":"Welche Schlussfolgerung zieht diese Auswertung am besten, ohne mehr in sie hineinzulesen, als sie hergibt?","options":["Das Risiko, im Meer zu ertrinken, und das Risiko im Straßenverkehr sind beide höher als das Risiko, von einem Hai getötet zu werden.","Das Risiko im Straßenverkehr ist höher als das Risiko, im Meer zu ertrinken, deshalb ist die Fahrt zum Strand gefährlicher als das Baden.","Das Hai-Risiko an bewachten Stränden ist gleich null, denn bei 264 Millionen Besuchen starb niemand; Warnungen sind dort überflüssig.","Ertrinken ist am Strand die häufigste Todesursache überhaupt, denn die Auswertung zeigt mehr Ertrunkene als Hai-Opfer."],"correctIndex":0,"explanation":"Bei rund 264 Millionen Strandbesuchen starb niemand durch einen Hai, ertrunken ist dagegen etwa einer von 3,5 Millionen Besuchern. Die Bezugsgrößen passen nicht genau zusammen: Die meisten Ertrunkenen starben außerhalb der bewachten Abschnitte, und die Verkehrszahl bezieht sich auf gefahrene Meilen statt auf Strandbesuche. Genau verrechnen lassen sich die Zahlen deshalb nicht; die Rangfolge trägt trotzdem, weil in den Daten kein einziger Hai-Todesfall vorkommt, während Ertrinken und Straßenverkehr messbar Todesopfer fordern. Das Risiko mit dem lebhaftesten Bild ist also nicht das größte. Eine Gefahr zu relativieren heißt aber nicht, sie zu leugnen. Verkehr und Ertrinken haben verschiedene Bezugsgrößen, sodass sich nicht sagen lässt, welches von beiden gefährlicher ist. Kein beobachteter Todesfall ist noch kein Risiko von null, und die Zahlen betreffen ohnehin nur bewachte Strände. Dass mehr Menschen ertrinken als von Haien getötet werden, sagt nichts über alle anderen Todesursachen am Strand.","coreRule":"⚡ Das Risiko mit dem dramatischsten Bild ist selten das mit den meisten Opfern.","beleg":"Werkstück B.3 (Die Angst vor dem Hai); Fn. gl-b-hai-auto (USLA-Daten, Stand Februar 2001; NHTSA 2024, S. 1)","status":"entwurf","scenario":"Nach einem Hai-Angriff in den Nachrichten meiden viele Urlauber das tiefe Wasser. Eine Auswertung von Strandbesuchen in den USA zeigt: Bei rund 264 Millionen Besuchen an bewachten Ozeanstränden starb kein einziger Mensch durch einen Hai. Ertrunken ist dagegen etwa einer von 3,5 Millionen Besuchern, die meisten außerhalb der bewachten Abschnitte. Im US-Straßenverkehr starben 2022 rund 1,33 Menschen je 100 Millionen gefahrene Meilen.","kurz":"Kein Hai-Todesfall bei 264 Millionen Besuchen, aber messbar Ertrunkene und Verkehrstote: Die Rangfolge trägt. Der naheliegende Fehler ist, das Risiko mit dem eindrucksvollsten Bild zu verwechseln, obwohl sich Verkehr und Ertrinken nicht genau verrechnen lassen.","prueffrage":"Wie viele Todesfälle durch Haie nennt die Auswertung, und welche anderen Todesursachen beziffert sie?","rueckmeldung":[{"option":1,"text":"Der Verkehr fordert tatsächlich Todesopfer, ebenso das Ertrinken. Eine Rangfolge der beiden ergibt sich aber nicht, denn die eine Zahl bezieht sich auf gefahrene Meilen, die andere auf Strandbesuche; dazu kommt die unbekannte Länge der Anfahrt."},{"option":2,"text":"Ein sehr kleines Risiko lässt sich so gut belegen. Kein beobachteter Todesfall ist aber kein Beweis für ein Risiko von null, und die Zahlen betreffen nur bewachte Strände. Eine Gefahr zu relativieren heißt nicht, sie zu streichen."},{"option":3,"text":"Dass mehr Menschen ertrinken als von Haien getötet werden, stimmt nach diesen Zahlen. Daraus folgt aber keine Rangfolge unter allen Todesursachen am Strand, denn andere Ursachen kommen in der Auswertung gar nicht vor."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Florida Museum of Natural History, International Shark Attack File: Beach Injuries & Fatalities (Daten USLA, Stand Februar 2001)","oeffentlich":true,"url":"https://www.floridamuseum.ufl.edu/shark-attacks/odds/compare-risk/beach-injuries-fatalities/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHTSA (2024): Overview of Motor Vehicle Traffic Crashes in 2022. DOT HS 813 560","oeffentlich":true,"url":"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813560","seite":"1","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0336059b3695a0eb"}},{"id":"qx-b1-012","clusterId":"B","werkstueckRef":"B.3","stufe":4,"question":"Warum ist dein Eindruck, dass das Ritual funktioniert, so überzeugend, und was folgt daraus für die Bewertung?","scenario":"Du hast einmal im Stillen „um einen Parkplatz gebeten“ und sofort einen gefunden. Seitdem bist du überzeugt, dass das Ritual funktioniert. Auf Nachfrage räumst du ein, dass es in den allermeisten anderen Fällen nicht geklappt hat, du dich daran aber kaum erinnerst.","options":["Der Treffer ist lebhaft und leicht abrufbar, die Fehlschläge nicht; das Gefühl der Wirksamkeit sagt nichts über die Trefferquote aus.","Du hältst nach vielen Fehlschlägen einen Treffer für überfällig (Spielerfehlschluss); darum wirkt der nächste Versuch aussichtsreicher, als er ist.","Du verlässt dich auf Erzählungen anderer über das Ritual; solche Berichte aus zweiter Hand solltest du nach ihrer Quelle bewerten.","Du erklärst Fehlschläge nachträglich mit Störungen weg, sodass das Ritual nicht widerlegbar ist; es müsste so formuliert werden, dass es scheitern kann."],"correctIndex":0,"explanation":"Ein einzelner Zufallstreffer ist emotional und bildhaft, er fällt dir leicht wieder ein. Die vielen Fehlschläge sind unauffällig und verblassen. Weil uns leicht Abrufbares wichtig und häufig erscheint, entsteht der Eindruck von Wirksamkeit, ohne dass sich an der tatsächlichen Trefferquote etwas ändert. Man erinnert sich lebhaft an den einen Treffer und vergisst die hundert Male, bei denen es nicht funktioniert hat. Beurteilen lässt sich das Ritual deshalb nur an allen Versuchen, nicht an dem Treffer, der dir am lebhaftesten einfällt. Ein Spielerfehlschluss würde voraussetzen, dass du nach den Misserfolgen einen Treffer erwartest, doch überzeugt dich gerade der eine Treffer. Von Erzählungen anderer ist im Fall keine Rede, es geht um deinen eigenen Versuch. Und du erklärst die Fehlschläge nicht weg, sondern räumst sie auf Nachfrage ein.","coreRule":"⚡ Bewerte ein Ritual nach allen Versuchen, nicht nach dem Treffer, der dir am lebhaftesten einfällt.","beleg":"Werkstück B.3 (Anwendung & Relevanz: Bei Esoterik & Aberglaube)","status":"entwurf","kurz":"Der eine Treffer ist lebhaft und leicht abrufbar, die vielen Fehlschläge verblassen. Dieser Eindruck wirkt überzeugend, sagt aber nichts über die Trefferquote. Bewerten lässt sich das Ritual nur an allen Versuchen, nicht an dem einen, der dir am lebhaftesten einfällt.","prueffrage":"Wie viele Versuche gab es insgesamt, und bei wie vielen davon klappte es?","rueckmeldung":[{"option":1,"text":"Dass nach vielen Misserfolgen ein Treffer „fällig“ sei, ist ein bekannter Irrtum. Hier passt er aber nicht, denn überzeugt hat dich gerade der eine Treffer, nicht eine Pechsträhne, auf die du eine Wende erwartest."},{"option":2,"text":"Berichte aus zweiter Hand sollte man tatsächlich nach ihrer Quelle bewerten. Im Szenario geht es aber um deinen eigenen Versuch, von Erzählungen anderer ist keine Rede."},{"option":3,"text":"Nachträgliches Wegerklären macht Behauptungen unwiderlegbar, und eine prüfbare Formulierung wäre sinnvoll. Du erklärst hier aber nichts weg, sondern räumst die Fehlschläge ein; sie bleiben nur blass in der Erinnerung."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Availability Heuristic“, „Misleading Vividness“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"07b62691d1c7e7bc"}},{"id":"qx-b1-013","clusterId":"B","werkstueckRef":"B.4","stufe":2,"question":"Was ist an deiner Argumentation fehlerhaft?","scenario":"Nach einem Derby sagst du: „Die Fans des anderen Vereins sind doch alle gleich – grölen, pöbeln, werfen mit Bechern.“ Auf den Einwand, dass auch in deiner eigenen Fankurve ein paar Leute Becher werfen, antwortest du: „Ja, aber unsere Leute sind ganz verschieden: Familien, Rentner, Studenten, Ultras. Da kann man nicht pauschal urteilen.“","options":["Du misst mit zweierlei Maß: Die fremde Gruppe siehst du als gleichförmige Masse, die eigene als Vielfalt einzelner Menschen.","Du greifst die Person an, die den Einwand bringt: Statt auf ihr Argument einzugehen, stellst du ihre Glaubwürdigkeit infrage.","Du folgst der Mehrheit in deiner Fankurve: Das Urteil über die gegnerischen Fans übernimmst du, ohne es selbst zu prüfen.","Du stützt dich auf eine Autorität: Dein Urteil begründest du damit, dass Vereinsverantwortliche die gegnerischen Fans genauso sehen."],"correctIndex":0,"explanation":"Dieses Muster heißt Outgroup-Homogenität: Wir sehen die Mitglieder einer fremden Gruppe als stereotype, homogene Masse („Die sind doch alle gleich“), die Mitglieder der eigenen Gruppe dagegen als vielfältige, einzigartige Individuen. Genau das passiert in deiner Argumentation: Die gegnerischen Fans fasst du zu einem einheitlichen Typus zusammen, bei deiner eigenen Kurve differenzierst du sofort. Ob dein Urteil trägt, prüfst du mit der Frage: Wie würde ich diese Aussage bewerten, wenn sie von einem Mitglied meiner eigenen Gruppe käme? Auf den Einwand gehst du inhaltlich ein, statt die Person anzugreifen. Dass die Mehrheit deiner Kurve dir das Urteil vorgäbe, steht nirgends. Und du berufst dich auf keine Autorität, sondern auf deinen eigenen Eindruck.","coreRule":"⚡ Frag dich bei jeder Gruppe: Würde ich sie auch als „alle gleich“ beschreiben, wenn es meine eigene wäre? Wenn nicht, sprichst du über ein Klischee, nicht über Menschen.","quote":"„Die sind doch alle gleich.“","quoteLabel":"Typische Aussage:","beleg":"Werkstück B.4 (Kontext & Tiefe: Outgroup-Homogenität)","status":"entwurf","kurz":"Die gegnerischen Fans fasst du zu einer einheitlichen Masse zusammen, bei der eigenen Kurve differenzierst du sofort. Das ist zweierlei Maß: Eine fremde Gruppe wirkt gleichförmig, die eigene besteht aus vielen verschiedenen Menschen.","prueffrage":"Wer steht an einem Spieltag alles in der gegnerischen Kurve?","rueckmeldung":[{"option":1,"text":"Ein Einwand lässt sich tatsächlich auch dadurch abwehren, dass man den Absender schlechtmacht. Hier wird aber niemand persönlich angegriffen: Du gehst auf den Einwand ein, nur wendest du bei der eigenen Gruppe einen anderen Maßstab an."},{"option":2,"text":"Gruppendruck kann Urteile tatsächlich färben. Im Szenario steht aber nichts davon, dass die Kurve dir das Urteil vorgibt. Die Aussage stützt sich auf deinen eigenen Eindruck, der bei Fremden pauschal und bei den Eigenen differenziert ausfällt."},{"option":3,"text":"Ein Verweis auf Verantwortliche wäre ein Autoritätsargument, kommt hier aber nicht vor. Du stützt dich auf deinen eigenen Eindruck vom Derby. Der Fehler liegt darin, dass du die gegnerischen Fans pauschal, die eigenen aber differenziert beurteilst."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Castano, E.; Yzerbyt, V. Y. (1998): The highs and lows of group homogeneity. Behavioural Processes 42 (Kopie auf der Seite von V. Yzerbyt, UCLouvain)","oeffentlich":true,"url":"https://perso.uclouvain.be/vincent.yzerbyt/Castano%20&%20Yzerbyt%20BP%201998.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Quattrone, G. A.; Jones, E. E. (1980): The perception of variability within in-groups and out-groups. JPSP 38(1)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"351c94f54cb87f3e"}},{"id":"qx-b1-014","clusterId":"B","werkstueckRef":"B.4","stufe":1,"question":"Eine Schlagzeile erklärt das so: „Offenbar waren die Jungen schon vorher voller Vorurteile.“ Was spricht am stärksten gegen diese Erklärung?","options":["Die Jungen waren zuvor ganz normale Kinder, und die Feindseligkeit entstand erst im Lager, mit Gruppenbildung und Wettstreit.","Die Jungen stammten aus sehr unterschiedlichen sozialen Schichten, und die Feindseligkeit zeigte sich schon am ersten Tag.","Kinder in diesem Alter sind grundsätzlich zu jung, um Vorurteile zu entwickeln oder Feindseligkeit zu zeigen.","Die Jungen hatten sich zuvor nie gesehen, daher kann zwischen ihnen unmöglich Feindseligkeit entstanden sein."],"correctIndex":0,"explanation":"Die Erklärung „Vorurteile waren schon vorher da“ lässt sich an der zeitlichen Abfolge prüfen: Die Jungen waren vor dem Lager unauffällige Kinder und kannten einander nicht. Erst mit der Gruppenbildung und dem eigens inszenierten Wettkampf entstanden Abwertung, Flaggenverbrennung und Handgreiflichkeiten. Wenn sich ein Verhalten erst einstellt, nachdem die Umstände verändert wurden, liegt die Veränderung der Umstände als Ursache näher als eine verborgene Vorbelastung. Zugleich gilt: Der Wettstreit wurde von den Versuchsleitern gezielt konstruiert, und ein früherer Versuch (1953) scheiterte und wurde abgebrochen; nach Perrys Archivrecherche weigerten sich die Jungen dort, Feindseligkeit gegeneinander zu entwickeln. Das bekannte Lager war der dritte von drei Versuchen.","coreRule":"⚡ Passt eine Erklärung nicht zum zeitlichen Ablauf, prüfe zuerst, was sich unmittelbar vor der Wirkung verändert hat – und ob die Situation inszeniert wurde.","beleg":"Werkstück B.4 (Das Ferienlager-Experiment); Fn. gl-b-sherif (Sherif u. a. 1961, S. 18 und 96; Perry 2018)","status":"entwurf","scenario":"Zwei Gruppen unauffälliger elfjähriger Jungen, die sich vorher nie begegnet waren, verbringen Zeit in einem Ferienlager. Zuerst leben sie getrennt voneinander und geben sich eigene Namen und Flaggen. Dann lassen die Versuchsleiter sie in einem eigens entworfenen Wettkampf gegeneinander antreten. Im Verlauf dieses Wettkampfs beleidigen sich die Gruppen, verbrennen gegenseitig ihre Flaggen und werden handgreiflich.","kurz":"Feindseligkeit, die erst mit Gruppenbildung und inszeniertem Wettkampf auftritt, spricht eher für veränderte Umstände als Ursache als für verborgene Vorurteile. Die Schlagzeile schließt vom späteren Verhalten auf eine Vorbelastung und übersieht, was sich dazwischen änderte.","prueffrage":"Was taten die Jungen in der Zeit, als die beiden Gruppen noch getrennt lebten?","rueckmeldung":[{"option":1,"text":"Unterschiedliche Herkunft wirkt wie ein möglicher Nährboden für Vorurteile. Davon ist aber nirgends die Rede, und die Feindseligkeit zeigte sich erst mit Gruppenbildung und Wettkampf, nicht schon am ersten Tag."},{"option":2,"text":"Das Alter wirkt wie ein einfaches Argument, ist aber zu pauschal: Dass Kinder Feindseligkeit zeigen können, belegt schon das Ferienlager selbst. Gegen die Schlagzeile spricht die zeitliche Abfolge, nicht ein angeblich zu junges Alter."},{"option":3,"text":"Dass sich die Jungen nie gesehen hatten, stimmt, und es spricht gegen eine alte Vorgeschichte. Daraus folgt aber nicht, dass Feindseligkeit unmöglich wäre: Sie kann durchaus erst durch Umstände wie Wettkampf entstehen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Sherif, M. u. a. (1954/1961): Intergroup Conflict and Cooperation: The Robbers Cave Experiment, Vorwort 1954 (Classics in the History of Psychology, York University)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Sherif/preface1954.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Sherif, M. u. a. (1954/1961): The Robbers Cave Experiment, Kap. 3: Role of Staff, Subject Selection, Experimental Site (Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Sherif/chap3.htm","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Perry, G. (2018): The Lost Boys: Inside Muzafer Sherif's Robbers Cave Experiment. Melbourne: Scribe","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"595fe1951b353197"}},{"id":"qx-b1-015","clusterId":"B","werkstueckRef":"B.4","stufe":3,"question":"Welche Schlussfolgerung ist hier am besten begründet?","options":["Das stimmt nicht zwingend: Vorliebe für die eigene Gruppe kann ohne Abwertung anderer bestehen; Feindschaft braucht meist weitere Auslöser.","Die Behauptung stimmt: Wer die eigene Gruppe bevorzugt, wertet die anderen automatisch ab, denn mehr Wert für die einen bedeutet weniger Wert für die anderen.","Die Behauptung stimmt nur, wenn sich die Gruppen deutlich in Sprache, Kultur oder Aussehen unterscheiden und die Beteiligten diese Unterschiede bemerken.","Die Behauptung stimmt nur, wenn eine Gruppe deutlich größer und mächtiger ist als die andere, weil erst dieses Gefälle Ressentiments gegen die Stärkeren erzeugt."],"correctIndex":0,"explanation":"Die Behauptung setzt zwei Dinge gleich, die sich trennen lassen: Bevorzugung der eigenen Gruppe und Abwertung der fremden. Die Forschung (Brewer 1999) zeigt, dass Benachteiligung anderer allein aus der Vorliebe für die eigene Gruppe entstehen kann, ohne negative Gefühle oder feindselige Absicht gegenüber den anderen. Wer seinen Verein liebt, muss den Rivalen nicht verachten. Aus „A bevorzugt X“ folgt nicht „A wertet Y ab“. In Feindschaft kippt die Bindung erst unter zusätzlichen Bedingungen: wahrgenommene Bedrohung, Konkurrenz oder gezielte Aufhetzung durch Anführer. Wer „automatisch“ sagt, behauptet eine Notwendigkeit, wo es nur eine Möglichkeit gibt. Dagegen genügt ein einziges Gegenbeispiel, und genau das liefern die Befunde. Die übrigen Antworten nennen Voraussetzungen (auffällige Unterschiede, Machtgefälle), die in der Forschung nicht als nötig für Feindschaft belegt sind; belegt sind stattdessen Bedrohung, Konkurrenz und Aufhetzung.","coreRule":"⚡ Gruppenliebe ist nicht dasselbe wie Fremdenhass; sie kippt unter Bedrohung, Konkurrenz und Aufhetzung. Wer „zwangsläufig“ behauptet, muss zeigen, dass es keine Ausnahme gibt.","beleg":"Werkstück B.4 (Das Adaptive Talent); Fn. gl-b-brewer-kipp (Brewer 1999, Journal of Social Issues 55(3), S. 431, 434–438)","status":"entwurf","scenario":"In einer Diskussion über Fan-Rivalitäten sagt jemand: „Wer seinen Verein mehr liebt als andere Vereine, hasst die anderen automatisch. Liebe zur eigenen Gruppe und Hass auf die fremde sind dasselbe, nur von zwei Seiten betrachtet.“ Du sollst beurteilen, ob das stimmt.","kurz":"Vorliebe für die eigene Gruppe und Abwertung der anderen lassen sich trennen: Wer seinen Verein liebt, muss den Rivalen nicht verachten. Feindschaft entsteht meist erst durch Bedrohung, Konkurrenz oder Aufhetzung. „Automatisch“ macht aus einer Möglichkeit eine Notwendigkeit.","prueffrage":"Wann schlägt die Stimmung zwischen zwei Fanlagern tatsächlich in Feindseligkeit um, und wann bleibt es beim Necken?","rueckmeldung":[{"option":1,"text":"Dass Bevorzugung der eigenen Gruppe andere benachteiligen kann, stimmt. Abwertung oder Hass folgt daraus aber nicht: Wer den eigenen Verein höher stellt, muss den Rivalen nicht geringschätzen, und „automatisch“ behauptet eine Notwendigkeit."},{"option":2,"text":"Auffällige Unterschiede können Gruppengrenzen betonen. Als Voraussetzung für Feindschaft sind sie aber nicht belegt; belegt sind Bedrohung, Konkurrenz und Aufhetzung. Und Liebe und Hass blieben auch dann zwei verschiedene Dinge."},{"option":3,"text":"Ein Machtgefälle kann Groll erzeugen, aber als nötige Bedingung ist es nicht belegt; Konkurrenz, Bedrohung oder Aufhetzung wirken auch ohne Gefälle. Außerdem hielte auch diese Einschränkung an der Gleichsetzung von Liebe und Hass fest."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3) (inoffizielle Kopie auf Server des Bard College)","oeffentlich":true,"url":"https://bcsh.bard.edu/files/2019/06/Brewer-ingroup-love-or-outgroup-hate.pdf","seite":"431, 434–437","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3), Verlagsfassung","oeffentlich":false,"doi":"10.1111/0022-4537.00126"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"efd28c1962bcc242"}},{"id":"qx-b1-016","clusterId":"B","werkstueckRef":"B.4","stufe":4,"question":"Welche Prüffrage setzt am Kern dieses Musters an?","scenario":"Ein Skandal in der Partei, die du wählst, ist für dich eine „Kampagne der Gegner“. Derselbe Skandal bei der anderen Partei ist für dich ein Beweis ihrer moralischen Verkommenheit.","options":["Welche der beiden Parteien hat in den vergangenen Jahren mehr Skandale gehabt, und wie schwer wogen sie jeweils?","Wie verlässlich sind die Medien, die über beide Parteien berichten, und welche Seite behandeln sie schonender?","Gibt es für den Vorwurf belastbare Belege, und lässt er sich unabhängig von beiden Parteien überprüfen?","Würde ich dieselbe Handlung genauso bewerten, wenn die Rollen vertauscht wären und sie von der anderen Seite käme?"],"correctIndex":3,"explanation":"Das Muster ist ein doppelter Maßstab: Derselbe Vorgang gilt als „Kampagne“, wenn er die eigene Seite trifft, und als Beweis für „moralische Verkommenheit“, wenn er die andere trifft. Dahinter steckt die Gruppenzugehörigkeits-Verzerrung: Statt zu fragen, ob etwas wahr ist, fragt man, ob es der eigenen Seite nützt. Am Kern setzt an, wer seinen Maßstab auf die Probe stellt, indem er sich vorstellt, dieselbe Handlung käme von der anderen Seite, und prüft, ob das Urteil gleich bliebe. Fällt es anders aus, liegt die Asymmetrie in der Bewertung und nicht im Vorgang. Die anderen Fragen sind für sich sinnvoll, passen aber nicht zu diesem Muster: Ein Vergleich der Skandalbilanz klärt Fakten, ändert aber nichts daran, dass derselbe Vorgang je nach Lager unterschiedlich gewogen wird. Auch die Medienlage zu prüfen betrifft die Berichterstattung und nicht das eigene Urteil. Und selbst wenn ein Vorwurf belegt ist, bleibt offen, warum er bei der eigenen Partei als Kampagne und bei der anderen als Beweis gilt.","coreRule":"⚡ Vertausche die Rollen: Gilt mein Maßstab auch, wenn es um meine eigene Seite geht?","quote":"Ist das gut für uns oder für die?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.4 (Anwendung & Relevanz: Bei politischer Polarisierung; Red Flags; Das Anti-Denkmuster)","status":"entwurf","kurz":"Das Muster liegt im doppelten Maßstab, nicht im Vorgang selbst. Wer sich dieselbe Handlung von der anderen Seite vorstellt und prüft, ob das Urteil gleich bliebe, stellt den eigenen Maßstab auf die Probe. Fällt es anders aus, steckt die Asymmetrie im Urteil.","prueffrage":"Worin unterscheiden sich die beiden Skandale in der Sache, abgesehen davon, welche Partei betroffen ist?","rueckmeldung":[{"option":0,"text":"Ein Vergleich der Skandalbilanz klärt Fakten und ist für sich sinnvoll. Er ändert aber nichts daran, dass derselbe Vorgang je nach Lager unterschiedlich gewogen wird. Die Asymmetrie liegt im Urteil, nicht in der Zahl der Skandale."},{"option":1,"text":"Die Verlässlichkeit der Berichterstattung ist eine berechtigte Frage, betrifft aber die Medien und nicht das eigene Urteil. Selbst bei bester Berichterstattung bliebe offen, warum derselbe Vorgang je nach Lager so verschieden gedeutet wird."},{"option":2,"text":"Nach Belegen und unabhängiger Überprüfung zu fragen ist grundsätzlich sinnvoll. Selbst ein belegter Vorwurf lässt aber offen, warum er bei der eigenen Partei als Kampagne und bei der anderen als Beweis gilt. Das Muster liegt im Maßstab, nicht in der Beleglage."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ditto, P. H. u. a. (2019): At Least Bias Is Bipartisan. Perspectives on Psychological Science 14(2) (Kopie auf der Seite des Ditto-Labors, UC Irvine)","oeffentlich":true,"url":"https://sites.uci.edu/peterdittolab/files/2018/06/Ditto-et-al.-2018-At-Least-Bias-is-Bipartisan-A-Meta-Analytic-Comparison-of-Partisan-Bias-in-Liberals-Conservatives.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"95c163714a2f0fe8"}},{"id":"qx-b1-017","clusterId":"B","werkstueckRef":"B.5","stufe":1,"question":"Eine Wirtschaftsjournalistin sagt: „Dass die Firma so erfolgreich wurde, ist doch klar: Der Gründer war ein Visionär, jede seiner Entscheidungen führte zwangsläufig zum Erfolg. Man sieht es an seiner Biografie.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Die Erzählung, die im Rückblick alles stimmig verbindet, wird mit einer Erklärung verwechselt, die den Erfolg schon vorher verlässlich vorhergesagt hätte.","Die Journalistin schließt vom Erfolg einer einzelnen Firma auf eine Regel für alle Gründer, obwohl ein Einzelfall keine Verallgemeinerung trägt.","Die Journalistin stellt nur zwei Möglichkeiten zur Wahl, Visionär oder Versager, und blendet damit alle Abstufungen zwischen diesen beiden Polen aus.","Die Journalistin beruft sich auf die Aussage eines Fachmanns, ohne dessen Sachkenntnis zu prüfen, sodass ein Autoritätsargument den Schluss trägt."],"correctIndex":0,"explanation":"Im Rückblick lassen sich unzusammenhängende Ereignisse leicht zu einer stimmigen Ursache-Wirkungs-Geschichte verbinden, die zwingend wirkt, weil man das Ergebnis schon kennt. Vorher hätte sie aber niemand verlässlich erzählen können: Zufall, Glück, Timing und Konkurrenten mit ähnlichen Ideen, die nur Pech hatten, fehlen in der glatten Erzählung. Eine gute Erklärung im Nachhinein ist deshalb noch keine gute Vorhersage. Der Test: Welche unzusammenhängenden Fakten bleiben übrig, wenn du die erzählerischen Verbindungslinien weglässt? Die anderen Gedanken benennen echte Denkfehler, passen aber nicht auf diesen Fall: Die Journalistin spricht nur über diese eine Firma und stellt keine Regel für alle Gründer auf. Sie bietet auch kein Entweder-oder an, denn von einem Versager ist nirgends die Rede. Und sie beruft sich auf die Biografie und nicht auf die Aussage eines Fachmanns.","coreRule":"⚡ Eine glatte Geschichte im Rückblick ist noch keine Vorhersage.","beleg":"Werkstück B.5 (Kernidee; Kontext & Tiefe; Die Legende des Star-CEOs; Anti-Denkmuster)","status":"entwurf","scenario":"Ein Zeitschriftenporträt über den Gründer eines Tech-Konzerns erzählt eine runde Geschichte: der rebellische College-Abbrecher, die Garage, der Kampf gegen die trägen Riesen. Jede Entscheidung erscheint im Rückblick wie ein kluger, folgerichtiger Schritt zum Gipfel.","kurz":"Im Rückblick lässt sich fast jede Biografie zu einer zwingenden Erfolgsgeschichte ordnen, weil man das Ende kennt. Vorher hätte das niemand verlässlich vorhersagen können, denn Zufall, Glück und Timing fehlen in der glatten Erzählung.","prueffrage":"Welche Entscheidungen des Gründers hätten genauso gut schiefgehen können?","rueckmeldung":[{"option":1,"text":"Ein Einzelfall trägt tatsächlich keine Regel für alle Gründer. Die Journalistin spricht aber nur über diese eine Firma und stellt gar keine allgemeine Regel auf. Ihr Fehler liegt woanders: im glatten Rückblick auf diesen einen Weg."},{"option":2,"text":"Das Wort „Visionär“ klingt nach einem Gegensatz, aber der nötige Gegenpol fehlt: Von einem Versager ist nirgends die Rede. Ohne zwei angebotene Pole entsteht kein falsches Entweder-oder."},{"option":3,"text":"Autoritätsargumente sind ein echter Fehler, hier fehlt aber der Fachmann: Die Journalistin beruft sich auf die Biografie, nicht auf die Aussage einer Expertin oder eines Experten. Der Fehler liegt in der Rückschau, nicht in einer Berufung auf Autorität."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Roese, N. J.; Vohs, K. D. (2012): Hindsight Bias. Perspectives on Psychological Science 7(5)","oeffentlich":false,"doi":"10.1177/1745691612454303"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"996ac363b4ab5ed5"}},{"id":"qx-b1-018","clusterId":"B","werkstueckRef":"B.5","stufe":2,"question":"Welche Prüfung hilft am besten, um zu klären, ob die Reportage mehr ist als eine gute Geschichte?","scenario":"Du liest eine Reportage über den Aufstieg einer Firma: klar, spannend, jede Wendung begründet. Du willst prüfen, ob die Erzählung die Fakten trägt oder nur gut klingt.","options":["Die Verbindungen zwischen den Ereignissen gedanklich löschen und fragen, welche Einzelfakten bleiben und welche Rolle Zufall und Glück spielten.","Die Interessen der Autorin klären, etwa ob die Firma sie bezahlt hat, und die Reportage danach entsprechend vorsichtig bewerten.","Die Reportage auf innere Widersprüche durchsehen und fragen, ob sich an einer Stelle behauptete Ursachen an anderer Stelle widerlegen.","Prüfen, ob die Geschichte auch für Leser ohne Vorwissen verständlich bleibt und ob jede Wendung nachvollziehbar begründet wird."],"correctIndex":0,"explanation":"Eine kohärente Erzählung entsteht oft erst im Rückblick: Das Gehirn verbindet Einzelereignisse zu einer Ursache-Wirkungs-Kette und blendet Zufall, Glück und gescheiterte Konkurrenz aus. Wer die Verbindungslinien gedanklich entfernt, sieht, welche belegbaren Fakten übrig bleiben und wo die Geschichte nur Lücken füllt. Die Interessen der Autorin zu klären ist sinnvoll, sagt aber nichts darüber, ob die Ursachenkette trägt. Dass die Reportage keine Widersprüche enthält, gehört zu einer gut gebauten Geschichte und belegt nicht, dass sie wahr ist. Auch Verständlichkeit und begründete Wendungen hat die Reportage schon: Eine Geschichte kann klar sein und trotzdem Zufall und Glück ausblenden.","coreRule":"⚡ Streich die Verbindungslinien und sieh nach, welche Fakten übrig bleiben.","beleg":"Werkstück B.5 (Das Anti-Denkmuster; Werkbank-Frage)","status":"entwurf","kurz":"Wer die Verbindungslinien gedanklich löscht, sieht, welche belegbaren Fakten übrig bleiben. Eine glatte Erzählung entsteht oft erst im Rückblick und blendet Zufall, Glück und gescheiterte Konkurrenz aus, um Lücken zu füllen.","prueffrage":"Woher stammen die einzelnen Angaben der Reportage, und wo ließen sie sich unabhängig von ihr nachprüfen?","rueckmeldung":[{"option":1,"text":"Zu wissen, wer die Reportage bezahlt hat, ist sinnvoll. Es sagt aber nichts darüber, ob die Ursachenkette trägt: Auch eine unabhängige Reportage kann Zufall und Glück ausblenden."},{"option":2,"text":"Widersprüche zu suchen ist eine legitime Prüfung. Eine gut gebaute Geschichte hat aber gerade keine, und Widerspruchsfreiheit belegt nicht, dass sie wahr ist."},{"option":3,"text":"Klarheit und begründete Wendungen hat die Reportage schon, deshalb wirkt sie überzeugend. Eine Geschichte kann klar sein und trotzdem Zufall und Glück ausblenden."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1e61094eb4b07e35"}},{"id":"qx-b1-019","clusterId":"B","werkstueckRef":"B.5","stufe":4,"question":"Nach einem Börsencrash behauptet ein Bekannter: „Das war von langer Hand geplant. Eine kleine Gruppe von Großinvestoren hat gezielt auf den Absturz gewettet und alle anderen ins Verderben geschickt.“ Er hat viele Details parat, die zusammen eine stimmige Geschichte ergeben. Was ist an seiner Argumentation das Kernproblem?","options":["Sie macht aus Zufall, Fehlern und vielen Einzelentscheidungen eine runde Geschichte mit Bösewicht und Plan; dass sie stimmig klingt, beweist nicht ihre Wahrheit.","Sie beruft sich auf die Zustimmung vieler Menschen als Beleg, obwohl die Verbreitung einer Behauptung nichts über ihre Wahrheit sagt (Mehrheitsargument).","Sie verallgemeinert vom Verhalten einzelner Großinvestoren auf alle Anlegerinnen und Anleger, obwohl ein Einzelfall nichts über die Gesamtheit sagt.","Sie hält die Mitte zwischen zwei Standpunkten für die Wahrheit, obwohl eine Mitte nicht schon deshalb zutrifft, weil sie zwischen Extremen liegt (Kompromissfehlschluss)."],"correctIndex":0,"explanation":"Große, chaotische Ereignisse wie Wirtschaftskrisen, Pandemien oder Kriege entstehen meist aus einer Mischung von Inkompetenz, Zufall und systemischen Kräften. Die Behauptung macht daraus eine runde Geschichte mit einem allmächtigen Bösewicht, einem geheimen Plan und einem klaren Gut-Böse-Schema. Solche Geschichten sind psychologisch befriedigender als die komplizierte Realität, und genau deshalb wirken sie überzeugend. Dass die Erzählung stimmig klingt, sagt aber nichts darüber, ob sie wahr ist: Der Erzählfehler macht die Qualität der Geschichte zum Maßstab ihrer Glaubwürdigkeit statt die Qualität der Fakten. Prüfen lässt sich die Behauptung nur anhand der harten Einzelfakten, die übrig bleiben, wenn man die Verbindungslinien der Erzählung wegdenkt. Die anderen Fehlschlüsse gibt es, sie liegen hier aber nicht vor: Der Bekannte beruft sich nicht auf die Meinung vieler, sondern auf Details. Er spricht von einer kleinen Gruppe und verallgemeinert nicht auf alle Anleger. Und zwei Standpunkte, zwischen denen er einen Mittelweg wählt, gibt es in seiner Argumentation nicht.","coreRule":"⚡ Je runder die Geschichte, desto genauer solltest du nach Zufall und banaler Erklärung fragen.","beleg":"Werkstück B.5 (Anwendung & Relevanz: Bei Verschwörungsmythen; Anti-Denkmuster: Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Die Geschichte macht aus Zufall, Fehlern und vielen Einzelentscheidungen einen Plan mit Bösewicht. Dass sie stimmig klingt, ist der Denkfehler: Stimmigkeit sagt wenig über Wahrheit, nur die harten Einzelfakten tragen.","prueffrage":"Welche der vielen Details lassen sich einzeln belegen, wenn du die Verbindungen dazwischen weglässt?","rueckmeldung":[{"option":1,"text":"Verbreitung allein beweist tatsächlich nichts, das wäre ein echter Fehler. Hier fehlt er aber: Der Bekannte stützt sich nicht auf die Zustimmung vieler, sondern auf seine Fülle an Details."},{"option":2,"text":"Von Einzelfällen auf alle zu schließen, wäre ein Fehler. Der Bekannte spricht aber ausdrücklich von einer kleinen Gruppe, die alle anderen geschädigt haben soll, und verallgemeinert nicht auf alle Anleger."},{"option":3,"text":"Eine Mitte ist nicht schon deshalb wahr, weil sie zwischen Extremen liegt. Dafür bräuchte es aber zwei Standpunkte, und die gibt es hier nicht: Der Bekannte vertritt eine einzige, eindeutige Behauptung."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6) (PMC, CC BY 4.0)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5724570/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1177dd99d7268d1a"}},{"id":"qx-b1-020","clusterId":"B","werkstueckRef":"B.6","stufe":1,"question":"Was ist an Jonas' Überlegung fehlerhaft?","options":["Er rechnet Geld, das bereits ausgegeben und nicht mehr zurückzuholen ist, in eine Entscheidung ein, die nur von künftigen Kosten und Nutzen abhängen sollte.","Er hängt am Motorrad, nur weil es ihm gehört, und bewertet es deshalb höher als ein gleichwertiges Motorrad, das ihm nicht gehört (Besitztumseffekt).","Er setzt die Dauer und die Kosten der nächsten Reparatur zu optimistisch an, weil Vorhaben meist länger dauern als geplant (Planungsfehlschluss).","Er orientiert sich an anderen Motorradbesitzern, die ihre Maschinen ebenfalls lange weiterreparieren, und folgt damit der Mehrheit (Mitläufereffekt)."],"correctIndex":0,"explanation":"Die 3.000 Euro sind weg, egal ob Jonas weiterrepariert oder aufgibt; sie verändern keine der beiden Möglichkeiten. Vernünftig ist ein Vergleich dessen, was noch kommt: weitere 1.800 Euro für ein Motorrad mit unsicherem Zustand gegen 2.500 Euro für ein zuverlässiges, abzüglich dessen, was das alte beim Verkauf noch einbringt. Dieser Vergleich kann durchaus für die Reparatur ausgehen; fehlerhaft ist die Begründung, denn wer die Vergangenheit mitrechnet, weil sonst alles „umsonst“ gewesen wäre, hält leicht an einer schlechten Investition fest. Diese Falle heißt Versunkene-Kosten-Falle (Sunk Cost Fallacy). Eine hilfreiche Prüffrage: Würdest du das Motorrad in diesem Zustand heute zu diesem Preis neu kaufen? Die anderen Gedanken nennen bekannte Verzerrungen, treffen Jonas aber nicht: Er begründet mit dem investierten Geld und nicht mit einer besonderen Bindung an das Motorrad als Besitz. Eine eigene, zu optimistische Schätzung der Reparatur äußert er nicht, die Zahl stammt vom Mechaniker. Und dass er sich an anderen orientiert, kommt im Szenario nicht vor.","coreRule":"⚡ Entscheide nach dem, was kommt, nicht nach dem, was schon weg ist.","beleg":"Werkstück B.6 (Kernidee; Kontext & Tiefe); Fn. gl-b-sunk-cost (Arkes/Blumer 1985, OBHDP 35(1), S. 124)","status":"entwurf","scenario":"Jonas hat vor einem Jahr 3.000 Euro in ein gebrauchtes Motorrad gesteckt. Seitdem war er viermal in der Werkstatt, der Motor macht weiter Probleme, und der Mechaniker schätzt die nächste Reparatur auf weitere 1.800 Euro. Ein vergleichbares, zuverlässiges Motorrad gäbe es für 2.500 Euro. Jonas sagt: „Ich habe schon 3.000 Euro hineingesteckt. Wenn ich jetzt aufgebe, war das alles umsonst. Ich repariere weiter.“","quote":"","quoteLabel":"","kurz":"Die 3.000 Euro sind verloren, egal wie Jonas sich entscheidet, und dürfen nur das Künftige vergleichen. Fehlerhaft ist die Begründung „sonst war alles umsonst“, denn sie lässt ihn leicht an einer schlechten Investition festhalten.","prueffrage":"Was spricht nach vier Werkstattbesuchen dafür, dass die nächste Reparatur die letzte ist?","rueckmeldung":[{"option":1,"text":"Eigentum kann den Wert eines Gegenstands tatsächlich verzerren. Jonas begründet aber nicht mit Verbundenheit zum Motorrad, sondern mit dem bereits ausgegebenen Geld, und das ist ein anderer Fehler."},{"option":2,"text":"Reparaturen werden oft teurer als gedacht, doch Jonas schätzt hier nichts selbst: Die 1.800 Euro nennt der Mechaniker. Sein Fehler liegt nicht in der Schätzung, sondern darin, wie er die schon bezahlten 3.000 Euro gewichtet."},{"option":3,"text":"Auf die Mehrheit zu schauen, kann Entscheidungen verzerren. Im Szenario kommen aber keine anderen Besitzer vor, und Jonas beruft sich auf niemanden, sondern allein auf sein bereits investiertes Geld."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"fc238e2b1b848245"}},{"id":"qx-b1-021","clusterId":"B","werkstueckRef":"B.6","stufe":2,"question":"Welche Prüffrage setzt genau am Fehler in der Begründung der Leitung an?","scenario":"In deiner Firma läuft seit vier Jahren ein Softwareprojekt, das nach Einschätzung des Teams nie fertig wird. In der Sitzung sagt die Leitung: „Wir haben schon so viel investiert – jetzt aufzugeben wäre Verschwendung.“ Du darfst eine einzige Prüffrage stellen.","options":["„Welchen Betrag müssen wir bei einem Abbruch abschreiben, und können wir diesen Verlust verkraften?“","„Würden wir dieses Projekt heute, in genau diesem Zustand und mit dem heutigen Wissen, neu beginnen?“","„Was lief in den ersten Jahren schief, und welche Lehren ziehen wir daraus für künftige Projekte?“","„Wer hat das Projekt damals angestoßen, und wurden bei dieser Entscheidung alle Beteiligten angehört?“"],"correctIndex":1,"explanation":"Der Fehler liegt darin, dass bereits ausgegebenes Geld und vergangene Mühe zum Grund für die Fortsetzung gemacht werden. Diese Kosten sind unwiederbringlich weg, egal ob das Projekt weiterläuft oder nicht; für die Entscheidung zählen nur künftige Kosten und künftiger Nutzen. Die Frage, ob man das Vorhaben heute im jetzigen Zustand neu beginnen würde, blendet die Vergangenheit aus und zwingt dazu, nur die Zukunft zu bewerten. Die Höhe der Abschreibung zu kennen kann bei der Planung eines Abbruchs nützlich sein, aber es ist vergangenes Geld und liefert keinen Grund für oder gegen die Fortsetzung. Die Ursachen des bisherigen Scheiterns zu klären hilft bei späteren Projekten, prüft aber nicht, ob das Weitermachen begründet ist. Wer das Projekt einst angestoßen hat, ist für die Frage nach der Zukunft unerheblich.","coreRule":"⚡ Frag nicht, wie viel du schon investiert hast, sondern ob du heute noch einsteigen würdest.","quote":"Würde ich einsteigen?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.6 (Das Anti-Denkmuster; Verbindungen: Null-Basis-Check A.14)","status":"entwurf","kurz":"Schon ausgegebenes Geld und vergangene Mühe sind weg, ob das Projekt weiterläuft oder nicht. Ein Grund zum Weitermachen ist nur, was künftig noch kostet und nützt; das zeigt die Frage, ob man heute neu beginnen würde.","prueffrage":"Welchen Grund nennt die Leitung in der Sitzung dafür, das Projekt weiterzuführen?","rueckmeldung":[{"option":0,"text":"Den Abschreibungsbetrag zu kennen kann bei der Planung eines Abbruchs nützlich sein. Doch es ist vergangenes Geld und spricht weder für noch gegen die Fortsetzung; die Frage prüft nicht, was künftig noch kostet und nützt."},{"option":2,"text":"Die Ursachen des bisherigen Scheiterns zu klären hilft bei späteren Projekten. Ob das Weitermachen jetzt begründet ist, prüft diese Frage aber nicht, denn sie blickt nur zurück und nicht auf künftige Kosten und Nutzen."},{"option":3,"text":"Wer das Projekt einst angestoßen hat und wie damals entschieden wurde, wirkt wie ein Weg, den Fehler zu finden. Für die Entscheidung über die Zukunft ist das aber unerheblich, und die Frage lenkt von künftigen Kosten und Nutzen ab."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ebd1deda555bc2ee"}},{"id":"qx-b1-022","clusterId":"B","werkstueckRef":"B.6","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass aus gesunder Ausdauer irrationale Sturheit geworden ist?","options":["Die Gründerin macht weiter, obwohl der Markttest eindeutig negativ ausfiel, und verweist auf ihre zwei bisherigen Jahre.","Der Doktorand wiederholt sein Experiment, obwohl der erste Versuch scheiterte, und verweist auf einen gefundenen Messfehler.","Der Mann hält an der Fernbeziehung fest, obwohl der Alltag anstrengend ist, und verweist auf den vereinbarten Umzug im nächsten Jahr.","Die Frau behält ihre Aktien, obwohl der Kurs im letzten Monat fiel, und verweist auf die unveränderten Geschäftszahlen der Firma."],"correctIndex":0,"explanation":"Ausdauer ist oft nötig und nützlich: Wer nach dem ersten Rückschlag aufgibt, erreicht langfristige Ziele nie. Der Kipppunkt zur Sturheit liegt dort, wo neue, negative Informationen ignoriert werden, um die ursprüngliche Entscheidung zu schützen. Entscheidend ist also, wie jemand mit neuer Information umgeht und wonach er seine Entscheidung begründet. Bei den anderen dreien zeigt der Grund nach vorn: Der Doktorand hat einen Messfehler gefunden, den er beim nächsten Versuch ausschließen kann, der Mann hat einen Umzug vereinbart, der den Alltag ändern wird, und die Frau stützt sich auf unveränderte Geschäftszahlen. Nur die Gründerin stützt sich auf bereits Investiertes und übergeht die eindeutig negative Information. Die zwei Jahre sind unwiederbringlich verloren, gleich wie sie sich entscheidet, und dürfen deshalb die Entscheidung über die Zukunft nicht lenken. Prüffrage: Würde ich heute, mit dem aktuellen Wissen, noch einmal einsteigen? Ein Rückschlag, ein anstrengender Alltag oder ein gefallener Kurs allein zeigen noch keine Sturheit. Auch ein gescheiterter erster Versuch ist kein Grund zum Aufgeben, wenn sich die Ursache benennen lässt. Sturheit beginnt erst dort, wo man an einer Entscheidung festhält, ohne einen Grund zu nennen, der in die Zukunft weist.","coreRule":"⚡ Ausdauer hält durch, trotz Schwierigkeiten – Sturheit hält fest, trotz Gegenbeweisen.","beleg":"Werkstück B.6 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","scenario":"Vier Menschen halten an einem Vorhaben fest, das nicht richtig läuft: eine Gründerin mit ihrem Start-up, ein Doktorand mit seinem Experiment, ein Mann mit seiner Fernbeziehung und eine Frau mit ihrer Aktienposition.","kurz":"Sturheit zeigt sich, wenn eine eindeutig negative Information übergangen und die Entscheidung mit bereits Investiertem verteidigt wird. Zwei Jahre sind so oder so verloren und taugen nicht als Grund, in der Zukunft weiterzumachen.","prueffrage":"Worauf stützt sich jede der vier Personen, wenn sie begründet, warum sie weitermacht?","rueckmeldung":[{"option":1,"text":"Ein gescheiterter erster Versuch wirkt wie ein Warnsignal. Hier ist aber die Ursache benannt: Der Messfehler lässt sich beim nächsten Versuch ausschließen. Der Grund zeigt nach vorn, das ist Ausdauer."},{"option":2,"text":"Ein anstrengender Alltag lässt Festhalten schnell stur aussehen. Der vereinbarte Umzug nennt aber einen Grund, der die Lage künftig ändert. Anstrengung allein zeigt noch keine Sturheit."},{"option":3,"text":"Ein gefallener Kurs wirkt wie ein Zeichen zum Verkaufen. Die Frau stützt sich aber auf unveränderte Geschäftszahlen, also auf etwas, das die Zukunft betrifft. Ein Kursrückgang allein reicht nicht als Beleg für Sturheit."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1832bcf56fc11d80"}},{"id":"qx-b1-023","clusterId":"B","werkstueckRef":"B.6","stufe":4,"question":"Welche Rückfrage der Freundin würde ihr am besten helfen, ihre Entscheidung neu zu prüfen?","scenario":"Eine Frau engagiert sich seit zehn Jahren in einer Gemeinschaft, die eine bestimmte Lehre vertritt. Inzwischen hat sie ernste Zweifel an deren Aussagen. Eine Freundin fragt sie, warum sie trotzdem bleibt. Sie antwortet: „Ich habe zehn Jahre, meine Freundschaften und mein Geld hineingesteckt. Wenn ich jetzt gehe, war das alles umsonst.“","options":["„Würdest du heute, so wie du die Lehre jetzt einschätzt, neu einsteigen?“","„Wie viel Geld und Zeit hast du investiert, und was davon ist noch zu retten?“","„Wann sind deine Zweifel zum ersten Mal aufgekommen, und was hat sie ausgelöst?“","„Gab es in den zehn Jahren auch gute Momente, und was haben sie dir bedeutet?“"],"correctIndex":0,"explanation":"Die zehn Jahre und das Geld sind ausgegeben und kommen nicht zurück, egal ob sie bleibt oder geht; solche versunkenen Kosten sollten die künftige Entscheidung nicht lenken. Zählen darf, was von nun an für oder gegen das Bleiben spricht, und dazu gehört auch, welche Freundschaften ein Austritt gefährden würde; über die Lehre selbst sagt aber auch das nichts. Die Frage nach dem Neueinstieg richtet den Blick genau darauf und zwingt, die Lehre so zu bewerten, wie sie heute dasteht. Genau diese Bindung ans Investierte hält Menschen oft in Kulten und Glaubenssystemen fest, selbst wenn Zweifel aufkommen. Den Aufwand zu überblicken ist verständlich, doch das Investierte lässt sich nicht zurückholen und ändert nichts an der künftigen Lage. Zu wissen, wann die Zweifel begannen, kann beim Verstehen helfen, prüft aber die Lehre nicht. Und die guten Momente gehören zur Vergangenheit, sie sagen nichts darüber, was die Lehre heute wert ist.","coreRule":"⚡ Bereits Verlorenes darf die Entscheidung nicht lenken: Frag, ob du heute noch einsteigen würdest.","beleg":"Werkstück B.6 (Anwendung & Relevanz: Bei irrationalen Glaubenssystemen; Kontext & Tiefe)","status":"entwurf","kurz":"Die zehn Jahre und das Geld sind weg, egal ob sie bleibt oder geht, und sollten daher nicht lenken. Die Frage nach dem Neueinstieg bewertet die Lehre so, wie sie heute dasteht, und löst damit die Bindung ans Investierte.","prueffrage":"Was genau an den Aussagen der Gemeinschaft bezweifelt sie, und seit wann?","rueckmeldung":[{"option":1,"text":"Sich den Aufwand klarzumachen ist verständlich und wirkt wie eine nüchterne Bilanz. Zurückholen lässt sich davon aber nichts, und für das Weitere ändert es nichts. Wer fragt, was noch zu retten ist, hält den Blick auf der Vergangenheit."},{"option":2,"text":"Zu wissen, wann und wodurch die Zweifel begannen, kann helfen, sie zu verstehen. Ob die Lehre heute trägt, prüft das jedoch nicht, denn es beleuchtet nur, wie die Zweifel entstanden sind."},{"option":3,"text":"Gute Erfahrungen zählen für ihr Leben durchaus. Sie liegen aber hinter ihr und sagen nichts darüber, was die Lehre heute wert ist. Genau das müsste sie für ihre Entscheidung klären."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a748c97ac094bba2"}},{"id":"qx-b1-024","clusterId":"B","werkstueckRef":"B.7","stufe":1,"question":"Was ist an der Aussage der Kollegin das Hauptproblem?","scenario":"Am Tag nach einer Wahl, bei der Kandidat A überraschend deutlich gewonnen hat, hörst du in der Kantine drei Sätze: (a) „Das musste ja so kommen.“ (b) „Ich habe doch gesagt, dass er gewinnt“ – dabei hatte sich der Sprecher vor der Wahl auf keinen Sieger festgelegt. (c) Eine Kollegin: „Das hätte man doch sehen müssen!“ Du weißt, dass vor der Wahl selbst Fachleute uneins waren und die Umfragen knapp standen.","options":["Sie beurteilt die Vorhersehbarkeit nach dem Ergebnis und blendet aus, dass die Lage vor der Wahl offen war.","Sie wertet den Sieg ab, weil sie A politisch ablehnt, und urteilt parteiisch (Gruppenzugehörigkeits-Verzerrung).","Sie führt den Sieg von A allein auf dessen Persönlichkeit zurück und unterschätzt die Umstände (Attributionsfehler).","Sie stützt sich auf einprägsame Wahlkampfbilder statt auf nüchterne Zahlen (Verfügbarkeitsheuristik)."],"correctIndex":0,"explanation":"Wer den Ausgang kennt, sortiert die damaligen Informationen neu: Was zum Ergebnis passt, wirkt im Rückblick wichtig, was auf andere Ausgänge hindeutete, verliert an Gewicht. Vor der Wahl waren selbst Fachleute uneins und die Umfragen knapp, die Lage war also offen; der Satz „Das hätte man doch sehen müssen!“ misst sie am Wissen von heute und urteilt dadurch unfair. Die drei Sätze aus der Kantine zeigen drei Spielarten des Rückschaufehlers: „Das musste ja so kommen“ ist das Gefühl der Unvermeidbarkeit, „Ich habe doch gesagt, dass er gewinnt“ die Gedächtnisverzerrung (die eigene frühere Einschätzung rutscht in Richtung des Ergebnisses), „Das hätte man doch sehen müssen!“ das Gefühl der Vorhersehbarkeit. Hilfreich ist die Frage: Welche Informationen, die ich jetzt habe, hatte damals noch niemand? Die anderen Gedanken benennen echte Verzerrungen, passen aber nicht zur Aussage: Über die politische Haltung der Kollegin steht nichts im Szenario. Sie spricht auch nicht über A als Person, sondern darüber, was man vorher hätte erkennen können. Und von einprägsamen Bildern, die ihr Urteil lenken, ist ebenfalls keine Rede.","coreRule":"⚡ Rückblickend wirkt alles zwingend, vorhersehbar und längst gewusst – dabei war es damals offen. Prüfe, was man zum Zeitpunkt der Entscheidung wissen konnte.","beleg":"Werkstück B.7 (Kontext & Tiefe, drei Ebenen); Fn. gl-b-rueckschau-ebenen (Roese/Vohs 2012, Perspectives on Psychological Science 7(5), S. 412–413)","status":"entwurf","kurz":"„Hätte man sehen müssen“ misst die damalige Lage am Wissen von heute. Dabei waren Fachleute uneins und die Umfragen knapp, der Ausgang also offen. Wer das Ergebnis kennt, gewichtet im Rückblick vor allem, was dazu passt.","prueffrage":"Welche Tipps gaben die Leute in der Kantine vor der Wahl ab, und wie sicher waren sie sich damals?","rueckmeldung":[{"option":1,"text":"Parteilichkeit ist eine echte Verzerrung und liegt bei Wahlthemen nahe. Im Szenario steht aber nichts über die politische Haltung der Kollegin, und ihr Satz handelt nicht von A, sondern davon, was man vorher hätte erkennen können."},{"option":2,"text":"Der Attributionsfehler ist eine echte Verzerrung, bezieht sich aber auf Ursachen. Die Kollegin erklärt den Sieg gar nicht mit der Persönlichkeit von A, sie behauptet, man hätte ihn vorhersehen können. Das ist eine andere Frage."},{"option":3,"text":"Einprägsame Bilder können Urteile tatsächlich lenken. Von Wahlkampfbildern ist im Szenario aber keine Rede, und der Satz der Kollegin stützt sich erkennbar auf das bekannte Ergebnis, nicht auf Eindrücke aus dem Wahlkampf."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis, Kap. 13: Hindsight Biases in Evaluation of Intelligence Reporting. CIA","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"161–162","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fischhoff, B. (1975): Hindsight ≠ Foresight. Journal of Experimental Psychology: Human Perception and Performance 1(3)","oeffentlich":false,"doi":"10.1037/0096-1523.1.3.288"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"76e1016f7aff5dca"}},{"id":"qx-b1-025","clusterId":"B","werkstueckRef":"B.7","stufe":2,"question":"Welches Vorgehen schützt am besten davor, dass das Wissen um den Ausgang die Erinnerung und das Urteil verfälscht?","scenario":"Anna wechselt den Job. Ein halbes Jahr später läuft es schlecht, und sie denkt: „Ich hab doch gleich gespürt, dass das nicht passt.“ Ihr Freund Ben erinnert sich anders: Damals war sie begeistert und hielt den Wechsel für eine große Chance. Beide wollen bei der nächsten wichtigen Entscheidung später ehrlich beurteilen können, was sie vorher wussten und wie gut sie entschieden haben.","options":["Nach dem Ergebnis in Ruhe überlegen, was man damals eigentlich geglaubt und gewusst hat.","Die Entscheidung so lange aufschieben, bis der Ausgang sicher genug absehbar ist.","Das Ergebnis konsequent als Maßstab nehmen, um die Entscheidung als gut oder schlecht zu bewerten.","Gründe und Unsicherheitsgrad vorab schriftlich festhalten, bevor das Ergebnis bekannt ist."],"correctIndex":3,"explanation":"Wer vor der Entscheidung schriftlich festhält, was er weiß und wie sicher er sich ist, hat später einen Beleg, der nicht mehr durch das Ergebnis verfälscht werden kann. Die Erinnerung nach dem Ausgang ist dagegen genau das, was der Rückschaufehler verzerrt: Wir sind dann überzeugt, es „schon immer gewusst“ zu haben. Auch das Ergebnis taugt nicht als Maßstab, denn eine gute Entscheidung kann schlecht ausgehen und umgekehrt. Beurteilen lässt sich eine Entscheidung nur danach, was zum Zeitpunkt der Entscheidung bekannt und absehbar war. Und abwarten, bis der Ausgang absehbar ist, würde die Entscheidung gerade unmöglich machen, denn Entscheidungen müssen unter Unsicherheit fallen.","coreRule":"⚡ Schreib auf, was du weißt und wie sicher du bist – bevor du das Ergebnis kennst.","beleg":"Werkstück B.7 (Verbindungen: Entscheidungs-Tagebuch; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer vorab schriftlich festhält, was er weiß und wie sicher er ist, hat später einen Beleg, den das Ergebnis nicht färben kann. Die Erinnerung danach neigt dazu, „das habe ich immer gewusst“ zu sagen.","prueffrage":"Wie sicher sind sich Anna und Ben jeweils ihrer Erinnerung, und wie ließe sich heute klären, wer recht hat?","rueckmeldung":[{"option":0,"text":"Nachträgliches Nachdenken klingt gründlich, stützt sich aber auf genau die Erinnerung, die der Ausgang färbt. Das zeigen Anna und Ben: Beide sind überzeugt, und ihre Erinnerungen widersprechen sich."},{"option":1,"text":"Wer wartet, bis der Ausgang absehbar ist, entscheidet nicht mehr unter Unsicherheit, sondern gar nicht. Das Problem der verfälschten Rückschau bleibt trotzdem für alle späteren Urteile bestehen."},{"option":2,"text":"Ein Ergebnis sagt zwar etwas, ist aber ein schlechter alleiniger Maßstab: Gute Entscheidungen können schlecht ausgehen und umgekehrt. Beurteilbar ist nur, was zum Zeitpunkt der Entscheidung bekannt und absehbar war."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis, Kap. 13: Hindsight Biases in Evaluation of Intelligence Reporting. CIA","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"162","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fischhoff, B. (1975): Hindsight ≠ Foresight. Journal of Experimental Psychology: Human Perception and Performance 1(3)","oeffentlich":false,"doi":"10.1037/0096-1523.1.3.288"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b5fa7f18433318f4"}},{"id":"qx-b1-026","clusterId":"B","werkstueckRef":"B.7","stufe":4,"question":"Wie prüfst du am besten, ob diese Strophe das Ereignis wirklich vorhergesagt hat?","scenario":"Nach einer Katastrophe zeigt dir jemand eine mehrdeutige Strophe aus einer alten Prophezeiungssammlung. Er sagt, sie habe genau dieses Ereignis „vorhergesagt“, und verweist darauf, dass sich im Text Bilder finden, die zum Geschehen passen.","options":["Du fragst, ob sich die Handschrift der Strophe sicher auf die Zeit vor dem Ereignis datieren lässt.","Du fragst, ob die Deutung vor dem Ereignis festgehalten wurde und konkret genug war, um scheitern zu können.","Du fragst, ob die Strophe korrekt übersetzt wurde, da Übersetzungen die Bedeutung von Bildern verschieben können.","Du fragst, ob die Person, die die Strophe deutet, Fachwissen über die Sammlung hat und seriös auftritt."],"correctIndex":1,"explanation":"Ob die Deutung schon vor der Katastrophe festgehalten wurde, ist offen; oft wird zu einer mehrdeutigen Strophe erst nachträglich ein passendes Ereignis gesucht. Wer den Ausgang kennt, findet in vagen Bildern fast immer Anknüpfungspunkte, deshalb beweisen passende Bilder nichts. Echte Vorhersagekraft zeigt nur eine Aussage, die vor dem Ereignis festgehalten wurde und so konkret war, dass sie hätte scheitern können. Fehlt das, bleibt nur Deutungskraft im Rückblick. Das Alter der Handschrift zu klären ist bei der Echtheit wichtig, aber der Text ist ja alt: Das Problem ist nicht, wann er entstand, sondern ob die Deutung vorab feststand. Eine genaue Übersetzung hilft, löst aber nicht das Problem, dass die Bilder mehrdeutig bleiben. Und das Fachwissen der Deutenden macht eine Deutung nicht überprüfbar, die erst nach dem Ereignis entstand.","coreRule":"⚡ Eine Vorhersage zählt nur, wenn sie vor dem Ereignis eindeutig festgehalten wurde.","beleg":"Werkstück B.7 (Anwendung & Relevanz: In der Esoterik)","status":"entwurf","kurz":"Entscheidend ist, ob die Deutung schon vor dem Ereignis feststand und so konkret war, dass sie hätte scheitern können. Wer den Ausgang kennt, findet in vagen Bildern fast immer Passendes; das ist dann nur Deutung im Rückblick, keine Vorhersage.","prueffrage":"Auf wie viele andere Katastrophen der letzten Jahrzehnte ließe sich dieselbe Strophe ebenso gut beziehen?","rueckmeldung":[{"option":0,"text":"Die Datierung ist wichtig, wenn es um die Echtheit des Textes geht. Dass die Strophe alt ist, steht aber ohnehin nicht infrage. Offen bleibt, ob die Deutung schon vor dem Ereignis feststand."},{"option":2,"text":"Eine genaue Übersetzung hilft, denn Bilder lassen sich tatsächlich verschieben. Doch auch die beste Übersetzung macht eine mehrdeutige Strophe nicht eindeutig, und ob die Deutung vorab feststand, klärt sie nicht."},{"option":3,"text":"Fachwissen und seriöses Auftreten sind nützlich, wenn es um die Auslegung eines Textes geht. Sie machen aber eine Deutung nicht überprüfbar, die erst nach dem Ereignis entstand. Geprüft werden muss die Aussage selbst."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0296f6a09115bd44"}},{"id":"qx-b1-027","clusterId":"B","werkstueckRef":"B.8","stufe":1,"question":"Was ist an dieser Überlegung fehlerhaft?","options":["Du erklärst sein Verhalten mit einer dauerhaften Eigenschaft und blendest die Umstände aus, die du nicht kennst.","Du ordnest Jonas vorschnell einer Gruppe zu und überträgst auf ihn Eigenschaften, die man dieser Gruppe nachsagt (Stereotypisierung).","Du hältst an dem ersten Eindruck fest, den Jonas bei dir hinterlassen hat, und gewichtest spätere Informationen zu gering (Primacy-Effekt).","Du bewertest Jonas strenger, weil du dich selbst für rücksichtsvoller hältst, und schützt so dein Selbstbild (selbstwertdienliche Verzerrung)."],"correctIndex":0,"explanation":"Aus einem einzelnen Verhalten wird hier auf eine stabile Eigenschaft geschlossen („Egoist“, „schon immer“), während die Situation, die du nicht kennst, gar nicht in die Erklärung eingeht. Das ist der typische Fehlschluss beim Beurteilen anderer: Die Person ist das Auffälligste, was wir sehen, ihre Umstände sind für uns unsichtbar. Der Fehler besteht in der Tendenz, die Situation zu unterschätzen, nicht darin, dass der Charakter nie eine Rolle spielt. Die anderen Gedanken benennen echte Verzerrungen, passen aber nicht zu deiner Überlegung: Eine Gruppe, der Jonas angehört, spielt darin keine Rolle. Du warst bei der Sitzung nicht dabei, es gibt also keinen ersten Eindruck, an dem du festhältst. Und ein Vergleich mit deinem eigenen Verhalten kommt in deinem Gedanken nicht vor.","coreRule":"⚡ Wer ein Verhalten sofort mit dem Charakter erklärt, sieht die Umstände nicht, die er nicht kennt.","beleg":"Werkstück B.8 (Kernidee; Kontext & Tiefe, Fokus der Aufmerksamkeit; Hinweis zur Beleglage); Fn. gl-b-attribution (Ross/Anderson 1982, Kap. 9)","status":"entwurf","scenario":"Du erfährst, dass Jonas bei der Teamsitzung gestern zwei Kollegen mehrfach das Wort abgeschnitten hat. Dein Gedanke: „Der ist einfach ein rücksichtsloser Egoist, so war der schon immer.“ Über Jonas' Woche weißt du nichts. Was du nicht weißt: Er hatte kurz vorher einen Abgabetermin mit großem Zeitdruck.","kurz":"Aus einem einzelnen Verhalten wird eine feste Eigenschaft gemacht („Egoist“, „schon immer“), während die Umstände unbekannt bleiben. Der Fehler: Die Person fällt auf, ihre Situation sehen wir nicht. Das heißt nicht, dass Charakter nie zählt.","prueffrage":"Wie hat sich Jonas in früheren Sitzungen verhalten, und wer hat das selbst erlebt?","rueckmeldung":[{"option":1,"text":"„Egoist“ klingt zwar nach einer Schublade, aber im Gedanken kommt keine Gruppe vor, der Jonas zugeordnet wird. Geurteilt wird über ihn allein, aus einem einzelnen Verhalten heraus."},{"option":2,"text":"Ein früh feststehendes Urteil kann tatsächlich spätere Informationen verdrängen. Hier gab es aber keinen eigenen ersten Eindruck, du hast nur davon gehört. Statt zu geringer Gewichtung fehlen die Umstände schlicht im Urteil."},{"option":3,"text":"Eigene Interessen können Urteile über andere färben. Dein Gedanke vergleicht Jonas aber an keiner Stelle mit dir selbst. Er schließt allein von einem Verhalten auf eine feste Eigenschaft."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1) (Kopie auf der Harvard-Seite von D. Gilbert)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"url","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6), Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4a9c8a5a19bccc83"}},{"id":"qx-b1-028","clusterId":"B","werkstueckRef":"B.8","stufe":3,"question":"In einem Podcast heißt es: „Jeder weiß doch: Wir erklären unser eigenes Fehlverhalten mit den Umständen, das Fehlverhalten anderer aber mit deren Charakter. Das ist psychologisch erwiesen.“ Du erfährst, dass eine Auswertung von 173 Studien genau diese Behauptung geprüft hat. Welche Frage hilft dir jetzt am meisten, um die Aussage einzuordnen?","options":["Wie groß war der durchschnittliche Effekt über alle Studien hinweg, und unter welchen Bedingungen zeigte er sich überhaupt?","Wie viele Versuchspersonen nahmen insgesamt an allen Studien teil, und wie groß war die kleinste einzelne Studie?","Wer hat die Auswertung finanziert, und hatten die Autorinnen ein Interesse an einem bestimmten Ergebnis?","Wie oft wurde die Auswertung seit ihrem Erscheinen zitiert, und in welcher Fachzeitschrift wurde sie veröffentlicht?"],"correctIndex":0,"explanation":"Wer eine Behauptung prüfen will, schaut auf die Gesamtlage der Belege statt auf Bekanntheit, Einzelfälle oder das eigene Gefühl. Tatsächlich fand die Auswertung von 173 Studien (Malle 2006) für diese Asymmetrie im Durchschnitt praktisch keinen Effekt. Sie zeigte sich nur unter bestimmten Bedingungen, vor allem bei negativem Verhalten, und auch dort nur klein; bei positivem Verhalten kehrte sie sich um. Eine Behauptung kann jahrzehntelang als gesichert gelten und der Überprüfung trotzdem nur teilweise standhalten. Die Zahl der Teilnehmenden sagt etwas über die Genauigkeit einer Auswertung, aber nicht, wie groß der Effekt ist. Die Finanzierung zu klären hilft, mögliche Interessen zu erkennen, beantwortet aber nicht, was die Daten zeigen. Zitate und Ruf einer Zeitschrift sagen etwas über Aufmerksamkeit, nicht über Größe und Bedingungen des Effekts.","coreRule":"⚡ Auch Lehrbuchwissen braucht einen Quellencheck: Frag nach der Gesamtlage der Belege (Größe und Bedingungen des Effekts), nicht nach Bekanntheit oder Einzelfällen.","beleg":"Werkstück B.8 (Hinweis zur Beleglage); Fn. gl-b-attribution (Malle 2006, Psychological Bulletin 132(6), S. 895, 902, 907)","status":"entwurf","scenario":"Du hörst den Podcast beim Kochen und möchtest die Aussage nicht einfach glauben oder abtun.","kurz":"Entscheidend ist, wie groß der Effekt im Durchschnitt war und wann er auftrat: Hier fast keiner, nur unter bestimmten Bedingungen und klein. Der Fehler wäre, Bekanntes für gesichert zu halten, statt die Gesamtlage der Belege zu prüfen.","prueffrage":"Woher weiß der Podcast, dass „jeder“ das so macht, und welche Belege nennt er dafür?","rueckmeldung":[{"option":1,"text":"Viele Teilnehmende machen eine Auswertung genauer, das ist ein guter Gedanke. Wie groß der Effekt ist und wann er auftritt, sagt die Zahl der Teilnehmenden aber nicht."},{"option":2,"text":"Wer finanziert, kann Interessen verraten, und danach zu fragen ist durchaus sinnvoll. Was die Daten über die Behauptung zeigen, bleibt damit aber offen, und darum geht es hier zuerst."},{"option":3,"text":"Oft zitierte Arbeiten in angesehenen Zeitschriften wirken verlässlich. Das zeigt aber nur Aufmerksamkeit und Ansehen, nicht, wie groß der Effekt ausfiel und unter welchen Bedingungen er auftrat."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis, Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6)","oeffentlich":false,"doi":"10.1037/0033-2909.132.6.895","seite":"895, 902"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"aa22bbef3a106c22"}},{"id":"qx-b1-029","clusterId":"B","werkstueckRef":"B.8","stufe":4,"question":"Wie solltest du den Schluss einschätzen, der Attributionsfehler („wir erklären das Verhalten anderer vorschnell mit ihrem Charakter“) sei ein universelles Merkmal des Menschen?","options":["Die Verallgemeinerung ist zu weit gegangen: Vergleichsstudien deuten darauf hin, dass der Effekt außerhalb des Westens schwächer ausfällt, etwa weil Ostasiaten eher auf die Macht der Situation schließen.","Die Verallgemeinerung ist nicht belegt: Dass eine Annahme vielen Menschen selbstverständlich erscheint, macht sie noch nicht zu einem gesicherten Befund, auch wenn sie oft wiederholt wird.","Die Verallgemeinerung ist fragwürdig: Aussagen gewinnen nicht dadurch an Beweiskraft, dass sich Fachleute auf sie berufen, solange die Belege dafür nicht offengelegt werden.","Die Verallgemeinerung ist voreilig: Aus einem Zusammenhang zwischen einem Merkmal und einem Verhalten folgt noch nicht, dass das Merkmal das Verhalten verursacht."],"correctIndex":0,"explanation":"Eine Verallgemeinerung ist nur so gut wie die Gruppe, an der getestet wurde. Wurden die klassischen Versuche fast nur mit westlichen Versuchspersonen gemacht, sagt das wenig über „den Menschen“ insgesamt. Tatsächlich deuten Vergleichsstudien darauf hin, dass der „fundamentale“ Fehler anderswo weniger grundlegend wirkt: Ostasiaten schlossen eher als US-Amerikaner auf die Macht der Situation, besonders wenn die Umstände deutlich hervorgehoben waren; ähnliche Befunde gibt es für Russen und früher für Hindus in Indien. Charakterurteile gibt es auch dort. Die angemessene Haltung: Der Effekt ist real, aber in Stärke und Verbreitung kulturabhängig. Die anderen Einwände nennen für sich genommen richtige Regeln: Dass viele etwas für selbstverständlich halten, macht es nicht wahr; die Berufung auf Fachleute ersetzt keine Belege; und ein Zusammenhang ist noch keine Ursache. Sie treffen aber nicht das Problem dieses Podcasts, der sich auf Experimente beruft und dessen Schwäche in der einseitigen Auswahl der Versuchspersonen liegt.","coreRule":"⚡ Von einer Stichprobe auf „alle Menschen“ zu schließen, ist nur erlaubt, wenn die Stichprobe die Vielfalt der Menschen abbildet.","beleg":"Werkstück B.8 (Kontext & Tiefe); Fn. gl-b-attribution-kultur (Henrich/Heine/Norenzayan 2010, RatSWD Working Paper 139, S. 25 f.)","status":"entwurf","scenario":"In einem Podcast heißt es: „Dass wir das Verhalten anderer vorschnell mit ihrem Charakter erklären und die Umstände unterschätzen, ist ein Grundzug der menschlichen Natur – das tun alle Menschen überall gleich stark, das haben Experimente gezeigt.“ Die klassischen Experimente, auf die sich die Aussage stützt, wurden ganz überwiegend mit westlichen Versuchspersonen durchgeführt.","quote":"","quoteLabel":"","kurz":"Eine Verallgemeinerung reicht nur so weit wie die getestete Gruppe. Wurde fast nur im Westen getestet, folgt daraus nichts über „den Menschen“; Vergleichsstudien deuten darauf hin, dass der Effekt anderswo schwächer ausfällt.","prueffrage":"An wem wurden die klassischen Experimente eigentlich durchgeführt?","rueckmeldung":[{"option":1,"text":"Dass Selbstverständlichkeit und Wiederholung keine Belege sind, stimmt als Regel. Der Podcast beruft sich aber auf Experimente, und der Effekt selbst ist real. Fraglich ist nur, wie weit diese Experimente reichen, wenn fast nur westliche Versuchspersonen getestet wurden."},{"option":2,"text":"Dass Fachleute allein keine Belege ersetzen, stimmt als Regel. Hier liegen aber Experimente vor; der Podcast beruft sich nicht bloß auf Autorität. Schwach ist die Reichweite der Belege, weil kaum außerhalb des Westens getestet wurde."},{"option":3,"text":"„Zusammenhang ist keine Ursache“ ist eine gute Regel, trifft hier aber nicht zu. Der Podcast behauptet keinen Kausalschluss, sondern dass alle Menschen überall gleich handeln. Der Fehler liegt in der Verallgemeinerung von einer einseitigen Stichprobe auf alle Kulturen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Henrich, J.; Heine, S. J.; Norenzayan, A. (2010): The Weirdest People in the World? RatSWD Working Paper 139 (KonsortSWD)","oeffentlich":true,"url":"https://www.konsortswd.de/wp-content/uploads/RatSWD_WP_139.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Henrich, J.; Heine, S. J.; Norenzayan, A. (2010): The weirdest people in the world? Behavioral and Brain Sciences 33(2–3)","oeffentlich":false,"doi":"10.1017/S0140525X0999152X"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"be0df34f9b7f61a6"}},{"id":"qx-b1-030","clusterId":"B","werkstueckRef":"B.8","stufe":2,"question":"Welche Frage prüft ihre Erklärung am besten?","scenario":"Eine Kollegin sagt über Menschen, die auf Heilkristalle schwören: „Die sind halt naiv und ungebildet.“ Du willst ihre Erklärung prüfen, bevor du sie übernimmst.","options":["Gibt es kontrollierte Studien, die zeigen, ob Heilkristalle über den Placebo-Effekt hinaus wirken?","Welche Hersteller verdienen an Heilkristallen, und wie stark bewerben sie ihre Produkte gegenüber Kunden?","Welche Umstände, etwa Kontrollbedürfnis oder enttäuschende Erfahrungen, machen den Glauben für sie attraktiv?","Wie viele Menschen kaufen Heilkristalle, und wie hat sich diese Zahl in den letzten Jahren entwickelt?"],"correctIndex":2,"explanation":"Die Kollegin führt das Verhalten anderer auf einen stabilen Charakterzug zurück: Sie seien „halt naiv und ungebildet“. Die Situation der Betroffenen blendet sie aus. Diese Verzerrung heißt fundamentaler Attributionsfehler: Wir unterschätzen bei anderen die Macht der Umstände und überschätzen ihre Eigenschaften. Bei Glaubensüberzeugungen können ganz verschiedene Umstände eine Rolle spielen, etwa ein Bedürfnis nach Kontrolle, schlechte Erfahrungen mit der Schulmedizin oder starker sozialer Einfluss im Umfeld. Wer nach ihnen fragt, prüft die Charaktererklärung an der Wirklichkeit. Das ist keine Rechtfertigung des Glaubens, sondern eine bessere Erklärung. Die anderen Fragen sind in anderer Lage sinnvoll, klären hier aber nichts: Ob Heilkristalle wirken, sagt nichts darüber, warum Menschen daran glauben. Wer am Geschäft verdient, erklärt das Angebot, nicht die Nachfrage. Und wie verbreitet der Glaube ist, zeigt nur seine Größe, nicht seine Gründe.","coreRule":"⚡ Frag nach den Umständen, bevor du über den Charakter urteilst.","beleg":"Werkstück B.8 (Anwendung & Relevanz: Bei Aberglaube & Esoterik; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wer fragt, in welcher Lage Menschen so etwas glauben, prüft die Charaktererklärung an der Wirklichkeit. „Naiv und ungebildet“ blendet die Umstände aus: Wir überschätzen bei anderen Eigenschaften und unterschätzen, was Situationen bewirken können.","prueffrage":"Was weiß die Kollegin über diese Menschen, außer dass sie an Heilkristalle glauben?","rueckmeldung":[{"option":0,"text":"Ob Heilkristalle wirken, lässt sich über Studien klären und ist eine berechtigte Frage. Warum Menschen daran glauben, beantwortet sie nicht: Auch Wirkungslosigkeit sagt nichts über die Gründe der Gläubigen."},{"option":1,"text":"Dass Hersteller werben und verdienen, erklärt vor allem das Angebot. Warum Kundinnen und Kunden darauf eingehen, bleibt offen, und gerade das müsstest du klären, um die Erklärung der Kollegin zu prüfen."},{"option":3,"text":"Die Zahl der Käufer und ihr Verlauf zeigen, wie verbreitet der Glaube ist. Warum Menschen so entscheiden, verraten sie nicht, und eine bloße Größe prüft keine Erklärung, die auf Eigenschaften der Käufer zielt."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1) (Kopie auf der Harvard-Seite von D. Gilbert)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ross, L.; Anderson, C. A. (1982): Shortcomings in the attribution process. In: Kahneman, D.; Slovic, P.; Tversky, A. (Hg.): Judgment under Uncertainty. Cambridge University Press, Kap. 9","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7fbcbaaedbbf7d40"}},{"id":"qx-b1-031","clusterId":"B","werkstueckRef":"B.9","stufe":1,"question":"Drei Szenen: Jemand erkennt in einer Wolke ein Tiergesicht. Jemand setzt nach fünfmal Schwarz beim Roulette auf Rot, weil „jetzt Rot dran ist“. Jemand deutet eine zufällige Häufung von Krankheitsfällen in einer Stadt als Zeichen einer Ursache, obwohl die Verteilung statistisch normal ist. Was haben die drei Szenen gemeinsam?","options":["In allen dreien wird im Zufall eine Ordnung gesehen, die gar nicht existiert.","In allen dreien werden nur Belege beachtet, die zu einer vorgefassten Meinung passen.","In allen dreien wird ein Zusammenhang fälschlich als Ursache und Wirkung gedeutet.","In allen dreien folgt der Betrachter dem Urteil einer vermeintlichen Autorität."],"correctIndex":0,"explanation":"Wolke, Roulette-Serie und Krankheitshäufung haben eine gemeinsame Wurzel: Das Gehirn sucht Ordnung und findet sie auch im reinen Zufall. Im ersten Fall ist es ein vermeintliches Gesicht, im zweiten eine scheinbare Gesetzmäßigkeit, nach der die nächste Runde die Serie ausgleichen müsse, obwohl jede Drehung unabhängig von den vorigen ist, im dritten eine zufällige Ballung, der eine besondere Ursache zugeschrieben wird. Die Neigung, Muster zu sehen, wo nur Rauschen ist, heißt Apophenie; der Roulette-Fall wird meist eigens als Spielerfehlschluss bezeichnet und beruht vor allem auf einem falschen Bild von unabhängigen Zufallsereignissen. Die Muster sind dabei nicht echt, sondern entstehen im Kopf des Betrachters; Apophenie ist eine allgemein menschliche Tendenz, die auch in der Allgemeinbevölkerung regelmäßig vorkommt (Blain u. a. 2020). Die anderen Denkfehler gibt es durchaus, sie passen aber nicht zu allen drei Szenen: Ein Bestätigungsfehler setzt eine vorgefasste Meinung voraus, von der bei Wolke und Roulette nichts zu sehen ist. Eine Ursache wird nur in der dritten Szene gesucht, Wolke und Roulette-Serie handeln nicht von Ursache und Wirkung. Und von einer Autorität, der jemand folgt, ist in keiner der drei Szenen die Rede.","coreRule":"⚡ Das Gehirn sieht Muster, auch wo keine sind: in Wolken, Serien und Ballungen.","beleg":"Werkstück B.9 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Gemeinsam ist, dass im bloßen Zufall eine Ordnung gesehen wird: ein Gesicht, eine „fällige“ Farbe, eine Ursache für eine Häufung. Naheliegend ist, jede Szene für sich nach eigener Art zu erklären, statt die gemeinsame Mustersuche des Gehirns zu erkennen.","prueffrage":"Wie oft fällt beim Roulette fünfmal hintereinander dieselbe Farbe, wenn man über viele Abende hinweg zählt?","rueckmeldung":[{"option":1,"text":"Einseitiges Sammeln von Belegen kommt vor, setzt aber eine vorgefasste Meinung voraus. Bei Wolke und Roulette ist von einer solchen Meinung nichts zu sehen, die Antwort passt also nicht auf alle drei Szenen."},{"option":2,"text":"Nur bei der Krankheitshäufung wird eine Ursache gesucht, und die erweist sich als bloßer Zufall. Wolke und Roulette-Serie handeln gar nicht von Ursache und Wirkung, deshalb taugt dies nicht als Gemeinsamkeit."},{"option":3,"text":"Autoritätsgläubigkeit ist ein echter Denkfehler, in diesen Szenen kommt aber keine Autorität vor. Niemand folgt hier einem fremden Urteil; die Deutung entsteht jeweils im Kopf des Betrachters selbst."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives. Journal of Abnormal Psychology 129(3) (PMC, Autorenmanuskript)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives, Verlagsfassung","oeffentlich":false,"doi":"10.1037/abn0000504"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"54f154fdbadda82f"}},{"id":"qx-b1-032","clusterId":"B","werkstueckRef":"B.9","stufe":3,"question":"Welche Schlussfolgerung ist aus diesem Studienergebnis am besten gerechtfertigt?","options":["Der Zusammenhang ist mäßig; ob das Mustersehen den Glauben verursacht, lässt sich aus diesem Ergebnis allein nicht ableiten.","Der Zusammenhang ist mäßig; er zeigt, dass der Verschwörungsglaube das Mustersehen auslöst und nicht umgekehrt.","Der Zusammenhang ist mäßig; er zeigt, dass ein dritter Faktor beide Größen steuert und das Mustersehen selbst nichts bewirkt.","Der Zusammenhang ist mäßig; er reicht aus, um bei jeder einzelnen Person aus dem Mustersehen auf den Glauben zu schließen."],"correctIndex":0,"explanation":"Ein Wert von r = 0,3 liegt weit unter 1: Das Mustersehen erklärt nur einen kleinen Teil der Unterschiede im Verschwörungsglauben, aber ganz ohne Zusammenhang ist es auch nicht. Außerdem sagt eine Korrelation nichts über die Richtung: Vielleicht macht Mustersehen anfällig für Verschwörungen, vielleicht prägt ein verschwörungsnahes Weltbild auch den Blick auf Zufallsdaten, oder ein dritter Faktor wirkt auf beides. Tatsächlich zeigte eine Reihe von Studien (van Prooijen u. a. 2018) Zusammenhänge meist um r = 0,2 bis 0,4. In Versuchen, in denen ein verschwörungsnaher Text das Mustersehen verstärkte, wirkten die Bedingungen teils nur über das Mustersehen auf den Glauben; die Autoren schließen daher starke Schlüsse über Ursache und Wirkung aus. Eine frühere Studie fand keinen solchen Zusammenhang; die Autoren erklären das unter anderem damit, dass er sich bei Hochgebildeten womöglich nicht zeigt. Eine Schlagzeile mit „macht anfällig“ behauptet mehr, als die Zahlen tragen. Dass umgekehrt der Glaube das Mustersehen auslöst, ist denkbar, aber ebenso wenig gezeigt. Auch ein dritter Faktor ist möglich, doch ein mäßiger Zusammenhang belegt ihn nicht und schließt eine Wirkung des Mustersehens nicht aus. Und ein Zusammenhang, der im Durchschnitt einer Gruppe gilt, erlaubt keine sichere Vorhersage für einzelne Personen.","coreRule":"⚡ Mäßige Korrelation heißt: ein Zusammenhang, aber weder vollständige Erklärung noch bewiesene Ursache.","beleg":"Werkstück B.9 (Anwendung & Relevanz: Bei Verschwörungsmythen); Fn. gl-b-prooijen (van Prooijen u. a. 2018, EJSP 48(3), S. 323–324 und 331–332)","status":"entwurf","scenario":"Eine Forschungsgruppe lässt Versuchspersonen Münzwurf-Folgen betrachten und fragt, ob sie darin Muster erkennen. Außerdem erfasst sie, wie sehr die Personen an Verschwörungstheorien glauben. Ergebnis: Wer in den zufälligen Folgen eher Muster sah, glaubte im Schnitt etwas häufiger an Verschwörungen. Der Zusammenhang liegt bei r = 0,3 (zur Orientierung: r = 0 bedeutet kein Zusammenhang, r = 1 ein perfekter). Eine Schlagzeile dazu lautet: „Mustersehen macht anfällig für Verschwörungsglauben!“","quote":"","quoteLabel":"","kurz":"Mit r = 0,3 besteht ein mäßiger Zusammenhang, doch eine Korrelation zeigt weder Richtung noch Ursache. Die Schlagzeile macht aus „tritt zusammen auf“ ein „macht anfällig“, obwohl der Befund auch andere Erklärungen offenlässt.","prueffrage":"Liegt r = 0,3 näher an 0 oder an 1, und hat die Forschungsgruppe das Mustersehen gezielt verändert oder nur gemessen?","rueckmeldung":[{"option":1,"text":"Dass ein verschwörungsnahes Weltbild den Blick auf Zufallsdaten prägt, ist durchaus denkbar. Gezeigt ist es aber so wenig wie die Gegenrichtung: Die Daten zeigen nur, dass beides zusammen auftritt, nicht, was was auslöst."},{"option":2,"text":"Ein dritter Faktor wäre eine mögliche Erklärung. Ein mäßiger Zusammenhang belegt ihn aber nicht und schließt auch nicht aus, dass das Mustersehen selbst etwas beiträgt. „Bewirkt nichts“ geht zu weit."},{"option":3,"text":"Der Zusammenhang ist tatsächlich mäßig, er gilt aber nur im Durchschnitt der Gruppe. Bei r = 0,3 erklärt das Mustersehen nur einen kleinen Teil der Unterschiede, für eine einzelne Person lässt sich daraus nichts sicher vorhersagen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots: Illusory pattern perception predicts belief in conspiracies and the supernatural. European Journal of Social Psychology 48(3) (PMC, CC BY 4.0)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5900972","abruf":"2026-10-12"},{"typ":"doi","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots, Verlagsfassung","oeffentlich":true,"doi":"10.1002/ejsp.2331","seite":"331–332"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8017092137482ff8"}},{"id":"qx-b1-033","clusterId":"B","werkstueckRef":"B.9","stufe":4,"question":"Was ist der erste sinnvolle Prüfschritt?","scenario":"In einem Viertel deiner Gemeinde sind innerhalb eines Jahres auffällig viele Fälle derselben Erkrankung gemeldet worden. Im Ort wird über eine gemeinsame Ursache spekuliert: Manche vermuten das Trinkwasser, andere den Mobilfunkmast am Ortsrand.","options":["Wasserproben nehmen und die Strahlung am Mast messen, um beide Vermutungen anhand von Grenzwerten zu testen.","Die Betroffenen mit Bewohnern eines unauffälligen Viertels vergleichen, um Unterschiede im Alltag zu finden.","Prüfen, ob die Häufung über das zufällig zu Erwartende hinausgeht, bevor nach einer Ursache gesucht wird.","Vorsorglich Maßnahmen gegen die naheliegendste Vermutung fordern, bis die Ursache geklärt ist."],"correctIndex":2,"explanation":"Die Clustering-Illusion beschreibt die Tendenz, in zufälligen Verteilungen „Ballungen“ zu sehen und ihnen eine besondere Bedeutung beizumessen; vermeintliche „Krebscluster“ in einer Stadt erweisen sich bei genauer Prüfung oft als statistisch unauffällig. Der erste Schritt ist deshalb die Frage, ob ein solches Muster auch in rein zufälligen Daten ähnlich wahrscheinlich wäre; erst wenn die Häufung über das zufällig zu Erwartende hinausgeht, lohnt die Suche nach einer Ursache. Messungen an Wasser und Mast sowie der Vergleich mit einem unauffälligen Viertel sind sinnvolle Schritte, aber erst für die Ursachensuche; sie klären nicht, ob überhaupt etwas Besonderes vorliegt. Vorsorgemaßnahmen gegen die naheliegendste Vermutung wären Handeln auf einer ungeprüften Annahme.","coreRule":"⚡ Bevor du ein Muster erklärst, prüfe, ob der Zufall es auch erzeugen könnte.","quote":"„Das kann doch kein Zufall sein!“","quoteLabel":"Typische Aussage:","beleg":"Werkstück B.9 (Kontext & Tiefe: Clustering-Illusion; Red Flags; Das Anti-Denkmuster)","status":"entwurf","kurz":"Zuerst gilt es zu klären, ob die Häufung über das zufällig Erwartbare hinausgeht. Der naheliegende Fehler: in einer Ballung sofort eine Ursache zu sehen, obwohl solche Muster auch in rein zufälligen Daten oft auftreten.","prueffrage":"Wie viele andere Viertel, Jahre und Krankheiten hätte man ebenso betrachten können, und wie oft fiele dabei irgendwo eine Häufung auf?","rueckmeldung":[{"option":0,"text":"Messungen an Wasser und Mast sind für die Ursachensuche sinnvoll, setzen aber voraus, dass die Häufung echt ist. Ob die Fallzahl über den Zufall hinausgeht, zeigen sie nicht, und Grenzwerte sagen nichts über einen Zusammenhang mit den Erkrankungen."},{"option":1,"text":"Der Vergleich mit einem unauffälligen Viertel ist ein guter Schritt, aber erst für die Ursachensuche. Ohne zu wissen, ob die Häufung mehr als Zufall ist, finden sich fast immer irgendwelche Unterschiede im Alltag, auch wo sie nichts erklären."},{"option":3,"text":"Vorsorge wirkt verantwortungsvoll, doch hier richtet sie sich gegen eine Vermutung, die niemand geprüft hat. Handeln auf ungeprüfter Annahme kann Aufwand und Verunsicherung bringen, und es bleibt offen, ob überhaupt etwas Besonderes vorliegt."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"National Cancer Institute: Cancer Clusters Fact Sheet","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/substances/cancer-clusters-fact-sheet","abruf":"2026-10-12"},{"typ":"url","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives (PMC, Autorenmanuskript)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8795b7dad27fd10c"}},{"id":"qx-b1-034","clusterId":"B","werkstueckRef":"B.10","stufe":1,"question":"Du bekommst eine „persönliche Analyse“ und findest dich fast komplett darin wieder. Welche Frage prüft am besten, ob sie wirklich auf dich zugeschnitten ist?","options":["Würden sich auch viele andere Menschen in genau diesen Sätzen wiedererkennen?","Wer hat die App entwickelt, und verdient das Unternehmen mit meinen Antworten Geld?","Werden meine Antworten sicher gespeichert, und wer kann sie später einsehen?","Welche Zusatzfunktionen bietet die App, und ab welchem Preis lohnt sich ein Abo?"],"correctIndex":0,"explanation":"Die Sätze sind so allgemein, dass sie auf fast jeden zutreffen: Fast jeder ist mal gesellig, mal zurückhaltend, fast jeder ist sich selbst gegenüber manchmal kritisch. Sie schmeicheln dem Selbstbild („ungenutzte Fähigkeiten“) und enthalten nur einen Hauch harmloser Kritik, das wirkt echt. Dazu kommt, dass unser Gedächtnis sofort passende Situationen abruft und die unpassenden übergeht. Dass die Aussage auf dich passt, ist deshalb kein Beweis, dass sie für dich gemacht wurde. Entscheidend ist, ob sie auch auf viele andere passen würde. Im Klassenexperiment von Forer (1948) bewerteten Studierende denselben, aus Horoskopen zusammengestellten Text im Schnitt mit 4,26 von 5 als treffend. Wer die App entwickelt hat und womit sie Geld verdient, ist eine berechtigte Frage, sagt aber nichts darüber, ob der Text für dich geschrieben wurde. Dasselbe gilt für den Schutz deiner Daten, der ein eigenes Thema ist. Und was ein Abo kostet, betrifft das Geschäft, nicht die Treffsicherheit der Beschreibung.","coreRule":"⚡ Wenn eine „persönliche“ Beschreibung auf fast jeden passt, sagt sie nichts über dich.","beleg":"Werkstück B.10 (Kontext & Tiefe)","status":"entwurf","scenario":"Eine App wertet einen kurzen Fragebogen aus und schreibt dir: „Du hast ein großes Bedürfnis nach Anerkennung. Manchmal bist du gesellig, manchmal zurückhaltend. Du bist dir selbst gegenüber oft kritisch und hast Fähigkeiten, die du noch nicht voll nutzt.“ Du denkst: „Das bin genau ich!“","quote":"","quoteLabel":"","kurz":"Sätze, die auf fast jeden passen, wirken persönlich, weil wir passende Situationen abrufen und unpassende übergehen. Dass es auf dich passt, beweist daher nicht, dass es für dich gemacht wurde. Prüfe, ob sich viele andere genauso wiederfänden.","prueffrage":"Steht in den Sätzen irgendetwas Konkretes, etwa ein Ereignis, ein Name oder eine Vorliebe, das nur in deinem Leben vorkommt?","rueckmeldung":[{"option":1,"text":"Wer hinter der App steckt und womit er Geld verdient, ist eine berechtigte Frage zu Interessen und Vertrauen. Sie sagt aber nichts darüber, ob dieser Text gerade für dich geschrieben wurde."},{"option":2,"text":"Datensicherheit und Einsicht sind ein wichtiges Thema, aber ein eigenes. Ob die Sätze auf dich zugeschnitten sind, lässt sich damit nicht klären; dafür müsstest du den Text selbst prüfen."},{"option":3,"text":"Funktionen und Abo-Preis zeigen, was die App als Geschäft bietet. Wie treffsicher die Beschreibung ist, erfährst du daraus nicht, denn das hängt allein an den Sätzen selbst."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0fa6cbd602d8c93e"}},{"id":"qx-b1-035","clusterId":"B","werkstueckRef":"B.10","stufe":2,"question":"Was ist an der Schlussfolgerung deiner Freundin am ehesten fehlerhaft?","scenario":"Nach einer Sitzung bei einem Medium sagt eine Freundin begeistert: „Es hat mir gesagt, dass ich mir Sorgen um Geld mache und eine Kiste mit alten Fotos habe, die ich nicht wegwerfen kann. Beides stimmt! Das Medium muss echte Fähigkeiten haben.“ Auf Nachfrage räumt sie ein, dass es auch noch einiges andere gesagt hat, das nicht gepasst hat, daran erinnert sie sich aber kaum noch.","options":["Sie zählt die erinnerten Treffer und übergeht die Fehlschüsse, obwohl solche allgemeinen Aussagen auf fast jeden passen.","Sie hält das Medium wegen seines guten Rufs für glaubwürdig, obwohl ein Ruf nichts über die einzelnen Aussagen sagt.","Sie schließt aus fehlenden Gegenbeweisen auf echte Fähigkeiten, obwohl fehlende Gegenbeweise für sich nichts belegen.","Sie folgt der Menge und hält das Medium für echt, weil es viele überzeugt, obwohl Beliebtheit nichts beweist."],"correctIndex":0,"explanation":"Die Freundin zählt nur die Treffer und blendet die Fehlschüsse aus. „Du machst dir Sorgen um Geld“ und „Du hast eine Kiste mit alten Fotos, die du nicht wegwerfen kannst“ sind typische Barnum-Aussagen aus dem Cold Reading. Ein Cold Reader feuert viele solcher Aussagen ab und beobachtet die Reaktion seines Gegenübers. Die Treffer werden vom Klienten bestätigt und ausgebaut, die Fehlschüsse werden ignoriert. So entsteht der Eindruck großer Treffsicherheit, obwohl nur Allgemeines gesagt wurde. Die anderen Fehlschlüsse gibt es, die Freundin begeht sie aber nicht: Von einem guten Ruf des Mediums ist keine Rede, sie stützt sich allein auf die Treffer. Sie schließt auch nicht aus fehlenden Gegenbeweisen, sondern aus erinnerten Treffern. Und andere Gläubige erwähnt sie nicht, sie urteilt nach ihrem eigenen Erlebnis.","coreRule":"⚡ Wer nur die Treffer zählt und die Fehlschüsse vergisst, hält Allgemeinplätze für Treffsicherheit.","beleg":"Werkstück B.10 (Anwendung & Relevanz: Bei Wahrsagern, Hellsehern & Cold Reading)","status":"entwurf","kurz":"Die Freundin zählt nur die Treffer und blendet die Fehlschüsse aus. Aussagen wie „Du machst dir Sorgen um Geld“ passen auf fast jeden; erst das Vergessen der Daneben-Aussagen lässt daraus große Treffsicherheit werden.","prueffrage":"Wie viele andere Aussagen hat das Medium gemacht, und wie viele davon haben tatsächlich gepasst?","rueckmeldung":[{"option":1,"text":"Ein guter Ruf kann tatsächlich über einzelne Aussagen hinwegtäuschen. Davon ist hier aber keine Rede: Die Freundin begründet ihr Urteil allein mit den beiden Treffern aus ihrer eigenen Sitzung."},{"option":2,"text":"Dass fehlende Gegenbeweise nichts belegen, stimmt als Grundsatz. Die Freundin argumentiert aber nicht mit dem Ausbleiben einer Widerlegung, sondern mit zwei erlebten Treffern."},{"option":3,"text":"Dass Beliebtheit nichts beweist, stimmt, und der Fehler kommt oft vor. Andere Gläubige tauchen hier aber gar nicht auf: Die Freundin urteilt nach dem, was sie selbst erlebt hat."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Selective Attention“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b962ad57f8308a75"}},{"id":"qx-b1-036","clusterId":"B","werkstueckRef":"B.10","stufe":3,"question":"Wie viel von dieser Namensgeschichte darfst du als gesichert ansehen?","options":["Dass Barnum auf ein breites Publikum zielte, gilt als gesichert, weil sein Geschäft gut dokumentiert ist; ob er den Satz sagte, bleibt ohne Quelle offen.","Dass Barnum den Satz sagte, gilt als gesichert, weil ihn der Artikel ausdrücklich nennt; offen ist nur, bei welcher Gelegenheit er ihn sagte.","Dass der Effekt auf Barnum selbst zurückgeht, gilt als gesichert, weil er seinen Namen trägt; offen ist nur, in welchem Jahr er ihn beschrieb.","Nichts davon gilt als gesichert, weil ein unbelegtes Zitat die ganze Namensgeschichte unglaubwürdig macht, auch Barnums Ruf als Schausteller."],"correctIndex":0,"explanation":"Hier gilt es, zweierlei zu trennen: Barnums Ruf und den angeblichen Wortlaut. Real ist sein Ruf als Schausteller, der sein Programm bewusst auf ein möglichst breites Publikum zuschnitt. Der Satz „Wir haben für jeden etwas dabei“ ist ihm dagegen nur populär zugeschrieben, ohne Beleg. Ein Zitat wird nicht dadurch belegt, dass es oft wiederholt wird oder gut zur Person passt. Auch das noch bekanntere „Alle naslang wird ein Dummkopf geboren“ ist nicht verifiziert. Und der Name „Barnum-Effekt“ stammt nicht von Barnum selbst: Er wurde 1956 vom Psychologen Paul E. Meehl geprägt, der ihn nach Barnums Ruf benannte. Der Effekt geht also nicht auf Barnum zurück, nur sein Name wurde geliehen. Wer einem Zitat oder einer Namensgebung vertrauen will, fragt deshalb nach der Quelle, nicht nach der Bekanntheit. Dass der Artikel den Satz nennt, belegt ihn nicht, denn er führt keine Quelle an. Ein Name beweist keinen Ursprung. Und Skepsis gegenüber dem unbelegten Zitat ist richtig, entwertet aber nicht, was unabhängig davon dokumentiert ist.","coreRule":"⚡ Ein oft wiederholtes Zitat ist noch kein belegtes Zitat: Frag nach der Quelle.","beleg":"Werkstück B.10 (Kontext & Tiefe); Fn. gl-b-barnum","status":"entwurf","scenario":"In einem Artikel über Persönlichkeitstests steht: „Der Barnum-Effekt geht auf den Zirkusmann P. T. Barnum zurück, der einst sagte: ‚Wir haben für jeden etwas dabei.‘“ Ein Beleg für den Satz wird nicht genannt, der Artikel verweist nur auf Barnums Ruf als Schausteller.","kurz":"Gesichert ist Barnums Ruf als Schausteller mit breitem Publikum, nicht der Wortlaut des Zitats. Naheliegend ist, ein Zitat zu glauben, weil es gut zur Person passt oder oft wiederholt wird; belegt wird es nur durch eine Quelle.","prueffrage":"Wann bekam der Effekt seinen Namen, und lebte Barnum da noch?","rueckmeldung":[{"option":1,"text":"Dass der Artikel den Satz nennt, macht ihn noch nicht verlässlich, denn er führt keine Quelle an. Offen ist deshalb mehr als die Gelegenheit: ob Barnum ihn überhaupt sagte, bleibt ungeklärt."},{"option":2,"text":"Ein Name zeigt, wem etwas gewidmet oder geliehen wurde, nicht, von wem es stammt. Der Begriff wurde 1956 von Paul E. Meehl geprägt und nach Barnums Ruf benannt; beschrieben hat Barnum den Effekt nie."},{"option":3,"text":"Misstrauen gegenüber dem unbelegten Zitat ist berechtigt. Es erfasst aber nur das Zitat: Barnums Ruf als Schausteller ist unabhängig davon dokumentiert und wird durch den fehlenden Beleg nicht berührt."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Barnum effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/barnum.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Meehl, P. E. (1956): Wanted—a good cook-book. American Psychologist 11(6), 263–272","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"743b8e681028224f"}},{"id":"qx-b1-037","clusterId":"B","werkstueckRef":"B.10","stufe":4,"question":"Was folgt aus dem Treffer für die Frage, ob der Dienst dich persönlich „durchschaut“?","scenario":"Dein Streamingdienst schlägt dir einen Song vor, der genau zu deiner Stimmung passt, und du denkst: „Der kennt mich besser als meine Freunde.“ Du weißt, dass der Dienst seine Vorschläge aus den Hörgewohnheiten sehr vieler Nutzer ableitet.","options":["Er zeigt nichts Sicheres, denn ein auf breite Muster gestützter Vorschlag kann sich persönlich anfühlen, ohne dich persönlich zu erfassen.","Er zeigt, dass der Dienst dich persönlich gut kennt, denn ein so genau passender Song entsteht ohne persönliches Verständnis kaum.","Er zeigt, dass der Dienst dich weniger gut kennt als deine Freunde, denn ein Algorithmus kann Stimmungen nicht erfassen.","Er zeigt, dass der Dienst dich gezielt an sich binden will, denn Empfehlungen sollen Nutzer möglichst lange beim Angebot halten."],"correctIndex":0,"explanation":"Das gute Gefühl allein sagt wenig darüber, wie der Vorschlag zustande kam. Algorithmen stützen sich oft auf breite statistische Muster, die auf Millionen von Menschen zutreffen, sich für den Einzelnen aber ganz persönlich anfühlen. Das ist ein digitaler Barnum-Effekt: Bereits 1948 gab der Psychologe Bertram Forer seinen Studenten allen denselben, aus Horoskopen zusammengestückelten Text. Sie bewerteten ihn im Mittel mit 4,26 auf einer Skala von 0 bis 5, obwohl er für niemanden maßgeschneidert war. Die gefühlte Treffsicherheit ist deshalb kein Beleg für tiefes Verstehen. Der Schluss vom Treffer auf gutes Kennen geht vom Gefühl auf die Ursache. Auch das Gegenteil, der Dienst kenne dich schlechter als deine Freunde, folgt aus einem einzelnen Treffer nicht. Dass Empfehlungen Nutzer an den Dienst binden sollen, mag stimmen, beantwortet aber nicht, ob der Dienst dich persönlich erfasst.","coreRule":"⚡ Gefühlte Treffsicherheit ist kein Beweis für echtes Verstehen.","beleg":"Werkstück B.10 (Anwendung & Relevanz: Bei algorithmischer Personalisierung)","status":"entwurf","kurz":"Wie gut der Song passt, sagt nichts darüber, wie er zustande kam. Breite Muster aus vielen Nutzern können sich ganz persönlich anfühlen, ohne dass der Dienst dich als Einzelne oder Einzelnen erfasst.","prueffrage":"Woraus leitet der Dienst seine Vorschläge ab, und was davon betrifft nur dich?","rueckmeldung":[{"option":1,"text":"Dass der Song so gut passt, wirkt wie ein Beleg für persönliches Verständnis. Das Gefühl der Passung verrät aber nicht, wie der Vorschlag entstand, und ein Muster aus vielen Nutzern kann sich genauso persönlich anfühlen."},{"option":2,"text":"Ein einzelner Treffer spricht nicht dafür, dass der Dienst dich gut kennt, und ebenso wenig dagegen. Auch der Grund trägt nicht: Aus Hörgewohnheiten lassen sich durchaus Hinweise auf Stimmungen ableiten, und was deine Freunde über dich wissen, steht gar nicht zur Debatte."},{"option":3,"text":"Dass Empfehlungen Nutzer binden sollen, mag durchaus stimmen. Es beantwortet aber eine andere Frage als die, ob der Dienst dich persönlich erfasst, und lässt sich aus einem einzelnen guten Vorschlag auch nicht ablesen."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9d37b6b4245a8f62"}},{"id":"qx-b1-038","clusterId":"B","werkstueckRef":"B.11","stufe":1,"question":"Welche Schlussfolgerung ist aus der Beobachtung gerechtfertigt?","scenario":"Du siehst nachts ein Licht, das schnell fliegt, plötzlich stehen bleibt und abrupt die Richtung ändert. Dein Freund sagt: „Ich kenne kein Flugzeug und keinen Satelliten, die das können – also muss es ein außerirdisches Raumschiff sein!“","options":["Es war ein außerirdisches Raumschiff, denn kein bekanntes Flugzeug und kein Satellit kann sich so bewegen.","Es war ein Flugzeug oder eine Drohne, denn die meisten gemeldeten Himmelslichter erweisen sich als gewöhnliche Objekte.","Es war eine optische Täuschung, denn ein Licht ohne Bezugspunkte am Nachthimmel scheint sich oft sprunghaft zu bewegen.","Es war ein unidentifiziertes Flugobjekt im wörtlichen Sinn, denn ich weiß schlicht nicht, was es war."],"correctIndex":3,"explanation":"Die Beobachtung zeigt nur, dass dein Freund keine Erklärung kennt. Das ist eine Aussage über den Stand seines Wissens, nicht über die Ursache des Lichts. Aus „mir fällt keine natürliche Erklärung ein“ folgt nicht, dass die Lieblingserklärung stimmt, und ebenso wenig, dass das Phänomen nicht stattgefunden hat oder doch ein gewöhnliches Objekt war. Eine Wissenslücke ist kein Beweis für irgendeine bestimmte Erklärung. Gerechtfertigt ist nur die ehrliche Feststellung, dass das Licht unidentifiziert bleibt. Sinnvoll ist dann, die Lücke zu untersuchen, statt sie mit einer bevorzugten Erklärung zu füllen. Dass die meisten gemeldeten Lichter gewöhnlich sind, spricht für eine Vermutung, entscheidet diesen Einzelfall aber nicht. Eine optische Täuschung ist als Möglichkeit denkbar, aber hier nicht gezeigt. Und was ein Mensch nicht kennt, sagt nichts darüber, was möglich ist.","coreRule":"⚡ „Ich weiß es nicht“ ist eine vollständige und ehrliche Antwort: Eine Wissenslücke beweist keine bestimmte Erklärung.","beleg":"Werkstück B.11 (Das Licht am Nachthimmel; Kontext & Tiefe)","status":"entwurf","kurz":"Aus „mir fällt keine Erklärung ein“ folgt keine bestimmte Erklärung, denn das beschreibt nur das Wissen deines Freundes, nicht das Licht. Ehrlich gerechtfertigt ist nur: Es bleibt unidentifiziert, und diese Lücke lässt sich untersuchen.","prueffrage":"Was lässt sich bei einem Licht am Nachthimmel mit bloßem Auge über seine Entfernung, Größe und Geschwindigkeit sicher sagen?","rueckmeldung":[{"option":0,"text":"Dass deinem Freund nichts Bekanntes einfällt, stimmt vermutlich. Es beschreibt aber nur seinen Kenntnisstand, nicht das Licht. Die Lücke in seinem Wissen belegt keine Ursache, schon gar keine so besondere."},{"option":1,"text":"Dass die meisten gemeldeten Himmelslichter gewöhnlich sind, spricht für eine Vermutung. Für diesen einen Fall entscheidet es aber nichts. Auch hier würde die Lücke mit einer bevorzugten Erklärung gefüllt, nur in die andere Richtung."},{"option":2,"text":"Ohne Bezugspunkte scheinen Lichter am Nachthimmel tatsächlich oft zu springen, als Möglichkeit ist das denkbar. Im Szenario zeigt aber nichts, dass hier eine Täuschung vorlag; als Feststellung wäre es wieder eine ungeprüfte Lückenfüllung."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7da5bfe6de926cd6"}},{"id":"qx-b1-039","clusterId":"B","werkstueckRef":"B.11","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Dein Onkel sagt: „Es gibt keinen einzigen Beweis, dass es Leben auf anderen Planeten gibt – also gibt es keins.“","options":["Er folgert aus dem fehlenden Beweis, dass es keins gibt, obwohl ein fehlender Beweis allein noch nicht zeigt, dass etwas nicht existiert.","Er setzt im Schluss schon voraus, was er erst zeigen will, obwohl eine Behauptung nicht zugleich der Beleg für sich selbst sein darf.","Er lässt nur zwei Möglichkeiten gelten und blendet andere aus, obwohl sich die meisten Fragen nicht auf zwei Antworten verengen lassen.","Er widerlegt eine überspitzte Fassung der Gegenposition, obwohl diese Fassung von niemandem vertreten wird und das Argument deshalb nichts trifft."],"correctIndex":0,"explanation":"Der Onkel schließt von „nicht bewiesen“ auf „falsch“. Das ist das Argument aus Unwissenheit: Ein fehlender Beweis allein zeigt nicht, dass etwas nicht existiert, sondern zunächst nur, dass wir es nicht wissen. Gewicht bekommt das Fehlen eines Belegs erst, wenn gründlich dort gesucht wurde, wo ein Beleg zu erwarten wäre; über die allermeisten Planeten wissen wir dafür noch viel zu wenig. Der Fehler liegt also im Übergang von der Wissenslücke zur festen Aussage. Zulässig wäre: „Ich kenne keinen Beleg und halte die Frage deshalb für offen.“ Die anderen Fehlschlüsse gibt es, der Onkel begeht sie aber nicht: Sein Grund, der fehlende Beweis, ist nicht schon die Behauptung selbst, es liegt also kein Zirkelschluss vor. Dass es Leben gibt oder nicht gibt, deckt alle Möglichkeiten ab, ein falsches Dilemma ist es deshalb nicht. Und eine Gegenposition, die er verzerren könnte, kommt in seinem Satz gar nicht vor.","coreRule":"⚡ Kein Beweis dafür heißt nicht „falsch“, kein Beweis dagegen nicht „wahr“.","beleg":"Werkstück B.11 (Kontext & Tiefe: Negative Form)","status":"entwurf","kurz":"Aus „nicht bewiesen“ folgt noch nicht „falsch“: Ein fehlender Beweis zeigt zunächst nur, dass wir etwas nicht wissen. Gewicht bekäme er erst, wenn dort gründlich gesucht wurde, wo ein Beleg zu erwarten wäre, und das ist bei fremden Planeten kaum der Fall.","prueffrage":"Was genau wurde bisher untersucht, und was würde man finden, wenn es dort doch etwas gäbe?","rueckmeldung":[{"option":1,"text":"Ein Zirkelschluss steckt hier nicht: Der Grund, dass es keinen Beweis gibt, ist nicht schon die Behauptung selbst. Der Fehler liegt woanders, nämlich im Sprung von der Wissenslücke zur festen Aussage."},{"option":2,"text":"Falsche Dilemmata gibt es oft, hier aber nicht: „Leben gibt es oder gibt es nicht“ deckt alle Möglichkeiten ab. Nicht die Auswahl der Möglichkeiten ist das Problem, sondern der Schluss, den der Onkel aus der Beweislage zieht."},{"option":3,"text":"Ein Strohmann verzerrt die Position eines Gegenübers. Im Satz des Onkels kommt aber gar keine Gegenposition vor, die er überspitzen könnte. Er stützt seine eigene Behauptung auf eine Lücke im Wissen, und dort liegt der Fehler."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b3b34e4f1ccdad74"}},{"id":"qx-b1-040","clusterId":"B","werkstueckRef":"B.11","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"In einer Debatte heißt es: „Die Wissenschaft kann bisher nicht bis ins letzte Detail erklären, wie das erste Leben aus unbelebter Materie entstand. Also muss es erschaffen worden sein.“","options":["Der Schluss ist fehlerhaft, weil er der Wissenschaft eine Behauptung unterstellt, die sie nie aufgestellt hat, um sie leichter anzugreifen.","Der Schluss ist fehlerhaft, weil er die Erschaffung schon voraussetzt, um sie zu belegen, und seine Behauptung so zum eigenen Beleg macht.","Der Schluss ist fehlerhaft, weil aus einer Wissenslücke keine bestimmte Erklärung folgt; sie zeigt nur, dass etwas noch offen ist.","Der Schluss ist fehlerhaft, weil er die Forschenden persönlich herabsetzt, statt sich mit ihren Ergebnissen sachlich auseinanderzusetzen."],"correctIndex":2,"explanation":"Eine Wissenslücke ist selbst kein Beleg für eine bestimmte Erklärung. Aus „Das wissen wir noch nicht“ folgt nicht „Also gilt meine bevorzugte Antwort“. Dieser Fehlschluss heißt Argument aus Unwissenheit, in religiösen Zusammenhängen auch „Gott der Lücken“: Eine aktuelle Lücke im wissenschaftlichen Verständnis wird als Beweis für die eigene Position ausgegeben. Dabei wird die Lücke willkürlich mit einer bevorzugten, unbewiesenen Erklärung gefüllt. Die ehrliche Antwort auf eine Lücke lautet: „Das wissen wir (noch) nicht.“ Die Aussage über den Stand der Forschung ist hier zutreffend dargestellt, ein Strohmann liegt also nicht vor. Der einzige Grund des Schlusses ist die Lücke, nicht die Erschaffung selbst, ein Zirkelschluss ist es deshalb nicht. Und die Forschenden werden nicht persönlich angegriffen.","coreRule":"⚡ Eine Wissenslücke ist eine Frage, keine Antwort.","beleg":"Werkstück B.11 (Anwendung & Relevanz: Im Kreationismus & „Intelligent Design“; Der Kipppunkt)","status":"entwurf","kurz":"Eine offene Frage der Forschung belegt keine bestimmte Antwort. Der Fehler: Aus „das weiß man noch nicht“ wird „also gilt meine Erklärung“, als müsste jede Lücke gefüllt werden. Ehrlich ist hier nur: noch offen.","prueffrage":"Welche Beobachtung nennt die Aussage, die für sich genommen auf eine Erschaffung hindeutet?","rueckmeldung":[{"option":0,"text":"Ein Strohmann verzerrt die Gegenseite, um sie leichter anzugreifen. Hier ist der Forschungsstand aber zutreffend wiedergegeben, die Lücke besteht tatsächlich. Das Problem liegt erst in dem, was daraus gefolgert wird."},{"option":1,"text":"Zirkelschlüsse setzen ihre Behauptung schon in den Prämissen voraus. Hier steht die Erschaffung aber erst am Ende; als einziger Grund dient die Lücke. Fehlerhaft ist, dass diese Lücke mit einer bevorzugten Erklärung gefüllt wird."},{"option":3,"text":"Ein persönlicher Angriff wertet Menschen ab, statt ihre Argumente zu prüfen. Die Forschenden werden hier aber gar nicht herabgesetzt. Es geht nur um den Stand des Wissens, und der ist korrekt beschrieben."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"788061e1674b42dc"}},{"id":"qx-b1-041","clusterId":"B","werkstueckRef":"B.12","stufe":1,"question":"Welcher Denkfehler steckt in der Schlussfolgerung der Zuschauerin, und woran liegt er?","scenario":"Ein Nachrichtenmagazin kündigt eine Sondersendung an: „Die Form der Erde: Gibt es eine Kontroverse?“ Eine Astrophysikerin und ein YouTuber, der die Erde für eine Scheibe hält, bekommen exakt gleich viel Redezeit. Der Moderator schließt: „Eine faszinierende Diskussion mit vielen offenen Fragen. Bilden Sie sich Ihre eigene Meinung.“ Eine Zuschauerin sagt danach: „Dann scheint sich die Wissenschaft ja nicht einig zu sein.“","options":["Sie schließt von der gleichen Redezeit zweier Gäste auf eine gleich starke Beweislage, obwohl die Sendung nichts über die Verteilung der Expertenmeinungen sagt.","Sie schließt von der Fachrolle der Astrophysikerin auf die Richtigkeit ihrer Aussagen, obwohl auch Fachleute sich irren können und ein Titel allein nichts beweist.","Sie schließt von der Zahl der Anhänger des YouTubers auf die Richtigkeit seiner Behauptung, obwohl Beliebtheit nichts darüber sagt, ob etwas stimmt.","Sie liest nur die Aussagen heraus, die zu ihrer bisherigen Meinung passen, obwohl eine faire Prüfung auch Gegenhinweise berücksichtigen muss."],"correctIndex":0,"explanation":"Wie viel Bühne und Redezeit jemand bekommt, sagt nichts darüber, wie viele Fachleute seine Position teilen oder wie gut sie belegt ist. Bei der Form der Erde stützen Satellitendaten, Flugrouten, Erdkrümmung und astronomische Beobachtungen eine Seite erdrückend, die andere hat dem nichts Vergleichbares entgegenzusetzen. Die Sendung formt trotzdem den Eindruck einer 50/50-Kontroverse unter Experten, und die Zuschauerin übernimmt ihn. Bei politischen Meinungsfragen ist es sinnvoll, beide Seiten anzuhören. Bei Fragen mit erdrückender Beweislage verzerrt dasselbe Prinzip die Realität. Die richtige Prüffrage lautet daher nicht „Wurden beide gehört?“, sondern „Wie verteilen sich Belege und Fachmeinungen tatsächlich?“. Dass der Moderator beide Positionen als gleichwertig behandelt und die Beweislage nicht einordnet, überlässt die Wahrheitsfindung dem Publikum und erzeugt den falschen Eindruck einer Kontroverse. Die anderen Fehlschlüsse gibt es, die Zuschauerin begeht sie aber nicht: Sie beruft sich nicht auf den Titel der Astrophysikerin, sondern zieht ihren Schluss aus dem Anschein der Sendung. Von der Beliebtheit des YouTubers ist keine Rede. Und von einer vorgefassten Meinung, die sie bestätigt sucht, steht im Szenario nichts.","coreRule":"⚡ Gleiche Redezeit ist keine gleiche Beweislage.","beleg":"Werkstück B.12 (Die Debatte über die Form der Erde; Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Gleiche Redezeit zeigt nur, wie die Sendung gebaut ist, nicht, wie sich Belege und Fachmeinungen verteilen. Aus der Bühne auf eine echte Kontroverse unter Fachleuten zu schließen, ist der Fehler; hier stützt die Beweislage eine Seite erdrückend.","prueffrage":"Was weißt du über die Form der Erde aus anderen Quellen, etwa von Satellitenbildern oder Flugrouten, und passt das zu einer offenen Streitfrage?","rueckmeldung":[{"option":1,"text":"Allein auf einen Titel zu bauen, wäre in der Tat ein Fehlschluss. Die Zuschauerin tut das aber nicht: Sie beruft sich nirgends auf die Astrophysikerin, sondern schließt aus dem Eindruck, den die Sendung erzeugt."},{"option":2,"text":"Dass Beliebtheit nichts über Wahrheit sagt, stimmt allgemein. Im Szenario spielt die Zahl der Anhänger des YouTubers aber keine Rolle; der Schluss entsteht aus der gleichen Bühne beider Gäste."},{"option":3,"text":"Sich nur Passendes herauszupicken, ist ein bekannter Fehler. Hier steht aber nichts über eine vorgefasste Meinung der Zuschauerin; sie übernimmt den Eindruck, den die Sendung selbst vermittelt."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016, Journal of Experimental Psychology: Applied)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1ac4822ddfa429e4"}},{"id":"qx-b1-042","clusterId":"B","werkstueckRef":"B.12","stufe":2,"question":"Welche Frage deckt am besten auf, dass diese Gleichbehandlung das Bild verzerren könnte?","scenario":"Du siehst eine Talkrunde zu einem Gesundheitsthema: links eine Epidemiologin, die den breiten Befund der Fachliteratur vertritt, rechts ein Gast mit eigener Theorie, die kaum ein Fachmensch teilt. Beide bekommen gleich viel Redezeit, und der Moderator schließt mit: „Eine spannende Kontroverse, bilden Sie sich Ihre eigene Meinung.“","options":["Haben die Gäste ein finanzielles Interesse am Ausgang der Debatte, das ihre Aussagen färben könnte?","Entspricht die Verteilung der Gäste der tatsächlichen Verteilung der Expertenmeinungen im Fachgebiet?","Wurden beiden Gästen dieselben Fragen gestellt, und durften sie auf die Einwände des anderen antworten?","Lassen sich die Quellen, auf die sich beide Gäste berufen, für Zuschauer öffentlich einsehen und überprüfen?"],"correctIndex":1,"explanation":"Ob eine Debatte das Bild der Wirklichkeit wiedergibt, hängt nicht davon ab, wie fair die Bühne gebaut ist, sondern davon, wie die Beweislage tatsächlich verteilt ist. Wenn nahezu alle Fachleute eine Position teilen und nur eine Handvoll die andere, erzeugen zwei gleich große Redeanteile beim Publikum den falschen Eindruck eines 50/50-Streits unter Experten. Wer das prüfen will, vergleicht die Verteilung der Gäste mit der Verteilung der Expertenmeinungen im Feld. Äußere Fairness kann eine innere Verzerrung sogar verdecken. Die anderen Fragen sind für sich sinnvoll, treffen hier aber nicht den Kern: Ein Interesse der Gäste würde nur ihre Glaubwürdigkeit betreffen und sagt nichts darüber, wie viele Fachleute hinter welcher Position stehen. Gleiche Fragen und Erwiderungsrechte gehören zur Fairness im Ablauf und verstärken eher den Eindruck eines Gleichstands. Nachprüfbare Quellen sind wünschenswert, zeigen aber nicht, welches Gewicht die Positionen im Fach haben.","coreRule":"⚡ Frag nicht nach der Fairness der Bühne, sondern nach dem Gewicht der Belege.","beleg":"Werkstück B.12 (Das Anti-Denkmuster; Red Flags)","status":"entwurf","kurz":"Entscheidend ist, wie viele Fachleute hinter welcher Position stehen. Gleiche Redezeit täuscht bei einer Handvoll Abweichler einen 50/50-Streit unter Experten vor, obwohl die Bühne fair wirkt.","prueffrage":"Woran hättest du als Zuschauer in der Sendung erkennen können, dass der zweite Gast mit seiner Theorie in der Fachwelt fast allein steht?","rueckmeldung":[{"option":0,"text":"Ein Eigeninteresse kann Aussagen färben, und das zu prüfen ist sinnvoll. Es betrifft aber nur, wie glaubwürdig ein einzelner Gast ist, nicht, wie viele Fachleute welche Position teilen."},{"option":2,"text":"Gleiche Fragen und Erwiderungsrechte sprechen für einen fairen Ablauf. Gerade dieser faire Rahmen kann aber den Eindruck eines Gleichstands noch verstärken, statt die Verzerrung aufzudecken."},{"option":3,"text":"Nachprüfbare Quellen sind wünschenswert. Sie zeigen aber nicht, welches Gewicht eine Position im Fach hat: Auch eine Außenseitertheorie kann offen belegt sein."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1fe9f73fe02276db"}},{"id":"qx-b1-043","clusterId":"B","werkstueckRef":"B.12","stufe":3,"question":"Ein Nachrichtenmagazin plant zwei Beiträge. Beitrag 1: Ist die Erde eine Kugel? Beitrag 2: Bei der Behandlung einer seltenen Krankheit gehen zwei Forschungsgruppen mit jeweils guter Datenlage von unterschiedlichen Wirkmechanismen aus, und die Fachwelt ist gespalten. Wie sollte die Redaktion die beiden Beiträge anlegen?","options":["In beiden Beiträgen sollte die Moderation nur Fragen stellen und nichts einordnen, weil Journalismus bloß wiedergibt.","In beiden Beiträgen sollte die Gegenseite einen kurzen Einwurf bekommen, weil so Vielfalt gewahrt bleibt, ohne die Hauptposition zu schwächen.","Nur im zweiten Beitrag sollten beide Seiten ausführlich zu Wort kommen, weil nur dort die Fachwelt wirklich gespalten ist.","In beiden Beiträgen sollten die Positionen nach ihrem Rückhalt im Publikum gewichtet werden, weil es sich vertreten sehen will."],"correctIndex":2,"explanation":"Zwei Seiten gleichwertig darzustellen ist nur sinnvoll, wenn die Frage wirklich offen ist. Bei der seltenen Krankheit stützen beide Positionen belastbare Daten, und die Fachwelt ist tatsächlich gespalten; hier bildet eine Debatte die Lage korrekt ab. Bei der Kugelgestalt der Erde gibt es keine legitime wissenschaftliche Kontroverse mehr; die Frage gilt als längst entschiedene Kernfrage der Wissenschaft. Eine Debatte mit gleicher Redezeit erzeugt beim Publikum den falschen Eindruck einer 50/50-Kontroverse unter Experten und verzerrt die Realität. Gleiche Redezeit ist kein Maß für Fairness: Entscheidend ist, ob die Verteilung der Positionen im Beitrag der tatsächlichen Verteilung der Expertenmeinungen und der Beweislage entspricht. Die anderen Gedanken klingen vertretbar, passen hier aber nicht: Eine Moderation, die nichts einordnet, überlässt dem Publikum die Bewertung und lässt beim Beitrag zur Erde einen Streit entstehen, den es unter Fachleuten nicht gibt. Ein kurzer Einwurf der Gegenseite wäre beim ersten Beitrag unnötig und würde beim zweiten die gespaltene Fachwelt unterschlagen. Und die Stimmung im Publikum sagt nichts darüber, wie Belege und Expertenmeinungen verteilt sind.","coreRule":"⚡ Zwei Seiten gehören dorthin, wo die Frage wirklich offen ist. Gewichte Positionen nach Beweislage, nicht nach Redezeit.","beleg":"Werkstück B.12 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"Die Redaktion möchte „fair und ausgewogen“ berichten und überlegt, in beiden Beiträgen jeweils zwei Gäste mit gleicher Redezeit auftreten zu lassen.","kurz":"Eine Debatte mit zwei Seiten bildet die Lage nur ab, wenn die Frage wirklich offen ist, wie bei der Krankheit mit zwei gut belegten Positionen. Gleiche Redezeit zur Kugelgestalt der Erde täuschte einen Expertenstreit vor, den es nicht gibt.","prueffrage":"Was unterscheidet die Datenlage hinter den Positionen beim ersten Thema von der beim zweiten?","rueckmeldung":[{"option":0,"text":"Zurückhaltung der Moderation wirkt neutral und passt noch zur offenen Frage. Wer aber gar nichts einordnet, überlässt dem Publikum die Bewertung und lässt beim Erd-Beitrag einen Streit entstehen, den es unter Fachleuten nicht gibt."},{"option":1,"text":"Vielfalt zu wahren ist ein berechtigtes Anliegen. Beim Erd-Beitrag braucht es aber gar keinen Einwurf, und beim Krankheits-Beitrag würde ein kurzer Einwurf verschweigen, dass die Fachwelt gespalten ist und beide Gruppen gute Daten haben."},{"option":3,"text":"Das Publikum zu erreichen ist ein legitimes Ziel, etwa bei Themenwahl und Verständlichkeit. Seine Stimmung sagt aber nichts darüber, wie sich Belege und Expertenmeinungen verteilen, und taugt deshalb nicht als Maßstab für die Gewichtung der Positionen."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"70d2a9e8b2fa9b6b"}},{"id":"qx-b1-044","clusterId":"B","werkstueckRef":"B.12","stufe":4,"question":"Welche Wirkung hat dieses Format auf Zuschauer, die das Thema nicht aus eigener Sachkenntnis beurteilen können?","scenario":"Ein Fernsehsender plant eine Sondersendung zum Klimawandel. Im Studio sitzen zwei Gäste: eine Klimaforscherin, deren Aussagen dem Stand der Fachliteratur entsprechen, und ein Redner, der die menschengemachte Erwärmung bestreitet und mit seiner Haltung unter Fachleuten kaum Rückhalt hat. Der Moderator gibt beiden exakt gleich viel Redezeit und schließt mit den Worten: „Eine spannende Debatte mit offenem Ausgang. Bilden Sie sich Ihre eigene Meinung.“","options":["Sie gewinnen den Eindruck, unter Fachleuten sei die Frage noch offen (falsche Ausgewogenheit), obwohl die Fachwelt weitgehend einig ist.","Sie übernehmen die Haltung der Mehrheit im Studio (Mitläufereffekt), weil man sich lieber dem größeren Lager anschließt als dem kleineren.","Sie bewerten alle weiteren Aussagen im Vergleich zur ersten genannten Zahl (Ankereffekt), obwohl diese Zahl beliebig gewählt sein kann.","Sie halten das Thema für dringlicher, als es ist (Verfügbarkeitsheuristik), weil eindrückliche Bilder leichter im Gedächtnis bleiben."],"correctIndex":0,"explanation":"Wer nicht selbst beurteilen kann, wie verbreitet eine Position unter Fachleuten ist, schließt aus der Bühne auf das Gewicht: Gleiche Redezeit und ein offenes Schlusswort legen nahe, dass sich zwei etwa gleich starke Lager gegenüberstehen. Tatsächlich bejahen über 99 % der einschlägigen Fachartikel eine menschengemachte Erwärmung; die Beweislage ist also keineswegs 50 zu 50. Gleiche Bühnenzeit bildet nicht die Beweislage ab, sondern verzerrt sie (falsche Ausgewogenheit). Eine bloße Gegenüberstellung ersetzt außerdem keine Einordnung: Die Bewertung der Beweiskraft wird dem unvorbereiteten Zuschauer überlassen. Die anderen Mechanismen gibt es durchaus, sie passen aber nicht zu dieser Sendung: Einen Mitläufereffekt gibt es nur, wenn eine Mehrheit sichtbar ist, im Studio sitzen aber nur zwei Gäste mit gleichem Raum. Ein Ankereffekt braucht eine genannte Zahl, die hier nicht fällt. Und die Verfügbarkeitsheuristik betrifft eindrückliche Bilder und Beispiele, von denen im Szenario keine Rede ist.","coreRule":"⚡ Eine 50:50-Bühne kann eine 99:1-Fachwelt als Streit erscheinen lassen.","beleg":"Werkstück B.12 (Anwendung & Relevanz: Bei der Leugnung des Klimawandels; Verweis auf Band VI)","status":"entwurf","kurz":"Wer das Thema nicht selbst beurteilen kann, schließt von der Bühne auf die Beweislage: Gleiche Redezeit und ein offenes Ende suggerieren zwei etwa gleich starke Lager, obwohl die Fachwelt weitgehend einig ist.","prueffrage":"Woran könnte jemand ohne Sachkenntnis in dieser Sendung erkennen, welche der beiden Positionen in der Fachwelt Rückhalt hat?","rueckmeldung":[{"option":1,"text":"Sich dem größeren Lager anzuschließen, kommt tatsächlich vor. Dafür müsste aber eine Mehrheit sichtbar sein; hier sitzen nur zwei Gäste mit exakt gleicher Redezeit, eine Mehrheit ist nicht zu erkennen."},{"option":2,"text":"Ein Ankereffekt kann Urteile prägen, setzt aber eine zuerst genannte Zahl voraus, an der sich alles misst. In der Sendung fällt gar keine Zahl, also gibt es nichts, woran sich die Zuschauer verankern könnten."},{"option":3,"text":"Eindrückliche Bilder bleiben tatsächlich leichter im Gedächtnis und können Gefahren größer erscheinen lassen. Von Bildern oder Beispielen ist in dieser Sendung aber keine Rede, und es geht um den Stand der Fachwelt, nicht um Dringlichkeit."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Cornell Chronicle (2021): More than 99.9% of studies agree: Humans caused climate change","oeffentlich":true,"url":"https://news.cornell.edu/stories/2021/10/more-999-studies-agree-humans-caused-climate-change","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lynas, M.; Houlton, B. Z.; Perry, S. (2021): Greater than 99% Consensus on Human Caused Climate Change in the Peer-Reviewed Scientific Literature. Environmental Research Letters 16(11), 114005","oeffentlich":true,"doi":"10.1088/1748-9326/ac2966"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"296b9329950ae993"}},{"id":"qx-b1-045","clusterId":"B","werkstueckRef":"B.13","stufe":1,"question":"Welche Rückfrage trifft den Kern des Fehlers in diesem Gespräch?","scenario":"Im Chat schreibt eine Kollegin: „Wie soll ein winziger Anteil eines unsichtbaren Gases wie CO2 das ganze Klima der Erde verändern? Das kann ich mir beim besten Willen nicht vorstellen, also ist die Sache Unsinn.“ Du willst ihr antworten.","options":["Beweist dein fehlendes Vorstellungsvermögen etwas über die Sache, oder zeigt es nur, wo dein Wissen gerade endet?","Stützt sich dein Schluss auf einen einzelnen Fall, oder gibt es mehrere vergleichbare Fälle, die dasselbe zeigen?","Verwechselst du zwei Dinge, die zusammen auftreten, mit einer Ursache, oder liegt wirklich ein Wirkzusammenhang vor?","Beruft sich deine Aussage auf eine Quelle, die veraltet sein könnte, oder gibt es neuere Daten dazu?"],"correctIndex":0,"explanation":"Die Kollegin schließt von „Ich kann mir nicht vorstellen, wie X wahr sein könnte“ auf „X ist nicht wahr“. Das ist ein Fehlschluss, denn die Grenzen der eigenen Vorstellungskraft sind kein Beleg gegen eine Behauptung. Unsere Intuition ist für Alltagsdinge in mittlerer Größe und bei mittlerer Geschwindigkeit geeignet. Bei Rückkopplungen im Klimasystem, in der Quantenphysik oder bei der Entwicklung des Auges versagt sie regelmäßig, und die Wirklichkeit hat keine Pflicht, unserem Bauchgefühl zu entsprechen. Auch die Verwandlung einer Raupe in einen Schmetterling, bei der in der Puppe große Teile des Körpers abgebaut und neu aufgebaut werden, klingt unvorstellbar und ist trotzdem real. Die richtige Rückfrage trennt deshalb sauber zwischen dem eigenen Unglauben und der Frage, was für oder gegen die Behauptung spricht. Die anderen Rückfragen sind in anderen Gesprächen berechtigt, treffen hier aber nicht: Die Kollegin stützt sich auf keinen Einzelfall, sondern auf ihr Vorstellungsvermögen. Sie behauptet auch keinen Zusammenhang zwischen zwei gleichzeitig auftretenden Dingen, sondern zweifelt an der Möglichkeit selbst. Und sie beruft sich auf keine Quelle, deren Aktualität man prüfen könnte.","coreRule":"⚡ Was ich mir nicht vorstellen kann, ist deshalb nicht unmöglich.","quote":"Ich kann es mir nicht vorstellen, also kann es nicht wahr sein.","quoteLabel":"Merksatz:","beleg":"Werkstück B.13 (Die unmögliche Raupe; Kernidee; Kontext & Tiefe; Anwendung & Relevanz)","status":"entwurf","kurz":"Dass sich die Kollegin etwas nicht vorstellen kann, sagt etwas über ihr Wissen, nicht über die Sache. Der Fehler ist der Schluss von „unvorstellbar“ auf „unwahr“, obwohl die Intuition bei Rückkopplungen im Klimasystem regelmäßig versagt.","prueffrage":"Welche Gründe nennt die Kollegin dafür, dass die Sache Unsinn ist?","rueckmeldung":[{"option":1,"text":"Die Frage nach Einzelfall und Verallgemeinerung ist in anderen Gesprächen sinnvoll. Die Kollegin stützt sich hier aber auf gar kein Beispiel, sondern auf ihr Vorstellungsvermögen. Für diesen Fehler gibt es also nichts zu verallgemeinern."},{"option":2,"text":"Zusammen auftretende Dinge mit einer Ursache zu verwechseln, ist ein häufiger Fehler, der hier aber nicht vorliegt. Die Kollegin behauptet keinen Zusammenhang zwischen zwei Beobachtungen, sondern hält die Wirkung selbst für unmöglich."},{"option":3,"text":"Auf veraltete Quellen zu achten, ist grundsätzlich klug. Hier fehlt dafür aber der Gegenstand: Die Kollegin beruft sich auf keine Quelle, deren Aktualität sich prüfen ließe, sondern auf das, was sie sich vorstellen kann."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"},{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI „Organs of extreme perfection“ (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"},{"typ":"url","kurz":"Jabr, F. (2012): How Does a Caterpillar Turn into a Butterfly? Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/caterpillar-butterfly-metamorphosis-explainer/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f04469cf776aed4d"}},{"id":"qx-b1-046","clusterId":"B","werkstueckRef":"B.13","stufe":2,"question":"Warum ist die Intuition in diesem Fall ein schlechter Maßstab, obwohl dasselbe Bauchgefühl bei dubiosen Verkaufsangeboten gut schützt?","scenario":"Ein Kollege sagt über ein neues Medikament: „Wie soll ein winziger Wirkstoff den ganzen Körper beeinflussen? Das kann ich mir nicht vorstellen, also wirkt es nicht.“ Die Zulassungsstudien liegen offen vor, er hat sie nicht gelesen. Zu gut klingende Angebote kennst du selbst als Fall, in dem dich ein Bauchgefühl zu Recht zum genaueren Hinsehen bringt.","options":["Weil sie hier als letztes Wort dient und verhindert, dass er die vorliegenden Belege überhaupt prüft.","Weil sie hier aus schlechten Einzelerfahrungen vorschnell auf alle Medikamente schließt und deshalb zu pauschal urteilt.","Weil sie hier von leicht abrufbaren Beispielen gespeist wird und die Risiken von Medikamenten verzerrt erscheinen lässt.","Weil sie hier auf einem Autoritätsargument beruht und der Meinung einer Person mehr traut als den vorliegenden Daten."],"correctIndex":0,"explanation":"Ein Bauchgefühl ist ein brauchbarer erster Filter: Es lässt uns bei Angeboten, die zu gut klingen, genauer hinsehen und schützt so vor vielen Betrügereien. Zum Problem wird es, wenn es zur unanfechtbaren Endinstanz wird. „Ich kann mir das nicht vorstellen“ sagt etwas über die Grenzen der eigenen Vorstellungskraft und des eigenen Wissens, nicht über die Wirklichkeit. Die Intuition ist für Alltagssituationen mit mittleren Größen und Geschwindigkeiten geeicht, bei komplexen wissenschaftlichen Themen weit außerhalb der Alltagserfahrung führt sie in die Irre. Wer seine Intuition hier über die vorliegenden Studien stellt, schaltet die Prüfung der Belege ab, die sie herausfordern könnten. Die Intuition ist nicht grundsätzlich unzuverlässig, sondern nur als finale Urteilsinstanz problematisch. Die anderen Erklärungen nennen bekannte Denkfehler, die hier aber nicht vorliegen: Der Kollege schließt nicht aus schlechten Erfahrungen auf alle Medikamente, von Erfahrungen ist gar nicht die Rede. Von auffälligen Berichten, die sein Urteil färben könnten, steht im Szenario ebenfalls nichts. Und er beruft sich auf keine Autorität, sondern allein auf das eigene Gefühl.","coreRule":"⚡ Die Intuition darf den Anfang der Prüfung machen, aber nicht das letzte Wort haben.","beleg":"Werkstück B.13 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"„Das kann ich mir nicht vorstellen“ sagt etwas über die Grenzen der eigenen Vorstellungskraft, nicht über das Medikament. Als Filter schützt das Bauchgefühl, als letztes Wort hält es davon ab, die vorliegenden Studien zu prüfen.","prueffrage":"Wie oft konnte der Kollege sein Gefühl über Arzneiwirkungen schon an echten Ergebnissen überprüfen, verglichen mit deinem Gefühl bei Verkaufsangeboten?","rueckmeldung":[{"option":1,"text":"Pauschal wirkt das Urteil tatsächlich, es betrifft aber nur dieses eine Mittel. Von schlechten Erfahrungen mit Medikamenten ist keine Rede: Der Zweifel kommt allein daraus, dass er sich den Mechanismus nicht vorstellen kann."},{"option":2,"text":"Verzerrte Risikowahrnehmung ist ein bekannter Fehler, im Szenario geht es aber gar nicht um Risiken oder auffällige Berichte. Der Kollege stützt sich auf seine Vorstellungskraft, nicht auf Beispiele, die ihm leicht einfallen."},{"option":3,"text":"Eine Autorität kommt im Szenario nicht vor: Der Kollege verlässt sich auf sein eigenes Gefühl, nicht auf die Meinung einer anderen Person. Das Problem liegt darin, dass er die offen vorliegenden Studien beiseiteschiebt."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"},{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"09c073221e101b16"}},{"id":"qx-b1-047","clusterId":"B","werkstueckRef":"B.13","stufe":4,"question":"Was ist an dieser Aussage als Argument gegen die Evolution des Auges ihr eigentliches Problem?","scenario":"Jemand sagt: „Ich kann mir einfach nicht vorstellen, wie sich aus zufälligen Mutationen und natürlicher Selektion etwas so Komplexes wie ein menschliches Auge entwickeln konnte. Das ist doch unmöglich!“","options":["Sie baut aus der Evolutionstheorie einen leicht angreifbaren Strohmann, obwohl die Theorie neben dem Zufall auch die natürliche Selektion als Mechanismus annimmt.","Sie macht die Grenze der eigenen Vorstellungskraft zum Maßstab für die Wirklichkeit, obwohl daraus nichts über die Entstehung des Auges folgt.","Sie greift die Forschenden persönlich an, statt ihre Befunde zu prüfen, obwohl ein Angriff auf Personen kein einziges ihrer Ergebnisse widerlegen kann.","Sie beruft sich auf die Meinung einer Autorität statt auf Belege, obwohl auch anerkannte Fachleute sich in Einzelfragen irren können."],"correctIndex":1,"explanation":"Der Satz „Ich kann mir nicht vorstellen, wie …“ beschreibt nur, was in einem Kopf möglich ist, nicht was in der Natur möglich ist. Aus fehlender Vorstellungskraft folgt nichts über die Wirklichkeit: Vieles, was sich als wahr herausgestellt hat, widerspricht der Alltagsintuition, etwa dass Uhren in schneller Bewegung langsamer gehen oder dass riesige Kontinente langsam über den Globus driften. Der Einwand ist also kein Argument, sondern ein Bekenntnis zur eigenen Wissenslücke, etwa über die kleinen Zwischenschritte, in denen komplexe Strukturen entstehen können. Hilfreich ist die Frage, ob der Mangel an Vorstellungskraft ein Beweis gegen die Behauptung oder nur ein Beweis für die Grenzen des eigenen Wissens ist. Die anderen Einwände beschreiben Fehler, die hier nicht vorkommen: Die Aussage nennt Zufall und Selektion beide, verzerrt die Theorie also nicht zu einem Strohmann. Sie greift niemanden persönlich an. Und sie beruft sich auf keine Autorität, sondern allein auf das eigene Vorstellungsvermögen.","coreRule":"⚡ Wenn du es dir nicht vorstellen kannst, such eine Erklärung oder Analogie, statt es abzulehnen.","beleg":"Werkstück B.13 (Kontext & Tiefe; Anwendung & Relevanz: Bei der Evolutionstheorie; Das Anti-Denkmuster)","status":"entwurf","kurz":"Fehlende Vorstellungskraft sagt etwas über den eigenen Kopf, nicht über die Natur. Wer „kann ich mir nicht vorstellen“ als „unmöglich“ liest, macht aus einer Wissenslücke, etwa über viele kleine Zwischenschritte, einen Einwand gegen die Sache selbst.","prueffrage":"Welche einfacheren Augen gibt es heute bei anderen Tieren, und was zeigen sie über mögliche Zwischenstufen?","rueckmeldung":[{"option":0,"text":"Ein Strohmann verzerrt die Gegenseite, und das wirkt hier plausibel, weil der Zufall so betont wird. Die Aussage nennt aber Mutation und Selektion beide, gibt die Theorie also korrekt wieder. Ihr Problem liegt im Schluss, nicht in der Darstellung."},{"option":2,"text":"Persönliche Angriffe sind ein bekannter Denkfehler, und ein solcher Angriff würde tatsächlich keinen Befund widerlegen. Hier kommen aber gar keine Forschenden vor: Die Aussage richtet sich gegen die Erklärung selbst, nicht gegen Personen."},{"option":3,"text":"Autoritätsargumente sind verführerisch, und auch Fachleute können sich in Einzelfragen irren. Die Aussage beruft sich aber auf keine Autorität, sondern ausschließlich auf das eigene Vorstellungsvermögen. Genau darin liegt ihr Problem."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI „Organs of extreme perfection“ (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"},{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b6b339d9023947a4"}},{"id":"qx-b1-048","clusterId":"B","werkstueckRef":"B.14","stufe":1,"question":"Welcher Denkfehler steckt in dem Satz „Das ist rein natürlich, die Natur weiß am besten, was gut für uns ist“?","scenario":"In der Drogerie rät dir jemand zu einem pflanzlichen Erkältungsmittel: „Das ist rein natürlich, ohne all die aggressive Chemie. Die Natur weiß am besten, was gut für uns ist.“","options":["Er schließt aus dem langen Gebrauch eines Mittels auf dessen Wirksamkeit (Appell an die Tradition).","Er schließt aus einer Besserung nach der Einnahme auf die Wirkung des Mittels (Post-hoc-Fehlschluss).","Er schließt aus der Beliebtheit eines Mittels bei vielen Menschen auf dessen Wirkung (Appell an die Menge).","Er schließt von der Herkunft eines Stoffs auf dessen Sicherheit und Wirkung (Appell an die Natur)."],"correctIndex":3,"explanation":"Der Satz setzt „natürlich“ mit „gut, sicher, überlegen“ gleich. Das ist ein Fehlschluss, denn die Herkunft eines Stoffs sagt nichts über Sicherheit oder Wirkung. Die Natur ist gleichgültig gegenüber unserem Wohlbefinden: Sie bringt Heilendes hervor, aber auch Tödliches wie Botulinumtoxin, Schlangengift oder Knollenblätterpilze. Ob ein Mittel hilft oder schadet, zeigen Reinheit, Dosierbarkeit und getestete Wirkung. Der Fehler liegt also nicht in einer angeblichen Schwäche natürlicher Stoffe, sondern darin, dass von der Herkunft auf Sicherheit und Wirkung geschlossen wird. Der Satz bewertet einen Stoff nach seiner Herkunft statt nach geprüfter Evidenz. Die anderen Fehlschlüsse gibt es ebenfalls, sie kommen in dem Satz aber nicht vor: Er beruft sich weder auf langen Gebrauch noch darauf, dass viele Menschen das Mittel nutzen, und er nennt auch keine Besserung nach der Einnahme.","coreRule":"⚡ „Natürlich“ ist ein Herkunftsetikett, kein Gütesiegel.","beleg":"Werkstück B.14 (Das Gespräch in der Drogerie; Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Der Satz bewertet das Mittel nach seiner Herkunft, nicht nach geprüfter Wirkung. „Natürlich“ sagt aber nichts über Sicherheit oder Nutzen: Die Natur bringt Heilendes hervor, aber auch Tödliches wie Knollenblätterpilze.","prueffrage":"Was steht auf der Packung über die Menge der Inhaltsstoffe und über Studien zur Wirkung?","rueckmeldung":[{"option":0,"text":"Pflanzliche Mittel haben oft eine lange Geschichte, das macht diese Deutung naheliegend. Im Satz kommt aber weder langer Gebrauch noch Überlieferung vor; er stützt sich nur darauf, dass der Stoff natürlich ist."},{"option":1,"text":"Dass ein Mittel nach der Einnahme zu helfen scheint, ist ein klassischer Anlass für Fehlschlüsse. Hier hat aber noch niemand etwas eingenommen, und es wird keine Besserung berichtet. Es geht nur um die Herkunft des Mittels."},{"option":2,"text":"Ein Mittel, das viele nutzen, wirkt schnell vertrauenswürdig. Der Satz nennt aber weder Nutzerzahlen noch Beliebtheit. Er wirbt allein mit „natürlich“ und „ohne Chemie“, und das ist ein Herkunftsargument."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO: Botulism. Fact sheet","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/botulism","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"70bd1b8e032228d2"}},{"id":"qx-b1-049","clusterId":"B","werkstueckRef":"B.14","stufe":2,"question":"Was spricht an dieser Argumentation am ehesten gegen den Schluss, der Rindenextrakt sei dem Laborprodukt überlegen?","options":["Die Rinde enthält viele weitere Substanzen, und ihr Wirkstoffgehalt schwankt je nach Baum und Jahreszeit. Die Herkunft sagt also nichts über Reinheit und Dosis aus.","Dass Weidenrinde seit Jahrhunderten genutzt wird, belegt noch keine Wirksamkeit. Auch ein langer Gebrauch ist deshalb kein Beleg für die Qualität eines Mittels.","Hersteller von Extrakten verdienen am Verkauf, und Verkaufsinteressen können Wirkversprechen färben. Aussagen zur Wirkung sind darum immer mit Vorsicht zu lesen.","Auch bei Kopfschmerzen helfen viele Mittel zum Teil durch den Placeboeffekt. Eine gefühlte Besserung beweist deshalb noch nicht, dass der Stoff selbst wirkt."],"correctIndex":0,"explanation":"Die Freundin schließt von der Herkunft auf die Qualität. Das ist ein Fehlschluss, denn entscheidend sind Reinheit, Dosierbarkeit und geprüfte Wirkung. Weidenrinde enthält neben dem Vorläuferstoff Salicin hunderte andere Substanzen, von denen manche die Wirkung abschwächen oder Nebenwirkungen haben können. Außerdem schwankt der Wirkstoffgehalt je nach Baum, Jahreszeit und Standort, sodass sich kaum genau dosieren lässt. Eine Aspirin-Tablette enthält dagegen eine festgelegte Menge reiner Acetylsalicylsäure, deren Vorläufer in der Weidenrinde vorkommt. Das macht Synthetisches nicht automatisch besser, es zeigt nur, dass „natürlich“ kein Qualitätsmerkmal ist. Die anderen Gedanken sind für sich zutreffend, gehen aber am Argument vorbei: Auf langen Gebrauch beruft sich die Freundin gar nicht, sie schließt von der Herkunft. Von Verkaufsinteressen ist im Szenario keine Rede. Und von einer gefühlten Besserung, die der Placeboeffekt erklären könnte, ebenso wenig.","coreRule":"⚡ Die Herkunft eines Stoffes sagt nichts über seine Qualität. Reinheit, Dosis und getestete Wirkung entscheiden.","beleg":"Werkstück B.14 (Kontext & Tiefe: Der entscheidende Vorteil des „Künstlichen“)","status":"entwurf","scenario":"Eine Freundin hat Kopfschmerzen und will keine Tabletten nehmen. Sie sagt: „Ich nehme lieber Weidenrinden-Extrakt statt Aspirin. Der Wirkstoff kommt ja ursprünglich aus der Rinde, also ist das Original natürlich besser als die Kopie aus dem Labor.“","kurz":"„Aus der Natur“ sagt nichts über Qualität: Rinde enthält viele weitere Stoffe, und der Wirkstoffgehalt schwankt je nach Baum und Jahreszeit. Der Fehler liegt darin, von der Herkunft auf Reinheit und Dosis zu schließen.","prueffrage":"In welcher Beziehung steht der Wirkstoff der Weidenrinde zu dem der Aspirin-Tablette?","rueckmeldung":[{"option":1,"text":"Dass langer Gebrauch keine Wirksamkeit belegt, stimmt. Die Freundin beruft sich aber gar nicht auf Tradition, sondern auf die Herkunft („Original“, „natürlich“). Dieser Gedanke trifft also ihr Argument nicht."},{"option":2,"text":"Verkaufsinteressen können Wirkversprechen tatsächlich färben. Im Szenario kommt aber kein Hersteller und keine Werbung vor, die Freundin begründet ihre Wahl allein mit der Herkunft. Der Einwand geht am Argument vorbei."},{"option":3,"text":"Der Placeboeffekt kann eine gefühlte Besserung erklären, das ist richtig. Die Freundin berichtet aber keine Besserung, sie begründet vorab, warum sie den Extrakt wählt. Der Einwand passt daher nicht zu ihrem Argument."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Vlachojannis, J.; Magora, F.; Chrubasik, S. (2011): Willow species and aspirin: different mechanism of actions. Phytotherapy Research 25(7), 1102–1104 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/21226125/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vlachojannis u. a. (2011), Verlagsfassung","oeffentlich":false,"doi":"10.1002/ptr.3386"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f3ca4714d4315885"}},{"id":"qx-b1-050","clusterId":"B","werkstueckRef":"B.14","stufe":3,"question":"Eine Bekannte erzählt dir, sie esse am liebsten unverarbeitete Lebensmittel, gehe oft in den Wald und setze bei leichten Erkältungen auf Kräutertee. Ihr Bruder lehnt dagegen die vom Arzt empfohlene Behandlung seiner Erkrankung ab und nimmt stattdessen nur noch „rein natürliche“ Präparate, weil „die Natur am besten weiß, was gut für uns ist“. Woran erkennst du, dass beim Bruder der Appell an die Natur zum gefährlichen Fehlschluss wird?","options":["Er ersetzt eine geprüft wirksame und sichere Behandlung durch Alternativen, deren Wirkung und Dosierung ungeprüft sind, und riskiert dadurch schwere Folgen.","Er stützt sich auf das Wort „rein“, das als Werbebegriff keine geprüfte Qualität garantiert, und lässt sich dadurch zu einer Fehlentscheidung verleiten.","Er verlässt sich bei der Behandlung auf Einzelberichte anderer Anwender statt auf Studien, und solche Berichte sind als Beleg für eine Wirkung unzuverlässig.","Er informiert sich ausschließlich unter Gleichgesinnten, und eine einseitige Informationslage verstärkt jede Meinung zusätzlich (Echokammer-Effekt)."],"correctIndex":0,"explanation":"Eine Vorliebe für Natürliches ist für sich genommen harmlos und oft sogar gesund: Wer unverarbeitete Lebensmittel mag, im Wald spazieren geht oder bei einer leichten Erkältung Kräutertee trinkt, trifft keine riskante Entscheidung. Der Fehlschluss wird erst gefährlich, wenn er zu einer Entscheidung mit Folgen wird. Das ist der Fall, wenn eine nachweislich wirksame und sichere Behandlung durch Mittel ersetzt wird, deren Wirkung nie geprüft wurde und deren Dosis schwankt. Dann entscheidet die Herkunft über die Behandlung statt die belegte Wirkung. Ein Beispiel: Wer eine Chemotherapie zugunsten von Aprikosenkernen ablehnt, setzt sich einem Gift aus (sie enthalten Amygdalin, aus dem im Körper giftige Blausäure entstehen kann), statt die Krankheit zu behandeln. Die Herkunft sagt weder etwas über Sicherheit noch über Wirksamkeit. Die richtige Frage lautet immer: Was zeigen die besten Belege über Sicherheit, Reinheit, Dosierbarkeit und Wirksamkeit genau dieses Mittels? Die anderen Hinweise treffen den Kern nicht: Dass „rein“ ein Werbewort ist, stimmt, die Gefahr entsteht aber erst durch das Absetzen der Behandlung. Von Einzelberichten, auf die er sich stützt, steht im Fall nichts. Und dass er sich nur unter Gleichgesinnten informiert, wird ebenfalls nirgends erwähnt.","coreRule":"⚡ Natürliche Vorlieben sind harmlos – gefährlich wird erst der Ersatz geprüfter Lösungen durch ungeprüfte.","beleg":"Werkstück B.14 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Gefährlich wird der Appell an die Natur erst, wenn er eine wirksame, sichere Behandlung verdrängt. Die Herkunft eines Mittels sagt weder etwas über Sicherheit noch über Wirkung; die Vorliebe der Schwester für Natürliches bleibt dagegen harmlos.","prueffrage":"Bei welchen Beschwerden setzt die Bekannte auf Natürliches, und bei welchen ihr Bruder?","rueckmeldung":[{"option":1,"text":"Dass „rein“ ein Werbewort ist, stimmt, und es kann Vertrauen wecken, das nicht gedeckt ist. Doch auch ohne dieses Wort wäre der Schritt riskant, denn die Gefahr entsteht erst dadurch, dass er die geprüfte Behandlung absetzt."},{"option":2,"text":"Einzelberichte sind als Wirkbeleg tatsächlich schwach. Im Fall steht aber nichts davon, dass er sich darauf stützt; seine Begründung ist der Grundsatz, die Natur wisse es am besten, und gefährlich wird erst das Absetzen der Behandlung."},{"option":3,"text":"Eine einseitige Informationslage kann Meinungen tatsächlich verstärken. Über sein Umfeld und seine Quellen sagt der Fall aber nichts. Das Erkennungszeichen liegt in seiner Entscheidung: Er ersetzt eine belegt wirksame Behandlung durch ungeprüfte Mittel."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Milazzo, S.; Horneber, M. (2015): Laetrile treatment for cancer. Cochrane Database of Systematic Reviews, CD005476 (Volltext frei in PMC6513327)","oeffentlich":true,"doi":"10.1002/14651858.CD005476.pub4","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c370f5e17f377bf2"}},{"id":"qx-b1-051","clusterId":"B","werkstueckRef":"B.14","stufe":4,"question":"Wie ist diese Behauptung am treffendsten zu beurteilen?","scenario":"Ein Verkäufer behauptet: „Dieser Stoff aus der Pflanze ist dem im Labor hergestellten überlegen, obwohl beide chemisch exakt identisch sind. Denn der natürliche trägt eine Lebenskraft in sich.“","options":["Sie ist ein Bestätigungsfehler, weil der Verkäufer nur Belege für die Überlegenheit natürlicher Stoffe sammelt und alle anderen Befunde übergeht.","Sie ist ein Autoritätsargument, weil der Verkäufer sich auf seine Stellung als Fachmann beruft, statt Belege für seine Aussage zu nennen.","Sie ist ein Strohmann, weil der Verkäufer der Gegenseite eine Position unterstellt, die sie gar nicht vertritt, und diese dann widerlegt.","Sie ist eine unbelegte Zusatzannahme, weil bei identischen Molekülen kein Unterschied gezeigt wird und Wirkung und Sicherheit durch Tests geprüft werden müssen."],"correctIndex":3,"explanation":"Die Behauptung gibt zu, dass beide Stoffe chemisch identisch sind, und setzt dann einen Vorteil des „natürlichen“ obendrauf, die „Lebenskraft“. Diese behauptete Überlegenheit ist unbewiesen, und sie lässt sich auch nicht an den Molekülen festmachen, die ja gleich sind. Die Herkunft sagt weder etwas über Wirksamkeit noch über Sicherheit: Der Knollenblätterpilz ist ebenso natürlich wie Arsen. Was zählt, sind Reinheit, Dosierbarkeit, Wirksamkeit und Sicherheit, und die muss man durch Tests belegen. Die anderen Einordnungen nennen bekannte Fehler, die hier aber nicht vorliegen: Der Verkäufer sammelt nicht einseitig Belege, er nennt gar keine. Er beruft sich nicht auf eine Fachautorität, sondern auf eine „Lebenskraft“. Und er unterstellt der Gegenseite keine Position, sondern behauptet den Vorteil selbst.","coreRule":"⚡ Bei identischen Molekülen bleibt „Lebenskraft“ eine Behauptung, kein Befund.","beleg":"Werkstück B.14 (Anwendung & Relevanz: In der Pseudomedizin & Wellness-Industrie; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wenn beide Stoffe chemisch identisch sind, gibt es keinen Unterschied, den eine „Lebenskraft“ erklären könnte. Der Fehler ist, „natürlich“ mit „besser“ gleichzusetzen: Herkunft sagt nichts über Wirkung und Sicherheit, die müssen Tests zeigen.","prueffrage":"Welcher messbare Unterschied zwischen den beiden Stoffen wird in der Aussage tatsächlich genannt?","rueckmeldung":[{"option":0,"text":"Bestätigungsfehler klingt passend, weil der Verkäufer eine Vorliebe für das Natürliche zeigt. Dafür müsste er aber Belege einseitig auswählen, und hier nennt er gar keine. Er behauptet den Vorteil nur."},{"option":1,"text":"Dass hier etwas ohne Belege behauptet wird, stimmt. Der Verkäufer beruft sich aber auf keine Fachautorität, sondern auf eine „Lebenskraft“. Ein Autoritätsargument liegt deshalb nicht vor."},{"option":2,"text":"Ein Strohmann bräuchte eine verzerrte Darstellung der Gegenseite, die dann widerlegt wird. Im Text gibt es keine Gegenseite und keine unterstellte Position, der Verkäufer stellt nur seine eigene Behauptung auf."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO: Botulism. Fact sheet","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/botulism","abruf":"2026-10-12"},{"typ":"url","kurz":"Vlachojannis, J.; Magora, F.; Chrubasik, S. (2011): Willow species and aspirin: different mechanism of actions. Phytotherapy Research 25(7), 1102–1104 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/21226125/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"fb0c59eb96847c80"}},{"id":"qx-b1-052","clusterId":"B","werkstueckRef":"B.15","stufe":1,"question":"Was ist an diesem Schluss fehlerhaft, und welche Information würde ihn am ehesten prüfen?","scenario":"In einem Ratgeber-Artikel steht: „Zwei bekannte Tech-Gründer haben ihr Studium abgebrochen und sind Milliardäre geworden. Also ist ein Studienabbruch ein guter Weg zum Erfolg.“","options":["Der Schluss stützt sich nur auf die Erfolgreichen; entscheidend wäre, wie es allen ergangen ist, die ihr Studium abgebrochen haben.","Der Schluss beruft sich auf die Autorität der Gründer; entscheidend wäre, ob diese beiden Gründer Fachleute für Bildung und Ausbildung sind.","Der Schluss stammt aus einem Ratgeber mit eigenem Interesse; entscheidend wäre, wer den Artikel bezahlt oder bestellt hat.","Der Schluss beruht auf Durchschnittswerten, die Ausreißer verdecken; entscheidend wäre die Streuung der Einkommen aller Gründer."],"correctIndex":0,"explanation":"Hier werden nur diejenigen betrachtet, die einen Auswahlprozess erfolgreich durchlaufen haben. Die vielen Menschen, die ebenfalls abgebrochen haben und gescheitert sind, tauchen in keiner Erfolgsgeschichte auf, wären für den Schluss aber entscheidend. Erst der Vergleich zeigt, ob Abbrechen die Erfolgschance erhöht oder ob Glück, Timing und andere Faktoren die Hauptrolle spielen. Ähnlich ist es bei Gewohnheiten wie „früh aufstehen“: Auch viele Gescheiterte können sie gehabt haben. Die anderen Gedanken sind für sich sinnvoll, treffen aber nicht den Fehler: Die Gründer dienen als Beispiele, nicht als Autoritäten, deren Fachwissen zählen würde. Wer den Artikel bestellt hat, sagt nichts darüber, ob der Schluss trägt. Und der Schluss rechnet gar nicht mit Durchschnittswerten, sondern mit zwei Einzelfällen.","coreRule":"⚡ Wenn nur Gewinner gezeigt werden, frag nach denen, die dasselbe getan haben und trotzdem gescheitert sind.","beleg":"Werkstück B.15 (Kernidee; Anwendung & Relevanz: In der Business- & Self-Help-Industrie)","status":"entwurf","kurz":"Der Schluss betrachtet nur die Abbrecher, die es geschafft haben. Ob Abbrechen die Erfolgschance erhöht, zeigt erst der Blick auf alle, die abgebrochen haben, auch auf die vielen, von denen niemand erzählt.","prueffrage":"Woher kennt der Artikel gerade diese zwei Gründer, und warum wird über sie überhaupt geschrieben?","rueckmeldung":[{"option":1,"text":"Nach dem Fachwissen der Gründer zu fragen, ist grundsätzlich vernünftig. Hier dienen die beiden aber nur als Beispiele, nicht als Experten, auf deren Urteil sich der Schluss stützt. Der Fehler liegt in der Auswahl der Fälle."},{"option":2,"text":"Fragen nach Interessen und Auftraggebern sind oft berechtigt. Wer den Artikel bestellt hat, sagt aber nichts darüber, ob der Schluss selbst trägt, denn auch ein unabhängiger Text könnte so argumentieren."},{"option":3,"text":"Bei Mittelwerten lohnt der Blick auf die Streuung. Hier gibt es aber gar keinen Durchschnitt, sondern genau zwei Einzelfälle, aus denen eine allgemeine Empfehlung folgen soll."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"450c2bb0bd4743ae"}},{"id":"qx-b1-053","clusterId":"B","werkstueckRef":"B.15","stufe":2,"question":"Welche Frage prüft die Schlussfolgerung des Lesers am besten?","scenario":"In einer Zeitung wird ein Medium gefeiert, weil es ein Ereignis angeblich korrekt vorhergesagt hat. Berichtet wird nur über diese eine Vorhersage. Ein Leser schreibt: „Das kann kein Zufall sein, das Medium hat offenbar echte Fähigkeiten.“","options":["Verdient das Medium Geld mit solchen Vorhersagen und hat deshalb ein Interesse an der Berichterstattung darüber?","Wie viele andere Vorhersagen dieses und anderer Medien lagen daneben und wurden nie erwähnt?","Hat das Medium eine anerkannte Ausbildung oder Prüfung, die seine behaupteten Fähigkeiten bescheinigt?","Wurde die Vorhersage von mehreren unabhängigen Zeugen bestätigt, bevor das Ereignis eintrat?"],"correctIndex":1,"explanation":"Bei diesem Medium hörst Du nichts von den tausenden Vorhersagen desselben Mediums (und aller anderen), die komplett danebenlagen. Die Treffer überleben in der öffentlichen Erinnerung, die Fehlschüsse verschwinden. Der eine berichtete Treffer ist also eine nach Erfolg gefilterte Auswahl. Ob er etwas über echte Fähigkeiten aussagt, lässt sich erst beurteilen, wenn Du auch die verfehlten Vorhersagen kennst. Die anderen Fragen sind in anderen Lagen berechtigt, klären hier aber nicht, ob der Treffer nur ein Produkt der Auswahl ist: Ob das Medium mit solchen Meldungen Geld verdient, sagt nichts über Treffer und Fehlschüsse. Eine Ausbildung oder Prüfung ist kein Beleg dafür, dass Vorhersagen gelingen. Und selbst unabhängig bestätigte Zeitpunkte ändern nichts daran, dass nur die Treffer erzählt werden.","coreRule":"⚡ Zeig mir nicht nur die Treffer, sondern alle Versuche.","quote":"Aber wo ist der Friedhof? Welche unsichtbaren Daten der Gescheiterten fehlen in diesem Bild?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.15 (Anwendung & Relevanz: In der Esoterik; Das Anti-Denkmuster)","status":"entwurf","kurz":"Berichtet wird nur der Treffer, die verfehlten Vorhersagen bleiben unsichtbar. Der Leser schließt aus einer nach Erfolg gefilterten Auswahl auf echte Fähigkeiten, doch beurteilen lässt sich das erst, wenn man auch die Fehlschüsse kennt.","prueffrage":"Warum berichtet die Zeitung gerade über diese Vorhersage, und worüber hätte sie geschrieben, wenn sie nicht eingetroffen wäre?","rueckmeldung":[{"option":0,"text":"Ein finanzielles Interesse kann Berichte färben, und danach zu fragen ist in anderen Lagen sinnvoll. Hier sagt es aber nichts darüber, wie viele Vorhersagen danebenlagen, und genau das entscheidet über den Treffer."},{"option":2,"text":"Eine Ausbildung oder Prüfung klingt nach Qualifikation. Sie ist aber kein Beleg dafür, dass Vorhersagen tatsächlich gelingen, und sie sagt nichts darüber, welche Vorhersagen überhaupt berichtet werden."},{"option":3,"text":"Zeugen vor dem Ereignis würden klären, ob diese eine Vorhersage wirklich vorher gemacht wurde. Das ist in anderen Lagen wichtig. Hier bliebe trotzdem offen, wie viele Vorhersagen danebenlagen und nie erzählt werden."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Selective Attention“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1fba7f2d747a7d0b"}},{"id":"qx-b1-054","clusterId":"B","werkstueckRef":"B.15","stufe":3,"question":"Du liest in einem Wirtschaftsmagazin, wie ein Mathematiker im Zweiten Weltkrieg den Generälen mit einem einzigen Satz widerspricht: „Meine Herren, Sie liegen komplett falsch.“ Wie gehst du mit der Szene um?","options":["Ich halte den Kerngedanken für prüfbar, die wörtliche Szene aber für ungesichert, weil anschauliche Details ohne Quelle leicht dazugedichtet sind.","Ich prüfe, ob es den genannten Mathematiker wirklich gab, und halte die Szene dann für bestätigt, weil sie von einer belegten Person handelt.","Ich halte die ganze Geschichte samt Kerngedanken für widerlegt, weil die Szene dramatisiert ist und der Artikel deshalb unseriös arbeitet.","Ich übernehme die Szene vorerst, weil der Kerngedanke stimmt und eine Geschichte, die ihn so treffend zeigt, wohl auch im Detail stimmt."],"correctIndex":0,"explanation":"Anschauliche Details wie wörtliche Dialoge sind kein Beleg, sondern oft das Ergebnis dramatisierenden Nacherzählens. Real ist Walds Arbeit für die Statistical Research Group der Columbia University, für die er 1943 Memoranden verfasste, die aus den Treffern zurückgekehrter Flugzeuge die Verwundbarkeit einzelner Flugzeugteile schätzen. Eine ausdrückliche Empfehlung, wo gepanzert werden soll, enthalten sie nicht, und der Dialog selbst ist nicht dokumentiert. Auch die Rahmung vom einsamen Außenseiter greift zu kurz, denn das US-Militär wertete Kampfschäden bereits systematisch aus. Die vernünftige Haltung trennt also zwischen dem prüfbaren Kern (der Idee der Auswahlverzerrung: Die Daten der Zurückgekehrten verzerren das Bild) und der ungesicherten Ausschmückung. Dass es die Person und ihre Arbeit gab, bestätigt nur ihre Existenz, nicht den überlieferten Wortlaut. Dass eine Szene dramatisiert ist, macht den Kerngedanken nicht falsch. Und dass der Kern stimmt, überträgt sich nicht auf jedes erzählte Detail.","coreRule":"⚡ Eine gute Lehrgeschichte ist noch keine Quelle – prüfe, was davon belegt ist.","beleg":"Werkstück B.15 (Die unsichtbaren Einschusslöcher); Fn. gl-b-wald (Mangel/Samaniego 1984, JASA 79(386), S. 259–267)","status":"entwurf","scenario":"Der Artikel erzählt eine mitreißende Geschichte über Abraham Wald und die Panzerung von Bombern. Wörtliche Dialoge, genaue Trefferverteilungen und ein einsamer Held, der die ahnungslosen Militärs belehrt, machen die Erzählung sehr anschaulich. Eine Quelle für diese Details nennt der Artikel nicht.","kurz":"Der Kerngedanke, dass die Daten der Zurückgekehrten das Bild verzerren, lässt sich prüfen. Der wörtliche Dialog ist nicht dokumentiert, und anschauliche Details ohne Quelle sind oft dazugedichtet. Ein stimmiger Kern macht die Szene nicht wahr.","prueffrage":"Woher könnte ein Magazin heute den genauen Wortlaut eines Satzes kennen, der vor über 80 Jahren in einer Besprechung gefallen sein soll?","rueckmeldung":[{"option":1,"text":"Dass es Wald gab und er an dem Thema arbeitete, ist belegt. Das bestätigt aber nur die Person und ihre Arbeit, nicht den überlieferten Wortlaut: Auch eine echte Person kann in einer erfundenen Szene auftreten."},{"option":2,"text":"Dass die Szene dramatisiert ist und keine Quelle genannt wird, ist ein berechtigter Anlass für Skepsis. Daraus folgt aber nicht, dass der Kerngedanke falsch ist: Er bleibt unabhängig von der Ausschmückung prüfbar."},{"option":3,"text":"Dass der Kerngedanke stimmt, sagt nichts über jedes erzählte Detail. Gerade eine Geschichte, die den Gedanken so treffend zeigt, ist oft zugespitzt, und der einsame Held ist selbst schon eine Verkürzung."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"98149e39cf9c2a57"}},{"id":"qx-b1-055","clusterId":"B","werkstueckRef":"B.15","stufe":4,"question":"Welche Frage prüft die Behauptung des Architekten am besten?","scenario":"Ein Architekt behauptet: „Früher hat man besser gebaut. Sieh dir die alten Häuser an, die noch heute stehen!“","options":["Wie viele der damals gebauten Häuser sind inzwischen abgerissen oder eingestürzt?","Wie komfortabel sind die alten Häuser nach heutigen Maßstäben bei Dämmung und Heizung?","Wie stark hat sich die durchschnittliche Wohnfläche pro Person seit damals verändert?","Wie unterscheiden sich die Baustile der damaligen Häuser von denen der heutigen?"],"correctIndex":0,"explanation":"Die Behauptung stützt sich nur auf Gebäude, die einen langen Auswahlprozess überstanden haben: Was baufällig war, wurde abgerissen, umgebaut oder ist eingestürzt. Dass die übrig gebliebenen Häuser solide sind, folgt daraus fast zwangsläufig und sagt wenig über die Bauweise einer ganzen Epoche. Erst der Blick auf die verschwundenen Häuser zeigt, ob früher tatsächlich besser gebaut wurde. Die anderen Fragen sind in anderen Zusammenhängen sinnvoll, passen hier aber nicht: Der Komfort nach heutigen Maßstäben sagt nichts darüber, wie haltbar die Häuser waren. Die Wohnfläche pro Person betrifft ein anderes Merkmal als die Haltbarkeit, um die es in der Behauptung geht. Und Unterschiede der Baustile erklären nicht, welche Häuser den Auswahlprozess nicht überstanden haben.","coreRule":"⚡ Was heute noch steht, ist eine Auswahl – nicht die Gesamtheit dessen, was einmal gebaut wurde.","beleg":"Werkstück B.15 (Red Flags; Anwendung & Relevanz)","status":"entwurf","kurz":"Die Behauptung beruht nur auf Häusern, die lange genug überdauert haben; baufällige verschwanden längst. Dass die übrigen solide wirken, folgt fast zwangsläufig und sagt wenig über die Bauweise der ganzen Zeit.","prueffrage":"Wer hat im Lauf der Zeit entschieden, welche Häuser stehen bleiben, und nach welchen Gesichtspunkten?","rueckmeldung":[{"option":1,"text":"Komfort wirkt wie ein naheliegender Maßstab beim Vergleich von alt und neu. Die Behauptung handelt aber von Solidität und Haltbarkeit; Dämmung und Heizung sagen darüber nichts, und die verschwundenen Häuser bleiben unberücksichtigt."},{"option":2,"text":"Der Vergleich zeigt, wie sich das Wohnen verändert hat, etwa beim Platz pro Person. Die Behauptung betrifft aber die Haltbarkeit der Bauten, ein ganz anderes Merkmal, das die Wohnfläche nicht berührt."},{"option":3,"text":"Unterschiedliche Baustile können durchaus Hinweise auf Bauweisen geben. Sie erklären aber nicht, welche Häuser abgerissen wurden oder einstürzten, und genau dieser Blick auf die Verschwundenen fehlt hier."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6a6b7abe8ea4c864"}},{"id":"qx-b1-056","clusterId":"B","werkstueckRef":"B.16","stufe":1,"question":"Was passiert sprachlich, wenn Menschen im Netz als „Bots“ oder „NPCs“ abgetan werden, und was ist daran problematisch?","options":["Die Menschen werden mit ekelerregenden Tieren verglichen und damit auf Instinkte reduziert, sodass Ausgrenzung leichter fällt.","Die Menschen werden als gefühllose Automaten ohne eigenes Denken dargestellt, sodass ihre Gründe nicht mehr geprüft werden müssen.","Die Menschen werden als Vertreter einer verhassten Ideologie angesehen, sodass sie nur noch als Teil einer Gruppe gelten.","Die Menschen werden als besonders gefährlich und mächtig dargestellt, sodass Misstrauen gegen sie gerechtfertigt erscheint."],"correctIndex":1,"explanation":"Wer Menschen als „NPCs“ oder „Bots“ bezeichnet, stellt sie als kalte, gefühllose Automaten dar und beraubt sie damit ihrer Wärme, Individualität und Empathie. Das ist die mechanistische Form der Entmenschlichung: Sie werden wie seelenlose Instrumente behandelt, die nur Skripte abspielen. Die Folge: Wer ein Gegenüber so einordnet, hat keinen Anlass mehr, dessen Gründe ernst zu nehmen, denn bei einem Automaten gibt es keine eigenen Gründe. Ein Tiervergleich wäre dagegen die animalische Form, die Menschen auf primitive, instinktgetriebene Kreaturen reduziert und Ekel, Angst oder Verachtung hervorruft. Die Gruppenabwertung durch Etiketten macht Menschen zu bloßen Repräsentanten einer verhassten Ideologie, nimmt ihnen aber nicht die Eigenschaft, denkende Wesen zu sein. Der Gefährlichkeitsvorwurf setzt sogar voraus, dass sie handlungsfähig sind. Entscheidend ist also, ob dem Gegenüber das eigene Denken und Fühlen abgesprochen wird oder ob nur seine Position kritisiert wird. Die Kritik an einer Position ist legitim, die Aberkennung des Menschseins ist es nicht.","coreRule":"⚡ Wer anderen das eigene Denken und Fühlen abspricht, muss ihre Gründe nicht mehr prüfen.","beleg":"Werkstück B.16 (Kontext & Tiefe: Zwei Mechanismen; Anwendung & Relevanz: In der politischen Propaganda)","status":"entwurf","scenario":"In einem Kommentarbereich schreibt jemand unter eine Diskussion: „Mit denen brauchst du gar nicht zu reden. Das sind doch alles NPCs, die immer dieselben Sätze runterbeten.“ Die Angesprochenen sind echte Menschen mit eigenen Gründen für ihre Meinung.","kurz":"Wer Menschen „NPCs“ nennt, stellt sie als Automaten dar, die nur Skripte abspielen. Dann gibt es scheinbar keine eigenen Gründe mehr, die man prüfen müsste. Der Fehler: Statt die Position zu kritisieren, wird dem Gegenüber das Denken abgesprochen.","prueffrage":"Worauf bezieht sich die Aussage: auf das, was die Leute vorbringen, oder auf die Leute selbst?","rueckmeldung":[{"option":0,"text":"Entmenschlichung erleichtert Ausgrenzung tatsächlich, und Tiervergleiche sind eine bekannte Form davon. Hier fällt aber kein Tiervergleich: Die Menschen gelten als seelenlose Skriptabspieler, nicht als instinktgetriebene Kreaturen."},{"option":2,"text":"Gruppenetiketten reduzieren Menschen oft auf Vertreter einer Ideologie. Im Satz wird aber keine Ideologie genannt, und die Leute gelten nicht als Überzeugte, sondern als gar nicht denkend. Genau darin liegt der Unterschied."},{"option":3,"text":"Misstrauen lässt sich leicht mit einer Bedrohung begründen. Der Satz stellt die Menschen aber gerade nicht als handlungsfähig dar, sondern als Leute, „die immer dieselben Sätze runterbeten“. Gefährlichkeit würde ihnen eigenes Handeln zugestehen."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Haslam, N. (2006): Dehumanization: An Integrative Review. Personality and Social Psychology Review 10(3), 252–264 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/16859440/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam (2006), Verlagsfassung","oeffentlich":false,"doi":"10.1207/s15327957pspr1003_4"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a3216a16ae3c69d8"}},{"id":"qx-b1-057","clusterId":"B","werkstueckRef":"B.16","stufe":2,"question":"Ein Kommentator behauptet: „Der Völkermord in Ruanda 1994 ist allein den Hetzsendungen eines Radiosenders zuzuschreiben. Ohne dieses Radio wäre nichts passiert.“ Wie beurteilst du diese Behauptung am besten?","options":["Die Behauptung überschätzt das Radio: Hetzsprache kann Hemmungen senken und das Töten erleichtern, aber andere Faktoren wirkten daneben mit.","Die Behauptung verallgemeinert vorschnell: Aus einem einzigen Ereignis lässt sich nicht auf die Wirkung von Hetzsprache schließen.","Die Behauptung ist ein Zirkelschluss: Sie setzt die Wirkung der Hetze voraus und nimmt die Gewalt dann als Beleg für diese Wirkung.","Die Behauptung ist ein Autoritätsargument: Sie gilt als belegt, nur weil ein Kommentator sie öffentlich und mit Nachdruck so ausspricht."],"correctIndex":0,"explanation":"Die Behauptung macht aus einem Faktor die einzige Ursache. Wer Nachbarn monatelang als „Ungeziefer“ bezeichnet, löst moralische Hemmungen und macht das Töten sprachlich leichter. Zugleich gab es weitere Treiber: die Angst vor dem Krieg, Hetzblätter und die Mobilisierung durch Behörden und Bürgermeister. Ein Ereignis mit mehreren zusammenwirkenden Ursachen auf eine einzige zu verkürzen, ist ein typischer Denkfehler. Auch das Gegenteil, Sprache habe gar keine Wirkung, wäre falsch, denn Ursachen können sich verstärken. Die anderen Einwände nennen bekannte Denkfehler, die hier aber nicht vorliegen: Die Behauptung gilt einem einzelnen Ereignis und verallgemeinert nicht auf andere Fälle. Sie dreht sich auch nicht im Kreis; ihr Problem ist nicht, dass sie ihre Voraussetzung als Beleg nimmt, sondern dass sie die Wirkung eines Faktors zur einzigen Ursache steigert. Und sie beruft sich auf keine Autorität, sondern ist eine ungeprüfte Behauptung, die an ihrem Inhalt zu messen ist.","coreRule":"⚡ Sprache kann Hemmungen lösen, erklärt aber nie allein die Tat.","beleg":"Werkstück B.16 (Die Kakerlaken im Radio); Fn. gl-b-rtlm (Human Rights Watch 1999, „Leave None to Tell the Story“)","status":"entwurf","scenario":"Der Sender sprach über die Tutsi nicht als Nachbarn, sondern über Monate hinweg als „Kakerlaken“ und „Ungeziefer“. Zur gleichen Zeit herrschten Angst vor dem Krieg, es kursierten Hetzblätter, und Behörden und Bürgermeister mobilisierten die Bevölkerung.","quote":"","quoteLabel":"","kurz":"Hetzsprache kann Hemmungen senken und das Töten erleichtern, doch das Szenario nennt weitere Treiber: Kriegsangst, Hetzblätter und die Mobilisierung durch Behörden. Der Fehler liegt darin, aus einem von mehreren zusammenwirkenden Faktoren die einzige Ursache zu machen.","prueffrage":"Welche anderen Umstände gab es zur gleichen Zeit, und was hätten sie allein bewirken können?","rueckmeldung":[{"option":1,"text":"Verallgemeinert wird hier nichts: Die Behauptung gilt allein dem Völkermord in Ruanda und schließt nicht auf andere Fälle. Ihr Mangel liegt woanders: Sie verkürzt ein Geschehen mit mehreren Ursachen auf eine einzige."},{"option":2,"text":"Einen Zirkelschluss erkennst du daran, dass die Gewalt als Beleg für die Wirkung der Hetze dient. Das geschieht hier nicht. Die Behauptung steigert vielmehr einen einzelnen Faktor zur alleinigen Ursache."},{"option":3,"text":"Ein Autoritätsargument würde sich auf Rang oder Fachwissen berufen. Der Kommentator tut das nicht, er stellt eine ungeprüfte Behauptung auf. Sie ist deshalb an ihrem Inhalt zu messen, und der blendet die übrigen Ursachen aus."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Human Rights Watch (1999): Leave None to Tell the Story: Genocide in Rwanda, Kap. „Propaganda and Practice“","oeffentlich":true,"url":"https://www.hrw.org/reports/1999/rwanda/Geno1-3-10.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3ca673a5055b0dfd"}},{"id":"qx-b1-058","clusterId":"B","werkstueckRef":"B.16","stufe":3,"question":"Eine Politikerin sagt in einer Talkshow: „Menschen, die ihre Gegner als ‚Ungeziefer‘ bezeichnen, tun das, weil sie sie töten wollen, denn Entmenschlichung ist die Ursache jeder Gewalt.“ Was folgt aus diesen Befunden für ihre Behauptung?","options":["Sie wird bestätigt, denn bei Gewalt aus Nutzen ging Entmenschlichung tatsächlich mit mehr Gewaltbereitschaft einher.","Sie geht zu weit, denn bei Gewalt, die als gerecht empfunden wird, fehlte der Zusammenhang, und das widerlegt „jede Gewalt“.","Sie wird bestätigt, denn auch bei Gewalt, die als gerecht empfunden wird, ging Entmenschlichung mit mehr Bereitschaft einher.","Sie geht zu weit, denn bei Gewalt aus Nutzen fehlte der Zusammenhang mit Entmenschlichung, und das widerlegt „jede Gewalt“."],"correctIndex":1,"explanation":"Die Behauptung verallgemeinert: Aus „Entmenschlichung kommt bei manchen Gewalttaten vor“ wird „sie erklärt jede Gewalt“. Gegen eine solche Allaussage genügt eine Gewaltart ohne den Zusammenhang, und die zeigte sich hier: Bei Gewalt, die als gerecht empfunden wird, ging Entmenschlichung nicht mit mehr Bereitschaft einher, bei Gewalt aus Nutzen dagegen schon. Daraus folgt aber nicht, dass Entmenschlichung gar keine Rolle spielt. Zwei Grenzen gehören dazu: Gemessen wurden Einstellungen und gedachte Szenarien, keine Taten, und Entmenschlichung nur als abgesprochenes Denken und Fühlen, nicht als Tiervergleich wie „Ungeziefer“. „Jede Gewalt“ ist also zu stark, „keine Gewalt“ wäre es ebenfalls. Dass Entmenschlichung bei Gewalt aus Nutzen mit mehr Bereitschaft einherging, ist richtig, bestätigt die Behauptung aber nicht, weil sie für jede Gewalt gelten soll. Die Richtung ist eindeutig: Der Zusammenhang zeigte sich bei Gewalt aus Nutzen, bei als gerecht empfundener Gewalt fehlte er.","coreRule":"⚡ Wer „jede“ oder „immer“ behauptet, braucht nur einen gut belegten Gegenfall zu fürchten: Entmenschlichung erklärt nicht jede Gewalt, denn wer „gerecht“ bestrafen will, braucht einen vollen Menschen als Ziel.","beleg":"Werkstück B.16 (Hinweis zur Beleglage); Fn. gl-b-rai (Rai/Valdesolo/Graham 2017, PNAS 114(32), S. 8511–8516); Fn. gl-b-kteily-folter (Kteily u. a. 2015, JPSP 109(5), S. 901–931)","status":"entwurf","scenario":"In Experimenten und Befragungen mit Online-Teilnehmern (Einstellungsfragen und gedachte Szenarien, keine echten Täter) wurde die Bereitschaft zu zwei Arten von Gewalt erhoben: Gewalt aus Nutzen (etwa einem Fremden für Geld schaden) und Gewalt, die als gerecht empfunden wird (etwa Strafe für ein Fehlverhalten). Entmenschlichung wurde dabei als abgesprochene Fähigkeit zu denken und zu fühlen gemessen. Ergebnis: Wer ein Opfer stärker entmenschlichte, war eher zu Gewalt aus Nutzen bereit. Bei Gewalt, die als gerecht empfunden wird, zeigte sich dieser Zusammenhang nicht; wer sich vorstellte, einen Fremden für sein Fehlverhalten zu bestrafen, hielt ihn sogar für menschlicher.","kurz":"Eine Allaussage wie „jede Gewalt“ scheitert schon an einer Gewaltart ohne den Zusammenhang, und bei als gerecht empfundener Gewalt fehlte er. Der Fehler ist, aus Fällen, in denen etwas vorkommt, auf „immer“ zu schließen.","prueffrage":"Wie wurden Gewaltbereitschaft und Entmenschlichung in den Studien gemessen, und wie nah ist das an dem, wovon die Politikerin spricht?","rueckmeldung":[{"option":0,"text":"Bei Gewalt aus Nutzen stimmt der Zusammenhang, und das ist ein echter Befund. Die Behauptung soll aber für jede Gewalt gelten, und dafür trägt ein Teilbefund nicht, zumal die Studie Einstellungen misst und nichts darüber sagt, ob Menschen jemanden töten wollen."},{"option":2,"text":"Hier ist der Befund ins Gegenteil gedreht. Bei als gerecht empfundener Gewalt zeigte sich gerade kein Zusammenhang, wer bestrafen wollte, hielt den Fremden sogar für menschlicher. Genau das macht die Allaussage angreifbar."},{"option":3,"text":"Der Gedanke, dass eine Ausnahme gegen eine Allaussage genügt, ist richtig, aber die Gewaltarten sind vertauscht. Bei Gewalt aus Nutzen zeigte sich der Zusammenhang, bei als gerecht empfundener Gewalt fehlte er."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Rai, T. S.; Valdesolo, P.; Graham, J. (2017): Dehumanization increases instrumental violence, but not moral violence. PNAS 114(32), 8511–8516 (frei in PMC5559031)","oeffentlich":true,"doi":"10.1073/pnas.1705238114","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6d3a5dd0e9b94a55"}},{"id":"qx-b1-059","clusterId":"B","werkstueckRef":"B.16","stufe":4,"question":"Welche Beurteilung wird dieser Sprache am besten gerecht?","scenario":"In einem Forum lest ihr Kommentare, die eine Gruppe von Menschen durchgehend „Ungeziefer“ und „Seuche“ nennen und von der „Säuberung“ der Gesellschaft sprechen. Zu Gewalt wird nirgends ausdrücklich aufgerufen. Eine Mitleserin meint: „Das ist doch nur Wut, das darf man nicht so ernst nehmen.“","options":["Es ist Ärger ohne Folgen, denn ohne ausdrücklichen Aufruf zu Gewalt lässt sich aus der Wortwahl nicht mehr als Wut ablesen.","Es ist bereits eine Gewalttat, denn Wörter wie „Seuche“ und „Säuberung“ schaden der Gruppe genauso wie ein körperlicher Angriff.","Es ist ein Warnsignal, denn die Gleichsetzung einer ganzen Gruppe mit Ungeziefer senkt die Hemmung vor Gewalt, auch ohne offenen Aufruf.","Es zeigt, dass die Schreibenden gewalttätig sind, denn wer andere so nennt, wird mit hoher Wahrscheinlichkeit auch selbst zuschlagen."],"correctIndex":2,"explanation":"Entscheidend ist, was die Sprache bewirkt, nicht ob sie einen ausdrücklichen Aufruf enthält. Ein einzelner Spruch wie „fauler Hund“ ist nur die mildeste Form der Entmenschlichung. Wird dagegen eine ganze Gruppe durchgehend mit Ungeziefer gleichgesetzt, als Seuche beschrieben und ihre Beseitigung als „Säuberung“ gerahmt, ist das etwas anderes: Sie wird aus dem Kreis derer herausgenommen, denen man moralische Rücksicht schuldet. Das kann Gewalt erleichtern, weil die Hemmung, Menschen zu schaden, bei „Ungeziefer“ weniger greift; nicht jede Gewalt erklärt sich allerdings so. In Ruanda 1994 gingen Monate der Hetze gegen „Kakerlaken“ dem Völkermord voraus. Die Sprache allein erklärt solche Taten nicht, denn Angst, Krieg und organisierte Mobilisierung kamen hinzu, aber sie lieferte die Wörter, die das Töten leichter machten. Die Einordnung als Warnsignal beurteilt die Sprache, nicht die Person, die sie benutzt. Dass kein ausdrücklicher Aufruf vorliegt, stimmt, hilft aber nicht weiter, denn die Vorbereitung geschieht meist unterhalb des Aufrufs. Wörter können verletzen, doch sie sind keiner Tat gleichzusetzen; die Einordnung fragt, was sie bewirken können. Und von der Wortwahl lässt sich nicht sicher auf das künftige Handeln einzelner Schreibender schließen.","coreRule":"⚡ Wird eine ganze Gruppe durchgehend mit Ungeziefer gleichgesetzt und ihre Beseitigung als „Säuberung“ gerahmt, ist das ein Warnsignal, auch wenn kein offener Gewaltaufruf fällt.","beleg":"Werkstück B.16 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Entscheidend ist, was solche Sprache bewirken kann, nicht ob sie ausdrücklich zu Gewalt aufruft. Wird eine ganze Gruppe als Ungeziefer und Seuche gerahmt, kann das die Hemmung senken, ihr zu schaden. Wut allein erklärt das nicht.","prueffrage":"Gegen wen richten sich die scharfen Wörter: gegen Meinungen und Handlungen oder gegen Menschen allein wegen ihrer Zugehörigkeit?","rueckmeldung":[{"option":0,"text":"Dass kein Aufruf vorkommt, stimmt. Die Frage ist aber, was die Wörter bewirken können: Vorbereitung geschieht meist unterhalb des Aufrufs, und durchgängige Entmenschlichung ist mehr als Dampf ablassen."},{"option":1,"text":"Wörter können tatsächlich verletzen und schaden. Gleichsetzen lassen sie sich mit einem körperlichen Angriff aber nicht. Das Gewicht dieser Sprache liegt darin, was sie bewirken kann, nämlich die Hemmung vor Gewalt zu senken."},{"option":3,"text":"Die Sprache ist ernst zu nehmen, doch von der Wortwahl lässt sich nicht sicher auf das Handeln einzelner Schreibender schließen. Beurteilt wird, was die Sprache bewirken kann, nicht, was in den Schreibenden vorgeht."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Human Rights Watch (1999): Leave None to Tell the Story: Genocide in Rwanda, Kap. „Propaganda and Practice“","oeffentlich":true,"url":"https://www.hrw.org/reports/1999/rwanda/Geno1-3-10.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Haslam, N. (2006): Dehumanization: An Integrative Review. Personality and Social Psychology Review 10(3), 252–264 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/16859440/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Over, H. (2021): Seven Challenges for the Dehumanization Hypothesis. Perspectives on Psychological Science 16(1), 3–13 (frei in PMC7809340)","oeffentlich":true,"doi":"10.1177/1745691620902133","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c37f1fba0ebce30b"}}]`);export{t as n,n as t};